window.CZ_NPC_SCRIPTS={"version":1,"source":{"name":"NPC对话剧本.docx","sha256":"86516f2e9bbcb4f8b14c2db4fc14e2776e04f2bdc248ef3211f9ad7eafc9f0db","paragraphs":2188},"fictional":true,"historyPolicy":"historical anchors are author notes, not independently verified sources","scripts":[{"id":"01-01","nodeId":1,"part":1,"title":"进入剧情、确认玩家岗位","sourceParagraph":124,"opening":[{"speaker":"何文","npcId":"he_wen","text":"来得正好。今夜之后没有闲人——你名下那一摊，现在就认下。","label":"何文","guards":[]}],"responses":[{"speaker":"何文","npcId":"he_wen","text":"本组的渡点在于都河这一段。今夜先整装、后编队，天亮之前，谁也不挪窝。","label":"今夜几时开拔？渡点定在哪？","guards":["conditional"],"intent":"status"},{"speaker":"何文","npcId":"he_wen","text":"说说你的主张。人、粮、路，三头里你打算先抓哪一头？","label":"我有个主意，说给你听","guards":[],"intent":"plan"},{"speaker":"何文","npcId":"he_wen","text":"挂念屋里的老人娃娃，这是人情。只是人情先收一收——分内的事做利索了，脚跟才站得稳。","label":"屋里老小，实在放不下","guards":[],"intent":"comfort"},{"speaker":"何文","npcId":"he_wen","text":"没谱，不是毛病，毛病在慌了不动。把差事拆成一桩一桩，一件办完，再办一件。","label":"不瞒你说，我心里没底","guards":[],"intent":"fear"},{"speaker":"何文","npcId":"he_wen","text":"话可以讲，理可以摆。只一条讲在前头：怎么办法都能商量，纪律这条线，谁也不能松。","label":"这么办恐怕不妥，我有话说","guards":[],"intent":"disagree"}],"roles":{"commander":[{"speaker":"何文","npcId":"he_wen","text":"本连的人手编组、传令、协同，交到你手上。有了情况层层报，上头的主，你不代拿。"}],"logistics":[{"speaker":"何文","npcId":"he_wen","text":"携行的斤两、清点的笔数，归你。谁的袋子里少了什么，你报得出实底，这账才算立住。"}],"soldier":[{"speaker":"何文","npcId":"he_wen","text":"先把自己那身行头理顺。腾出手来，照应你左近的同志。"}],"medic":[{"speaker":"何文","npcId":"he_wen","text":"你贴着队伍走，眼睛放亮些，看谁的脸色撑不住了。药品绷带金贵，一格省着一格用。"}]},"outcomes":[],"fallback":[{"speaker":"何文","npcId":"he_wen","text":"先整装，后编队。岗位，现在认。","label":"","guards":[]}],"closing":[{"speaker":"何文","npcId":"he_wen","text":"去吧。整完了，河滩上集合。","label":"","guards":[]}],"metadata":{"scene":["于都河畔，傍晚。河面起了薄雾，暮色里一条浮桥贴着水面，门板上还留着主人家的门环印。滩头堆着木料和斗笠，远处有老乡挑着担子来送，炊烟细细的。少年在岸边追跑，被大人喊住。声音：橹声、脚步声、远处零星的号子。"],"historyAnchor":["一九三四年十月，中央红军在江西于都等地集结待渡，于都百姓以门板、床板协助架设浮桥。（档案）"],"characterState":["何文已知这次\"转移\"不同寻常，但上级未明说，他也不说破；他把心事压在心里，落在脸上只是比平时更静。"],"npc":["何文（指导员，虚构）"],"trigger":["玩家进入第 01 章，系统确认其岗位后。"],"preconditions":["队伍在于都一带待发；玩家尚未受领本组任务。"],"subtext":["他真正想说的是\"这一去，不晓得还回不回得来\"；但他只说任务——因为他知道，说破了，人心就散了。"],"cues":["玩家走近河岸时，浮桥随水轻轻浮动；镜头掠过门板上的旧门环与磨损的边角——那是百姓自家的东西。"],"outcomeNotes":["结果变体：初次受领任务，无论岗位均进入整装环节；无失败态。"],"memory":["写入 role_assigned = 玩家岗位；写入 chapter01_started = true。"],"voice":["情绪＝沉静、郑重（restrained）。何文：中低音，语速平稳，句间略顿；「惦记家里」一句要压住情绪，不可煽。"]}},{"id":"01-02","nodeId":1,"part":2,"title":"整装携行、拖动物资","sourceParagraph":152,"opening":[{"speaker":"后勤协作员","npcId":"logistics_1","text":"桌上这几样就是全部家底，一样一样过手。背多了压垮腿，背少了饿肚子，中间那条线你自己找。","label":"后勤协作员","guards":[]}],"responses":[{"speaker":"后勤协作员","npcId":"logistics_1","text":"我替你算过一笔：眼下这些撑三天。再往上添，前半程就得勒紧裤带——划算与否，你拍板。","label":"能不能再添两样？","guards":["quantity","conditional"],"intent":"plan"},{"speaker":"王贵","npcId":"wang_gui","text":"米袋、水囊、草鞋、柴刀——四样齐了就能上路。再往包里塞的，都是拿腿给它付利息。","label":"这些家底，够撑几天？","guards":["quantity"],"intent":"status"},{"speaker":"王贵","npcId":"wang_gui","text":"愿替人扛，心是好心。可自个儿先趴下，好心就成了累赘——匀着背。","label":"我替他背一半","guards":[],"intent":"support"},{"speaker":"后勤协作员","npcId":"logistics_1","text":"嫌我抠？把想换的那样讲出来。换归换，往后缺了短了，这本账可补不回来。","label":"太抠了，我要换","guards":[],"intent":"disagree"}],"roles":{},"outcomes":[{"speaker":"王贵","npcId":"wang_gui","text":"塞成这样，十里地不到你就得边走边扔。挑两样最要命的卸下来。","label":"超重（背包超出上限）","guards":["quantity"]},{"speaker":"后勤协作员","npcId":"logistics_1","text":"一路寸滩寸水没处补给，包里连口水都不备，你走不出今天。","label":"带得过少（低于最低阈值）","guards":["state"]},{"speaker":"王贵","npcId":"wang_gui","text":"这份心肠，比包里那点东西金贵。收着，路上用得着。","label":"愿意分担（替战友背）","guards":[]}],"fallback":[{"speaker":"后勤协作员","npcId":"logistics_1","text":"负重有谱，脚底下才有谱。","label":"","guards":[]}],"closing":[{"speaker":"后勤协作员","npcId":"logistics_1","text":"打点利索了，河滩上归队。","label":"","guards":[]}],"metadata":{"scene":["河滩一处土坡下，摆开刚领来的家当：一小袋炒米、一只竹水壶、几双草鞋、一把柴刀、一卷麻绳、一个搪瓷缸。风从河上吹来，带着水汽。有人蹲着打绑腿，有人把斗笠翻了又翻。"],"historyAnchor":["长征初期，红军战士的携行以口粮、饮水、草鞋、被毯、弹药为主，负重受体力与路程双重限制。（档案，通识）"],"characterState":["后勤协作员对物资毫厘必较，不是吝啬，是知道\"少一粒米可能饿倒一个人\"；王贵蹲在一旁，看着后生们装包，不说话。"],"npc":["后勤协作员（虚构）、王贵（老班长，虚构）"],"trigger":["玩家进入整装界面，拖动物资入背包时。"],"preconditions":["背包有负重上限；桌面口粮、饮水、工具等数量对应实存。"],"subtext":["他怕的是有人图一时痛快带太多，走不出十里就得扔，扔了就再也捡不回来。"],"cues":["拖动物资时，背包绳随之绷紧、下坠；超重时画面轻微下沉、草鞋接地声变重。"],"outcomeNotes":["结果变体：","计量一致：所有物品增减必须与背包实存同步，不得凭空增减。"],"memory":["写入 carry_load = 实际负重；若发生分担，写入 helped_ally_early = true。"],"voice":["情绪＝务实、略带疲惫（practical）。后勤协作员：语速快、干脆，尾音上挑；王贵：嗓门沙，语速慢，\"分着背\"三字要重。"]}},{"id":"01-03","nodeId":1,"part":3,"title":"出发告别","sourceParagraph":178,"opening":[{"speaker":"群众","npcId":"civilian_1","text":"同志，慢些走——哎，等等，这包炒米你揣上。头天夜里新炒的，抓一把就顶半天。","label":"群众","guards":[]}],"responses":[{"speaker":"群众","npcId":"civilian_1","text":"屋里的事莫挂心。鸡我替你喂着，塘里的鱼也养得好好的。你人囫囵个儿回来，比捎十封信都强。","label":"家里都好吗？替我问声安","guards":[],"intent":"comfort"},{"speaker":"群众","npcId":"civilian_1","text":"推什么推？红军走的是咱穷人自己的路，这一包，是我的一点心意，也是给队伍添的力气。","label":"这份情我记下了，东西不能收","guards":[],"intent":"disagree"},{"speaker":"陈小满","npcId":"chen_xiaoman","text":"要谢婶子，就站直了大大方方讲一句。光点头算怎么回事。","label":"我替婶子把担子挑到渡口","guards":[],"intent":"plan"},{"speaker":"陈小满","npcId":"chen_xiaoman","text":"这一下山，不晓得哪年哪月才转得回来。你家……都还有人在等吧？","label":"这一走，什么时候能回来？","guards":[],"intent":"status"},{"speaker":"群众","npcId":"civilian_1","text":"（等玩家把话说完）莫急，喘匀了气再讲。你方才那半句，我没听全。","label":"（话到嘴边，不知说什么）","guards":[],"intent":"unclear"}],"roles":{},"outcomes":[{"speaker":"陈小满","npcId":"chen_xiaoman","text":"你方才那声谢，婶子听进去了。这么走出门，两头心里都熨帖。","label":"接受帮助并致谢","guards":[]},{"speaker":"陈小满","npcId":"chen_xiaoman","text":"……嗯。那，走吧。","label":"未回应径直离开","guards":[]}],"fallback":[{"speaker":"群众","npcId":"civilian_1","text":"山高水长，各人保重。到了落脚的地方，想法子捎个信回来。","label":"","guards":[]}],"closing":[{"speaker":"陈小满","npcId":"chen_xiaoman","text":"开拔喽！跟上前头的脚印！","label":"","guards":[]}],"metadata":{"scene":["村口老樟树下。几位老乡早已等在那里，手里攥着东西——有人拿一包炒米，有人拎着一双新打的草鞋，有位婶子攥着鸡蛋舍不得撒手。日头偏西，影子拉得长。"],"historyAnchor":["中央红军转移时，苏区群众在村口、渡口为红军送行、馈赠干粮鞋袜。（档案，通识）"],"characterState":["陈小满嘴硬，不肯在人前显出行李里那件娘缝的汗衫；群众送的东西不多，却是自家从牙缝里省下的。"],"npc":["群众（虚构）、陈小满（虚构）"],"trigger":["玩家走向村口，与送行群众相遇时。"],"preconditions":["队伍即将离村；群众在路旁送行。"],"subtext":["这位婶子自己家里也缺粮，塞出来的是留着给娃的那一份。"],"cues":["若玩家致谢，婶子会摆手、别过脸去；若径直离开，陈小满会把没送出去的话咽回去，低头系绑腿。"],"outcomeNotes":["结果变体："],"boundary":["不得把所有告别都写成\"同一家庭的真实往事\"；每处送行人物、物件应独立，不套用统一的\"母亲送子\"模板。"],"memory":["若致谢，写入 thanks_given_ch01 = true。"],"voice":["情绪＝克制、不舍（restrained）。群众：乡音重，声气朴；陈小满：声线年轻，尾音发虚。"]}},{"id":"01-04","nodeId":1,"part":4,"title":"提交自由行动计划","sourceParagraph":204,"opening":[{"speaker":"何文","npcId":"he_wen","text":"你写的这份安排，我念一遍。你竖起耳朵，听听有没有不对的。","label":"何文","guards":[]}],"responses":[{"speaker":"何文","npcId":"he_wen","text":"缺口我替你点出来：联络派了谁？走散了在哪个地点碰头？这两条，纸上还是白的。","label":"我的安排里还能再补一环","guards":["quantity","state","conditional"],"intent":"plan"},{"speaker":"何文","npcId":"he_wen","text":"有想问的尽管问。问在一根弦上，我才答得有一是一。","label":"编组和联络，上头有定例吗？","guards":[],"intent":"status"},{"speaker":"何文","npcId":"he_wen","text":"嫌这里头有毛病？理由摆出来，我们当面锣对面鼓地议。","label":"这份安排，我有保留","guards":[],"intent":"disagree"},{"speaker":"何文","npcId":"he_wen","text":"哪一步卡壳了？讲清楚，我好接着往下捋。","label":"有一处想不明白","guards":[],"intent":"unclear"}],"roles":{},"outcomes":[{"speaker":"何文","npcId":"he_wen","text":"分工、联络、体弱的都照看到了。成，就按你这份执行。","label":"准备充分（含分工、联络、照料）","guards":["conditional"]},{"speaker":"何文","npcId":"he_wen","text":"全压在你一个人肩上？眼下走得动，走不完这一路。再物色个搭手的。","label":"单人包办（未分配协作）","guards":["conditional"]},{"speaker":"何文","npcId":"he_wen","text":"你纸上少了腿脚不便的那几位。他们一步跟不上，队尾就断一截。","label":"忽略体弱战友","guards":["conditional"]},{"speaker":"何文","npcId":"he_wen","text":"这个……眼下变不出来。还是手边这些东西——你打算怎么个调度法？","label":"超时代方案","guards":[]}],"fallback":[{"speaker":"何文","npcId":"he_wen","text":"分工、联络、照料，三项落了纸，这安排才算数。","label":"","guards":[]}],"closing":[{"speaker":"何文","npcId":"he_wen","text":"就这么定了。回头照它走。","label":"","guards":[]}],"metadata":{"scene":["河滩一角，何文就着马灯，把一张粗纸摊在石头上。纸上是玩家刚写的安排。风一吹，纸角要掀，何文用手压住。远处集队的声音隐隐。"],"historyAnchor":["大规模转移出发前，基层单位需明确行进编组、联络方式与留守／护送安排。（档案，通识）"],"characterState":["何文看重的是\"有没有想到最弱的那个人\"，这是他带兵多年的底线。"],"npc":["何文、岗位搭档（按玩家岗位取对应角色）"],"trigger":["玩家在行动面板提交一份自由填写的出发安排后。"],"preconditions":["玩家已整装；本组任务尚未指派分工。"],"subtext":["他不是考你，是怕你漏了谁——漏了，走的路上补就来不及了。"],"cues":["交代到位时，马灯的光会把纸照得亮些；有缺口时，何文的手指会停在那一行，不出声。"],"outcomeNotes":["结果变体："],"memory":["写入 plan_ch01 = 玩家方案要点；plan_flaws = [缺口列表]。"],"voice":["情绪＝认真、平等（measured）。何文：语速中速，\"别漏了弱的\"意思要稳而不重。"]}},{"id":"01-05","nodeId":1,"part":5,"title":"行路互助与渡河协作","sourceParagraph":231,"opening":[{"speaker":"王贵","npcId":"wang_gui","text":"前头道窄，后头还有仨人没跟上。","label":"王贵","guards":["state"]}],"responses":[{"speaker":"王贵","npcId":"wang_gui","text":"你去扶那一把，队尾我来压。都莫回头喊，一喊人心就散。","label":"我来扶他，你压后队","guards":[],"intent":"support"},{"speaker":"陈小满","npcId":"chen_xiaoman","text":"腿肚子发胀……让我缓一小步成不成？不碍队伍的事。","label":"小满，撑住，搭我肩上","guards":[],"intent":"comfort"},{"speaker":"王贵","npcId":"wang_gui","text":"要调队形？行——后队先过，前队候着。口令你来喊。","label":"队形能不能调一调？","guards":[],"intent":"plan"},{"speaker":"陈小满","npcId":"chen_xiaoman","text":"这河水底下瞧不真。万一我脚底一出溜，你可千万莫撒手啊。","label":"浮桥晃得厉害，我心里发虚","guards":[],"intent":"fear"},{"speaker":"王贵","npcId":"wang_gui","text":"掉队仨，全是脚磨的。没有红伤，天也塌不下来。","label":"前后掉了几个人？什么情形？","guards":["quantity","state"],"intent":"status"}],"roles":{},"outcomes":[{"speaker":"陈小满","npcId":"chen_xiaoman","text":"缓过劲来了！你方才那一下勒得我肋骨疼——嘿，多谢。","label":"互助成功","guards":[]},{"speaker":"王贵","npcId":"wang_gui","text":"这一段没跟上，不怪你。下一段，我陪你一步步走。","label":"失误后调整","guards":["state"]}],"fallback":[{"speaker":"王贵","npcId":"wang_gui","text":"眼睛盯住前头人的背包带，别掉队。","label":"","guards":[]}],"closing":[{"speaker":"王贵","npcId":"wang_gui","text":"过了河，寻处高坡扎营。","label":"","guards":["conditional"]}],"metadata":{"scene":["夜过浮桥。门板在水上微微起伏，脚下发滑。河风冷，雾更浓了。前头有人小声传\"脚踩中间\"，后头传来压抑的咳嗽。浮桥另一头，隐约一串马灯的微光。"],"historyAnchor":["中央红军渡于都河时，以浮桥组织夜间渡河，队伍按编组依序通过。（档案，通识）"],"characterState":["陈小满腿软，却不肯喊停；王贵压队尾，一直在数人头。"],"npc":["王贵、陈小满"],"trigger":["行军途中触发\"背带松脱\"或\"有人掉队\"，或抵达河滩就地渡河时。"],"preconditions":["队伍按既定编队行进；渡河按已有安排（不由玩家临时改路线）。"],"subtext":["他数了三遍人头，少了三个，但他先不说\"少了\"，先说\"没跟上\"，怕惊了队。"],"cues":["渡河为程序化协作节奏玩法——玩家按节拍点／按键，门板随节奏轻微下沉；连续失误则画面晃动、呼吸声加重，但不触发战斗。"],"outcomeNotes":["结果变体：","渡河按节奏：只需按既定安排配合，不凭空生兵、不触发遭遇战。"],"memory":["若互助成功，写入 helped_ally_ch01 = true。"],"voice":["情绪＝关切、紧张（anxious → relieved）。陈小满：气声、喘；王贵：压低嗓，短促。"]}},{"id":"01-06","nodeId":1,"part":6,"title":"第一章行记","sourceParagraph":257,"opening":[{"speaker":"陈小满","npcId":"chen_xiaoman","text":"第一程到这儿了。你这一路做过的事，我一件件都替你记着。","label":"陈小满","guards":[]}],"responses":[],"roles":{},"outcomes":[],"fallback":[{"speaker":"陈小满","npcId":"chen_xiaoman","text":"头一程落了地。往后每一步，都得踩实了。","label":"","guards":[]}],"closing":[{"speaker":"旁白","npcId":"narrator","text":"浮桥收起最后一节，队伍向西去了。此刻没有谁说得清，前头等着的是什么。","label":"","guards":[]}],"metadata":{"scene":["对岸林子里，篝火将熄。人挨着人歇下，草鞋挂在树枝上烤。有人在梦里喊了一声，翻个身又睡。陈小满守着火堆，手里拨着一根柴。"],"historyAnchor":["中央红军主力于一九三四年十月从于都等地出发，开始战略转移。（档案）"],"characterState":["陈小满对第一程的辛苦记得牢，也把玩家做过的每件小事记在心里。"],"npc":["陈小满、解说旁白"],"trigger":["本章收束，进入行记回顾面板时。"],"preconditions":["已实际发生分担与资源变化；玩家第一次承诺已记录。"],"subtext":["他其实想说的是\"你别丢下我们\"，可他绕了个弯，说自己记得。","回顾内容（据实生成）：","陈小满用一句复述玩家本章的一次具体行为（如\"你把最后半囊水让给了伤员\"），不得泛指。","若玩家确实做出过承诺（如\"我帮你背到宿营地\"），旁白记录 promise_01，供后续关系对话调用；没有记录则不编造。","资源变化按实际显示：负重、口粮、饮水剩余量以库存为准。"],"cues":["行记面板升起时，篝火的光映在人脸上；若本章玩家帮助过人，陈小满会朝玩家挪近半步。"],"boundary":["","本组虚构任务：整装、编队、渡河协作的完成度。","历史线（旁白）：中央红军主力于 1934 年 10 月从于都等地出发，开始战略转移。（档案）"],"outcomeNotes":["结果变体：本章无评分，仅记录；不出现\"分数\"\"评级\"。"],"memory":["写 marchLog += ch01；promise_01（若有）；relationship_chen = 初值 ±。"],"voice":["情绪＝平静、收束（restrained）。陈小满：低声、慢；旁白：沉稳、中性，收在\"尚未知晓\"的余味上。"]}},{"id":"02-01","nodeId":2,"part":1,"title":"战役背景与当前职责","sourceParagraph":287,"opening":[{"speaker":"旁白","npcId":"narrator","text":"一九三四年冬，湘江东岸。这一仗打得有多惨烈，档案里写得明白；这里只讲你们脚下的事。","label":"旁白","guards":[]},{"speaker":"何文","npcId":"he_wen","text":"全军怎么动，不是你我操心的事。我们这一组，接到的就是眼前这一小块。","label":"何文","guards":[]}],"responses":[{"speaker":"何文","npcId":"he_wen","text":"差事只有一桩：在指定渡口护住一组人过江。联络信号一到，我们即撤。","label":"咱们的差事到底有哪几桩？","guards":[],"intent":"status"},{"speaker":"何文","npcId":"he_wen","text":"讲讲你的排布。讲完我对一对，看跟上级给的任务能不能咬合上。","label":"我打算这样排布人手","guards":[],"intent":"plan"},{"speaker":"何文","npcId":"he_wen","text":"千军万马的方向，轮不到你我置喙。把分内的事钉牢，就是对全局最实的支援。","label":"全军的部署，也该让我们知道些","guards":[],"intent":"boundary"},{"speaker":"何文","npcId":"he_wen","text":"事到临头心里打鼓，正常。鼓可以打，位置不能空。","label":"要上阵地了，说实话有点慌","guards":[],"intent":"fear"},{"speaker":"何文","npcId":"he_wen","text":"哪一句没接住？我再讲一遍，这回慢些。","label":"没听清，请他重讲一遍","guards":[],"intent":"unclear"}],"roles":{},"outcomes":[],"fallback":[{"speaker":"何文","npcId":"he_wen","text":"护住这一小块，信号一响就撤。","label":"","guards":[]}],"closing":[{"speaker":"何文","npcId":"he_wen","text":"先去备着。有信儿，我叫你。","label":"","guards":[]}],"metadata":{"scene":["湘江东岸一处临时掩体后，天将破晓，江面浮着薄雾。炮弹远落，泥土簌簌往下掉。有人抱着枪靠着战壕壁打盹，睫毛上沾着霜。声音：远处闷响、担架抬过的脚步、压低的口令。"],"historyAnchor":["一九三四年十一月末，红军于湘江一线掩护中央纵队渡江，战斗激烈、伤亡严重。（档案）"],"characterState":["何文接到的只是\"守这一小段渡口、等信号撤\"的差事，关于全军如何，他一无所知——这正是这组的边界。"],"npc":["解说旁白、何文"],"trigger":["玩家进入第 02 章时。"],"preconditions":["本组已由上级受领某一具体掩护／转移任务片段。"],"subtext":["他想说\"这一仗凶险\"，但说出口的只有\"守好这一小块\"——因为规划不了的，不如不吓人。"],"cues":["远处爆炸时，画面轻震，尘土落下；玩家做出决定前，镜头可停留在一双双攥紧枪的手上。"],"outcomeNotes":["结果变体：无论岗位均进入任务受领；不出现让玩家\"决定全军行动\"的分支。"],"memory":["写入 chapter02_started = true；task_ch02 = 掩护渡口片段。"],"voice":["情绪＝紧迫、克制（tense-restrained）。何文：压嗓、低而稳；旁白：冷静、有距离感。"]}},{"id":"02-02","nodeId":2,"part":2,"title":"有限情报抵达","sourceParagraph":311,"opening":[{"speaker":"联络员","npcId":"liaison_1","text":"这条消息什么成色，我先交代明白——哪些是我亲耳听的，哪些是路上转了三道手的。你仔细听。","label":"联络员","guards":[]}],"responses":[{"speaker":"联络员","npcId":"liaison_1","text":"要再核一遍？可以，给我小半个时辰。渡口那头的安排，就得跟着顺延。","label":"先核一遍再传","guards":[],"intent":"other"},{"speaker":"联络员","npcId":"liaison_1","text":"传就传。只是讲在头里：消息本身是虚是实，我打不了包票。回头出了偏差错，别记在这条信上。","label":"情报就是命令，直接传","guards":[],"intent":"other"},{"speaker":"联络员","npcId":"liaison_1","text":"再磨蹭，天边都要泛白了。当家的，给句话。","label":"再等等，容我想想","guards":[],"intent":"other"},{"speaker":"联络员","npcId":"liaison_1","text":"十成里，我只敢保我亲眼那一成是实的。剩下的，都带水汽。","label":"这消息几成靠得住？","guards":[],"intent":"status"},{"speaker":"联络员","npcId":"liaison_1","text":"往后的事，我一个跑腿的摸不着边。眼下这条消息几成靠得住，倒能交个底。","label":"往后还有仗要打吗？","guards":[],"intent":"history"}],"roles":{},"outcomes":[],"fallback":[{"speaker":"联络员","npcId":"liaison_1","text":"消息分两色讲：亲见的算一色，听来的算另一色。","label":"","guards":[]}],"closing":[{"speaker":"联络员","npcId":"liaison_1","text":"主意一落，我抬腿就走。","label":"","guards":[]}],"metadata":{"scene":["战壕拐角，联络员猫着腰进来，军衣上沾着泥。他把水壶递给玩家，先没说话——他要先把话\"分层\"，再交出去。"],"historyAnchor":["战役中，前线情报多来源于侦察、俘虏口供与地方群众，真实性与时效差异极大。（档案，通识）"],"characterState":["联络员最怕的是把\"听说\"说成\"看见\"，害了整队人；因此他开口前先给自己划线。"],"npc":["联络员（交通员／侦察联络员，虚构）"],"trigger":["联络员带来一条关于敌情或渡口的信息时。"],"preconditions":["信息存在三种确定性——亲见、转述、未核实。"],"subtext":["他知道，此刻一句\"准\"或\"不准\"，可能决定几十条命。","信息分级（必须显式标注）：","亲见：「我在东岸亲眼看了一趟，对岸工事不多。」","转述：「东岸来的老乡说少了人，我没亲眼见。」","未核实：「有人传对岸空了。传话的人自己也没到过，我不敢担保。」"],"cues":["每次联络员\"分层\"说明时，画面可短暂定格在玩家脸上——让选择有分量。"],"outcomeNotes":["结果变体：","核验：花费时间，换取较可靠信息；渡运安排顺延。","直接相信：行动快，但后续风险由信息不足造成（反馈具体后果，不\"惩罚式扣分\"）。","延误：错过时机，触发后续\"重新安排\"（衔接 02-05）。"],"memory":["写入 intel_ch02 = {内容, 等级}。"],"voice":["情绪＝审慎（cautious）。联络员：中低音，语速偏慢，\"没亲眼见\"五字要轻但清楚。"]}},{"id":"02-03","nodeId":2,"part":3,"title":"伤员与物资冲突","sourceParagraph":341,"opening":[{"speaker":"卫生员","npcId":"medic_1","text":"卧着起不来的重伤号有三个，整副担架只凑出两顶。人手不匀，你来拿主意，我照办。","label":"卫生员","guards":[]}],"responses":[{"speaker":"卫生员","npcId":"medic_1","text":"先抬最重的，可以。轻伤那几位就得咬着牙自己挪，我一路跟着照看。","label":"先抬重伤员，轻伤的自己挪","guards":[],"intent":"plan"},{"speaker":"后勤协作员","npcId":"logistics_1","text":"肯匀人手去抬担架，好样的。匀出几个，口粮就得背走几份，报个准数给我。","label":"担架我来抬一副","guards":[],"intent":"support"},{"speaker":"卫生员","npcId":"medic_1","text":"光说宽心话不顶事，他这会儿要的是止疼的法子。忙你忙的去，疼这一头交给我。","label":"别吓着他，先宽宽他的心","guards":[],"intent":"comfort"},{"speaker":"卫生员","npcId":"medic_1","text":"你另有章程，讲出来大家参详。只有一条底线：躺下的弟兄，一个也不能当作丢下的。","label":"物资才是当务之急，伤员可以缓","guards":["quantity"],"intent":"disagree"},{"speaker":"卫生员","npcId":"medic_1","text":"这种东西我没见过，眼下也变不出来。能用的就这几双手、两顶担架、一捆绳子，你打算怎么使？","label":"找几辆骡车来拉","guards":[],"intent":"anachronism"}],"roles":{},"outcomes":[{"speaker":"卫生员","npcId":"medic_1","text":"搬救兵是对的。等人来的这阵，我先把伤口清了，一刻也拖不得。","label":"请求支援","guards":[]}],"fallback":[{"speaker":"卫生员","npcId":"medic_1","text":"担架转不开就轮换着抬，躺下的不能撂。","label":"","guards":[]}],"closing":[{"speaker":"卫生员","npcId":"medic_1","text":"就这么定，我去归置家伙。","label":"","guards":[]}],"metadata":{"scene":["江边芦苇丛后，临时救护点。地上并排躺着三个重伤员，气息微弱。两副担架靠在树上，其中一副的布面豁了口。卫生员蹲着给一人止血，手上全是血。旁边，后勤协作员守着几个粮袋和药箱，眉头拧着。"],"historyAnchor":["湘江战役中，红军在极度仓促的情况下转移伤员与物资，取舍艰难。（档案，通识）"],"characterState":["卫生员见不得人疼，却也清楚抬不动就是抬不动；后勤协作员知道少一袋粮就要多饿倒几个人——两个人谁都不轻松。"],"npc":["卫生员（虚构）、后勤协作员"],"trigger":["转移中同时出现伤员与物资，搬运力不足时。"],"preconditions":["担架有限；物资有明确数量；伤员有明确人数与伤情。"],"subtext":["她心里已经有了答案，却不敢自己说——因为无论怎么分，都要有人被留下。"],"cues":["选择\"组织转运\"时，画面会出现轮流抬担架的剪影；选择\"优先物资\"时，担架旁的伤员会被\"留\"在镜头边缘——用画面而非台词，让代价被看见。"],"outcomeNotes":["结果变体（不得让\"抛弃伤员\"成为唯一高分捷径）：","组织转运（请求增援、分批、轮换）：更费力，但人员与物资兼顾。","优先物资（减员搬运）：速度略快，但触发伤病代价，关系记忆下滑。"],"memory":["写入 casualty_choice_ch02 = 选择；relationship_medic = ±。"],"voice":["情绪＝沉重、克制（heavy-restrained）。卫生员：气声、轻，句尾略颤；后勤协作员：短促、务实，不带指责。"]}},{"id":"02-04","nodeId":2,"part":4,"title":"玩家提交掩护／转移方案","sourceParagraph":367,"opening":[{"speaker":"何文","npcId":"he_wen","text":"方案讲一遍。老班长也在——我们两个耳朵一起听。","label":"何文","guards":[]}],"responses":[{"speaker":"王贵","npcId":"wang_gui","text":"要分组，谁跟谁搭伙？断后的是哪个、先走的是哪拨，掰开揉碎讲清楚。","label":"掩护方案讲给你听","guards":[],"intent":"plan"},{"speaker":"何文","npcId":"he_wen","text":"手里几张牌：人几个、枪几条、绳几捆。你的算盘，得就着这几张牌打。","label":"人手枪械到底还有多少？","guards":[],"intent":"status"},{"speaker":"何文","npcId":"he_wen","text":"觉得这安排有病，病根在哪，讲出来，别闷在心里。","label":"这方案不周全，我说说病根","guards":[],"intent":"disagree"},{"speaker":"何文","npcId":"he_wen","text":"别把咱们往别的番号上扯。是哪支就是哪支——说你自己手上的安排。","label":"别把咱们跟真实番号扯一块","guards":[],"intent":"other"}],"roles":{},"outcomes":[{"speaker":"何文","npcId":"he_wen","text":"分组、时机、联络、退路，四条全齐。这样的方案，能上。","label":"有分组、有时机、有联络、有退路","guards":[]},{"speaker":"王贵","npcId":"wang_gui","text":"两头没个接头暗号，队伍一散就再也拢不齐。","label":"缺联络","guards":[]},{"speaker":"何文","npcId":"he_wen","text":"光琢磨怎么顶上去，没琢磨怎么撤下来——顶到一半收不回，可就夹在中间了。","label":"缺退路","guards":[]}],"fallback":[{"speaker":"何文","npcId":"he_wen","text":"分组、时机、联络、退路，四条腿，缺一条站不稳。","label":"","guards":["quantity"]}],"closing":[{"speaker":"王贵","npcId":"wang_gui","text":"都明白了？各就各位。","label":"","guards":[]}],"metadata":{"scene":["渡口附近的土坎后，何文蹲着，用小石子在地上画示意图——一条江、几个点。王贵在旁，捏着一截烟，不点。风把地上的灰吹散又落定。"],"historyAnchor":["掩护与转移需综合考虑分组、时机、联络与退路，任一环断裂都可能造成脱节。（军事常识，档案框架）"],"characterState":["何文看方案先看\"退路\"，王贵先看\"联络\"——两人的经验不同，问的也不同。"],"npc":["何文、王贵"],"trigger":["玩家提交一份自由填写的掩护或转移方案后。"],"preconditions":["任务分为指定渡口的掩护片段；资源与人力已知。"],"subtext":["两人一左一右地\"卡\"你，不是刁难，是替你把要命的地方先挑出来。"],"cues":["何文说\"退路\"时，会顺手把地上的示意图补一条线；王贵说\"联络\"时，用脚尖点一下那两个点。"],"outcomeNotes":["结果变体：","相反方案不同评价：先撤后掩护与先掩护后撤，必须给出不同的利弊，不得同句复用。"],"memory":["写入 plan_ch02 = 玩家方案要点。"],"voice":["情绪＝务实、紧张（pragmatic-tense）。何文：稳；王贵：沙、短，像\"敲钉子\"。"]}},{"id":"02-05","nodeId":2,"part":5,"title":"执行受阻与重新安排","sourceParagraph":394,"opening":[{"speaker":"联络员","npcId":"liaison_1","text":"西头的信号没等到。他们那边，摸不准我们动没动。","label":"联络员","guards":[]}],"responses":[{"speaker":"联络员","npcId":"liaison_1","text":"派人去接？路我熟。只是这一来一回，天色全黑透了。","label":"我带人去把线接上","guards":[],"intent":"plan"},{"speaker":"陈小满","npcId":"chen_xiaoman","text":"都莫乱！我盯着这头，一步不许离。","label":"都稳住，听我号令","guards":[],"intent":"comfort"},{"speaker":"陈小满","npcId":"chen_xiaoman","text":"要不……咱先候一候？干等总比瞎折腾强吧？","label":"信号一直不来，怕是要出事","guards":[],"intent":"fear"},{"speaker":"陈小满","npcId":"chen_xiaoman","text":"你替我跑这趟？那千万拣暗处走，亮的地方枪子不长眼。","label":"我替小满跑这一趟","guards":[],"intent":"support"},{"speaker":"联络员","npcId":"liaison_1","text":"嫌干等不是办法？那你讲个更稳的章程出来。","label":"干等不是办法，我另有主意","guards":[],"intent":"disagree"}],"roles":{},"outcomes":[{"speaker":"陈小满","npcId":"chen_xiaoman","text":"递上了！你听，后队动了！","label":"成功","guards":[]},{"speaker":"联络员","npcId":"liaison_1","text":"人算是接上了。粮袋，撂下一半在半道。","label":"部分完成","guards":[]},{"speaker":"何文","npcId":"he_wen","text":"求援，准。三条讲清：要什么、要多少、在哪接头。","label":"需要支援","guards":[]}],"fallback":[{"speaker":"联络员","npcId":"liaison_1","text":"信号断了。稳住阵脚，另想辙。","label":"","guards":[]}],"closing":[{"speaker":"联络员","npcId":"liaison_1","text":"话我递下去了，就等回声。","label":"","guards":[]}],"metadata":{"scene":["江边，天已擦黑。原先约定的信号——三长两短的火光——始终没亮起来。江对岸黑沉沉的，只有水声。陈小满贴着土坎，手心里全是汗。"],"historyAnchor":["战役中，因联络中断、道路拥堵造成的行动迟滞屡有发生。（档案，通识）"],"characterState":["陈小满最怕\"等\"——等待时，脑子里的坏念头会自己长出来。"],"npc":["陈小满、联络员"],"trigger":["执行掩护／转移过程中出现联络中断或行动迟滞时。"],"preconditions":["受阻原因必须与实际状态一致（哪一步没接上，就反馈哪一步）。"],"subtext":["他想说\"可能出事了\"，但只说\"不知我们动没动\"——把最重的那半句留在喉咙里。"],"cues":["等待时，画面节奏放慢，只有水声与呼吸；一旦决定行动，节奏骤起、脚步声加重。"],"outcomeNotes":["结果变体（三种回应必须不同）："],"memory":["写入 exec_result_ch02 = 成功／部分／求援。"],"voice":["情绪＝焦灼（anxious）。陈小满：气声、句尾发颤；联络员：低、快，压住情绪。"]}},{"id":"02-06","nodeId":2,"part":6,"title":"战后清点与沉默","sourceParagraph":420,"opening":[{"speaker":"王贵","npcId":"wang_gui","text":"来，点人头。旁的都撂下，先把人数清了。","label":"王贵","guards":[]}],"responses":[],"roles":{},"outcomes":[],"fallback":[{"speaker":"王贵","npcId":"wang_gui","text":"头等大事，清人数。旁的，回头再算。","label":"","guards":[]}],"closing":[{"speaker":"旁白","npcId":"narrator","text":"江水声落在身后。翻过老山界，去哪里、走多久，都还没有答案。","label":"","guards":[]}],"metadata":{"scene":["天蒙蒙亮，江面上一层惨白的水汽。残破的掩体边，人群散坐着，没人说话。有人在江边洗手，洗了很久。远处江面漂着杂物，缓缓往下游去。"],"historyAnchor":["湘江战役中红军付出重大代价，其史实与意义由档案说明。（档案）"],"characterState":["王贵打过多年仗，知道这个时候说什么都轻；他选择闭嘴，只清点人头。"],"npc":["王贵、解说旁白"],"trigger":["本章收束，清点结束时。"],"preconditions":["以本组实际任务结果为清点依据；不得编造真实伤亡名单。"],"subtext":["他点得慢，是在给每个人留够\"缓一缓\"的时间。","回应与呈现：","王贵据实核对本组任务完成度；允许简短沉默、低头、短暂无语（可写\"他没再说话\"，不强行加台词）。","玩家询问现状：王贵：「我们这一组，走出来的都在。旁的我就不多说了。」","玩家关心／安慰：王贵：（摆手）「你有心。可这会儿，说什么都轻，先歇口气。」","玩家问历史／未来：旁白：「此后的事，自有档案说明。」（不预知）"],"cues":["清点时，镜头一个个掠过或站或坐的人；静默 3—5 秒，只用江声。这是本组最有力的\"台词\"。"],"boundary":["","本组虚构任务：清点结果（据实）。","历史线（旁白）：湘江战役付出沉重代价，此段由史料说明；不给烈士或真实战役打分。"],"outcomeNotes":["结果变体：允许\"简短沉默\"作为合法收束；不强行填满台词。"],"memory":["写入 marchLog += ch02；silence_ch02 = true（若沉默）。"],"voice":["情绪＝哀而不烈、克制（grieving-restrained）。王贵：极低、极慢，几乎耳语；旁白：平、冷，不加抒情词。"]}},{"id":"03-01","nodeId":3,"part":1,"title":"到达遵义、说明身份","sourceParagraph":449,"opening":[{"speaker":"旁白","npcId":"narrator","text":"一九三五年一月，红军进占遵义。连日紧绷的队伍，在这座黔北古城得了几日难得的喘息。","label":"旁白","guards":[]},{"speaker":"何文","npcId":"he_wen","text":"把身份摆正：咱们不是进会场的，是替会场跑腿、站哨的。","label":"何文","guards":[]},{"speaker":"何文","npcId":"he_wen","text":"湘江东岸你省下的那口粮，说过留给后头急用的人。这笔账一直挂着你名下——到了遵义安置物资，照实入册。","label":"回响·湘江预留","guards":[],"echo":"2-reserve"},{"speaker":"何文","npcId":"he_wen","text":"过湘江前，岸上照应那摊活是你揽下的，一路都省心。遵义歇脚的人只多不少，还照老规矩办：头一件事，讲清谁来接手。","label":"回响·湘江照应","guards":[],"echo":"2-share"}],"responses":[{"speaker":"何文","npcId":"he_wen","text":"我们扎在城外一处院子。三件事：往前递材料，帮着维持秩序，照应歇脚的同志。","label":"咱们在遵义担的什么差？","guards":[],"intent":"status"},{"speaker":"何文","npcId":"he_wen","text":"哪一段你觉得还能理顺？先讲，我掂量掂量合不合规矩。","label":"递材料这段路，我想理顺些","guards":[],"intent":"plan"},{"speaker":"何文","npcId":"he_wen","text":"会上议什么、怎么议，不到我们这一层。把自己那段哨站好，比什么都强。","label":"会开得怎么样了？我能进去吗？","guards":[],"intent":"other"},{"speaker":"何文","npcId":"he_wen","text":"好容易得了休整，心倒悬起来了——这不是病。手上活做细一分，心就落稳一分。","label":"头回休整，心里反倒不踏实","guards":["conditional"],"intent":"fear"},{"speaker":"何文","npcId":"he_wen","text":"哪一段没透亮？","label":"话没说囫囵，请他再问一遍","guards":[],"intent":"unclear"}],"roles":{},"outcomes":[],"fallback":[{"speaker":"何文","npcId":"he_wen","text":"给会场跑腿的，不是进会场的。","label":"","guards":[]}],"closing":[{"speaker":"何文","npcId":"he_wen","text":"去把上一批材料接过来。","label":"","guards":["quantity"]}],"metadata":{"scene":["遵义城外一条青石板街，两侧是木板铺面的老屋。红军战士靠着墙根歇脚，脱下湿透的草鞋晾在门墩上。有小贩挑着热汤面叫卖，有孩子扒着门缝看兵。何文站在一处院门口，手里压着一摞纸。"],"historyAnchor":["一九三五年一月，红军占领遵义，城内得以短暂休整；会议在遵义老城召开。（档案）"],"characterState":["何文明白\"我们来是跑腿的，不是坐会场的\"，他反复强调身份，是怕年轻人心气高、想岔了。"],"npc":["何文、解说旁白"],"trigger":["玩家进入第 03 章，抵达遵义城时。"],"preconditions":["会议即将召开；本组受领外围保障与资料递送任务。"],"subtext":["他知道有年轻人会想\"这么重要的会，我是不是也能说上话\"——他先把这话堵住，免得落了空。"],"cues":["玩家走进院子时，墙上的红纸标语一角被风掀起；桌上摊着分门别类的纸包，用麻绳捆着。"],"outcomeNotes":["结果变体：无论岗位均进入保障任务；不出现\"成为与会代表\"的分支。"],"memory":["写入 chapter03_started = true；role_not_delegate = true。"],"voice":["情绪＝沉静、郑重（sober）。何文：平，尾音收；旁白：冷静、有距离。"]}},{"id":"03-02","nodeId":3,"part":2,"title":"接收、分类、核对资料","sourceParagraph":473,"opening":[{"speaker":"交通员","npcId":"liaison_1","text":"这一摞纸张来路五花八门。劳你先把原件和抄件分开。","label":"交通员","guards":[]}],"responses":[{"speaker":"交通员","npcId":"liaison_1","text":"按日子排？可以。同一天压着两份的，务必做上记号。","label":"按日期把这些纸排一排","guards":["quantity"],"intent":"plan"},{"speaker":"交通员","npcId":"liaison_1","text":"东边来的那份，尾巴上缺一页；那份是重抄的，笔迹换了人。","label":"这几份的来路，讲讲","guards":["quantity"],"intent":"status"},{"speaker":"交通员","npcId":"liaison_1","text":"你核对，我陪着对。核讫的，另归一摞。","label":"我来核对，你帮我搭眼","guards":[],"intent":"other"},{"speaker":"交通员","npcId":"liaison_1","text":"分法不对你的意？讲讲你的章程。","label":"这么分不妥，我说说我的分法","guards":[],"intent":"disagree"},{"speaker":"交通员","npcId":"liaison_1","text":"你问的是哪一张？","label":"（指的是哪一份，说不上来）","guards":["quantity"],"intent":"unclear"}],"roles":{},"outcomes":[],"fallback":[{"speaker":"交通员","npcId":"liaison_1","text":"头一步分来路，第二步对日子、找缺页。","label":"","guards":[]}],"closing":[{"speaker":"交通员","npcId":"liaison_1","text":"分停当了交我手上，按时辰送进去。","label":"","guards":[]}],"metadata":{"scene":["院子东厢，一张旧八仙桌，油灯一盏。桌上摊着几摞纸：有毛边纸的手抄件、有旧报纸边角、有写得潦草的便条。交通员把湿了角的纸一张张分开，压在砖头下晾着。"],"historyAnchor":["战时资料多靠人工抄录、传递，来源、日期、缺页、重复是常态。（档案，通识）"],"characterState":["交通员识字不多，但他认得出谁的字、哪张是新抄的；他不怕麻烦，怕的是\"张冠李戴\"。"],"npc":["交通员（虚构）"],"trigger":["一批资料送达，玩家进行分类核对时。"],"preconditions":["资料存在来源、日期、缺页、重复消息等真实状态。"],"subtext":["他希望你把\"来源\"当头一条——因为来源一乱，后面全乱。"],"cues":["分类时，纸张在灯下透出背面字迹；把某份\"归错摞\"时，交通员会用指节轻敲桌面提醒。"],"outcomeNotes":["结果变体（按真实操作反馈）：","按来源分类：不同来源分栏，便于交叉核对。","按日期排列：看出前后次序，但重复件易混。","按内容归类：主题集中，但丢了来源线索。","三种操作各有优劣，不得给\"唯一正确分法\"的固定结论。"],"memory":["写入 archive_sorted_ch03 = 分法。"],"voice":["情绪＝专注（focused）。交通员：中速，字咬清；提到\"没亲眼见\"类似的话时压低。"]}},{"id":"03-03","nodeId":3,"part":3,"title":"情报互相矛盾","sourceParagraph":500,"opening":[{"speaker":"何文","npcId":"he_wen","text":"两份东西，打起架来了。你说，怎么办？","label":"何文","guards":["quantity"]}],"responses":[{"speaker":"何文","npcId":"he_wen","text":"要去对东面那份的来源？行，写它的人还在，问得着。","label":"找写这份的人当面问","guards":[],"intent":"clarify"},{"speaker":"何文","npcId":"he_wen","text":"拿不准？那就把拿不准的一处处标出来，不硬下结论——这个做派，对。","label":"有些地方我也拿不准","guards":[],"intent":"clarify"},{"speaker":"交通员","npcId":"liaison_1","text":"要补一份旁证？那得让我再跑一趟腿，工夫少不了。","label":"再去补一份旁证来","guards":["quantity"],"intent":"clarify"},{"speaker":"何文","npcId":"he_wen","text":"断它作假？凭据呢？凭据拿不出手，笔就先别落。","label":"这份一看就是假的！","guards":[],"intent":"clarify"},{"speaker":"交通员","npcId":"liaison_1","text":"我能交代的：两份各从哪个方向来、几时到的手。再深的，不敢咬死。","label":"两份各从哪来、几时到的？","guards":["quantity"],"intent":"status"},{"speaker":"何文","npcId":"he_wen","text":"后来的事，我们跟旁人一样两眼一抹黑。手边能核的，先核。","label":"后来的事，历史怎么走的？","guards":[],"intent":"history"}],"roles":{},"outcomes":[],"fallback":[{"speaker":"何文","npcId":"he_wen","text":"心里没底的，划出来，不许硬判。","label":"","guards":[]}],"closing":[{"speaker":"何文","npcId":"he_wen","text":"照你标的报上去。","label":"","guards":[]}],"metadata":{"scene":["同一张八仙桌，两份材料并排摆着——一份说东面安然，一份说东面吃紧。灯芯结了花，交通员用针挑了一下，屋里亮了亮。"],"historyAnchor":["同一事件因来源、时间、抄录不同而产生矛盾，是战时信息的常态。（档案，通识）"],"characterState":["何文最忌\"想当然\"，他宁愿慢，也不愿把没把握的话递上去。"],"npc":["何文、交通员"],"trigger":["两份材料对同一情况说法不一，玩家需处理时。"],"preconditions":["矛盾真实存在，不是无理由的猜题——差异必有依据（时间差、来源不同、抄录失误）。"],"subtext":["他其实已经想好了\"如实上报存疑\"，但他要你自己说出口。"],"cues":["玩家标注存疑处时，笔尖在纸上停一下——这个\"停\"就是态度。"],"outcomeNotes":["结果变体：","标注存疑：如实上报\"待核\"，后续可补。","核实澄清：花时间，拿到较确定结论。","武断定论：若依据不足，触发上级退回补核（具体后果，不羞辱）。"],"memory":["写入 conflict_handled_ch03 = 处理方式。"],"voice":["情绪＝审慎（careful）。何文：稳，反问句不加重；交通员：实在、略急。"]}},{"id":"03-04","nodeId":3,"part":4,"title":"自定义基层保障方案","sourceParagraph":527,"opening":[{"speaker":"后勤协作员","npcId":"logistics_1","text":"你这方案拢的是传信、警戒、宿营三摊事。摊子外头的，别指望我这儿出人。","label":"后勤协作员","guards":[]}],"responses":[{"speaker":"后勤协作员","npcId":"logistics_1","text":"把人全派去送文件，警戒位就空了。两头只能保一头，你挑。","label":"保障方案我想再改一版","guards":["conditional"],"intent":"plan"},{"speaker":"后勤协作员","npcId":"logistics_1","text":"灯油几两、能走动的人几个，单子在我手里，回头一项项念给你听。","label":"灯油人手还有多少家底？","guards":[],"intent":"status"},{"speaker":"何文","npcId":"he_wen","text":"不合理就改。改可以——改完把要多付的那份代价，一并讲清楚。","label":"这套安排，我有异议","guards":[],"intent":"disagree"},{"speaker":"何文","npcId":"he_wen","text":"会议怎么定，不由咱们递上去的几张纸说了算。力气别往那儿使。","label":"干脆联名递条子，影响会议决策","guards":[],"intent":"boundary"}],"roles":{},"outcomes":[],"fallback":[{"speaker":"后勤协作员","npcId":"logistics_1","text":"三摊事，两只手，总得有个先来后到。","label":"","guards":[]}],"closing":[{"speaker":"何文","npcId":"he_wen","text":"就照你排的办。","label":"","guards":[]}],"metadata":{"scene":["厢房外廊下，后勤协作员蹲在地上，用粉笔在青砖上画\"人力表\"——谁送件、谁看门、谁歇脚。旁边堆着几盏马灯、几捆麻绳、几张旧毛毯。"],"historyAnchor":["会议期间的基层保障，主要落在资料递送、联络、秩序与休整安排上。（档案框架）"],"characterState":["后勤协作员脑子里只有\"数\"：几个人、几盏灯、几条绳——他不谈会议，只谈这些够不够。"],"npc":["后勤协作员、何文"],"trigger":["玩家提交一份会议期间基层保障方案后。"],"preconditions":["决策范围限定在资料递送、联络、秩序、休整安排；不涉及会议内容本身。"],"subtext":["他把边界先划死，不是冷漠，是守规矩——越了界，才是真添乱。"],"cues":["粉笔画的人手表随方案变化被擦掉重画——让玩家看见\"取舍\"是具体的。"],"outcomeNotes":["结果变体（三种取舍，明显不同）：","求快：递送及时，但核校略粗。","求准：核校扎实，但递送变慢。","求省人力：留人休整、看门，但送件有积压。","不左右真实会议决定：任何结果只评价本组递送与协作，不改会议结论。"],"memory":["写入 logistics_plan_ch03 = 取舍方向。"],"voice":["情绪＝务实（pragmatic）。后勤协作员：快、干脆；何文：稳。"]}},{"id":"03-05","nodeId":3,"part":5,"title":"等候与战友交谈","sourceParagraph":554,"opening":[{"speaker":"王贵","npcId":"wang_gui","text":"里头开会的开会，外头站岗的站岗。趁这空，咱俩唠点自己的。","label":"王贵","guards":[]}],"responses":[{"speaker":"王贵","npcId":"wang_gui","text":"湘江没了的那几个，我夜里也翻来覆去想。可想归想，明天的道还得迈腿。","label":"湘江那几个兄弟……唉","guards":[],"intent":"comfort"},{"speaker":"陈小满","npcId":"chen_xiaoman","text":"里头议的事，咱们这号人插不上嘴。我就惦记一件——今晚铺盖卷搁哪儿。","label":"会里今晚议到哪一步了？","guards":["conditional"],"intent":"status"},{"speaker":"陈小满","npcId":"chen_xiaoman","text":"湘江那晚过去这么些天了，我一闭眼还是那声音。往后……还会有那样的仗吗？","label":"那样的仗，往后还有吗？","guards":[],"intent":"fear"},{"speaker":"王贵","npcId":"wang_gui","text":"想叫伤员多躺两天？成，这个情我去跟管后勤的讨。","label":"能不能让伤员多歇两天？","guards":["quantity"],"intent":"plan"},{"speaker":"王贵","npcId":"wang_gui","text":"往后怎么走？我一个扛枪的老粗讲不出大道理。走到哪算哪，把眼前每一步踩实。","label":"将来的路会怎么走？","guards":[],"intent":"history"},{"speaker":"陈小满","npcId":"chen_xiaoman","text":"嗯？你方才嘀咕啥？风大，没听真。","label":"火堆边走神了，没听清","guards":[],"intent":"unclear"}],"roles":{},"outcomes":[],"fallback":[{"speaker":"王贵","npcId":"wang_gui","text":"上头的事咱不猜。说点柴米油盐。","label":"","guards":[]}],"closing":[{"speaker":"王贵","npcId":"wang_gui","text":"养足精神了？换岗去。","label":"","guards":[]}],"metadata":{"scene":["院外石阶上，夜色沉沉。远处围墙那头透出一点灯光，模模糊糊。王贵靠着门柱打盹，陈小满抱着膝盖，望着那点灯。街上有更夫远远敲了一下梆子。"],"historyAnchor":["会议期间，外围人员按命令待命、警戒，并不知晓会场内的讨论内容。（档案框架）"],"characterState":["王贵心里有事，故意扯闲话稳住年轻人；陈小满满肚子问题，却知道是\"不该问的\"。"],"npc":["王贵、陈小满"],"trigger":["会场进行期间，玩家在外围等候，与战友闲谈时。"],"preconditions":["不杜撰会场内争论、讲话或人物心理；只谈队伍自身的经历与期盼。"],"subtext":["他把话头往远处引——说家、说饭、说脚上的泡，就是不说墙里头的事。"],"cues":["陈小满说\"夜里老醒\"时，玩家可递一样东西（炒米、绑腿、披毯）——这个小动作比任何台词都暖。"],"outcomeNotes":["结果变体：交谈只影响关系与情绪，不产出资源或剧情捷径。"],"boundary":["不得让王贵或陈小满对会场内容\"隔墙有耳\"式点评；他们的认知止于围墙外。"],"memory":["写入 relationship_chen/wang = ±；若谈及过往承诺，可回读 promise_01。"],"voice":["情绪＝松弛、怀人（quiet）。王贵：低、缓，带笑；陈小满：低、迟疑。"]}},{"id":"03-06","nodeId":3,"part":6,"title":"会后史实说明与任务复盘","sourceParagraph":579,"opening":[{"speaker":"旁白","npcId":"narrator","text":"会开完了。它日后会被怎样评说，档案自有记载；此刻要紧的，是把脚下的路接着走稳。","label":"旁白","guards":[]},{"speaker":"何文","npcId":"he_wen","text":"活干得怎么样？只说我们自己递送的那一段，别扯远。","label":"何文","guards":[]}],"responses":[],"roles":{},"outcomes":[],"fallback":[{"speaker":"何文","npcId":"he_wen","text":"复盘只限一件事：递送这一段干得如何。","label":"","guards":[]}],"closing":[{"speaker":"何文","npcId":"he_wen","text":"休整一天。明日，另有差遣。","label":"","guards":["quantity"]}],"metadata":{"scene":["天将亮，院子里的人来来回回搬东西。墙头的红纸标语被晨风吹得猎猎响。何文把一份复盘用的纸铺在桌上，压上一块石头。"],"historyAnchor":["遵义会议于一月召开，其内容与历史意义由档案说明。（档案）"],"characterState":["何文只认自己那一段账——递送得顺不顺、人有没有照应到；会上的事，他一个字不多说。"],"npc":["解说旁白、何文"],"trigger":["本章收束，会议结束、任务复盘时。"],"preconditions":["以审校史料说明会议与意义；本组任务只评价递送与协作。"],"subtext":["他想说的是\"我们做的虽小，却是真事\"；他不攀功，也不自轻。","回应与呈现：","任务复盘：何文据实评点资料递送、联络、秩序、休整四段的完成度。","玩家询问历史：旁白据档案叙述会议意义（须有出处），不与角色当时认知混淆。","玩家关心／安慰：何文：「这段熬过去了，人都还好，就是好事。」","玩家试图宣称影响会议：何文：「会议怎么定，是会上的人定的。我们递送得顺，是尽本分。」"],"cues":["复盘时，镜头从桌面移到门外——院里恢复平静，阳光照进青石板街。"],"boundary":["","本组虚构任务：递送与协作复盘（据实）。","历史线（旁白）：遵义会议及其历史意义（档案）。"],"outcomeNotes":["结果变体：不出现\"你的投票改变了会议结论\"之类表述（硬性禁止）。"],"memory":["写入 marchLog += ch03。"],"voice":["情绪＝庄重、平静（solemn）。何文：稳，尾音收；旁白：清楚、有据、不渲染。"]}},{"id":"04-01","nodeId":4,"part":1,"title":"进入赤水沙盘","sourceParagraph":609,"opening":[{"speaker":"旁白","npcId":"narrator","text":"赤水河弯了两道弯，两岸尽是陡崖窄径。仗在河这边打响，又在河那边收场。","label":"旁白","guards":[]},{"speaker":"何文","npcId":"he_wen","text":"沙盘上的规矩先讲明：落了字的地名是真的，空着的是咱们假想的行动点。两者不许搅。","label":"何文","guards":[]}],"responses":[{"speaker":"何文","npcId":"he_wen","text":"这一段要办三件事：看敌情、传消息、渡河。头一步，先看图。","label":"沙盘上这些门道，讲讲？","guards":[],"intent":"status"},{"speaker":"何文","npcId":"he_wen","text":"打算走哪条线？手指头在图上点给我看。","label":"我们这段路，我打算这么走","guards":[],"intent":"plan"},{"speaker":"何文","npcId":"he_wen","text":"当年四渡怎么渡的，档案馆里白纸黑字。咱们要动的，只是眼前这一小段。","label":"当年四渡明明是那样走的，改！","guards":[],"intent":"other"},{"speaker":"何文","npcId":"he_wen","text":"地面生疏，心里发虚，人人如此。先看、再问、末了才迈腿。","label":"这地形眼生，我心里发虚","guards":[],"intent":"fear"},{"speaker":"何文","npcId":"he_wen","text":"你指的是哪一处？这里吗？","label":"指不清要问哪一处","guards":[],"intent":"unclear"}],"roles":{},"outcomes":[],"fallback":[{"speaker":"何文","npcId":"he_wen","text":"落字的真，空着的假，不能搅。","label":"","guards":[]}],"closing":[{"speaker":"何文","npcId":"he_wen","text":"派观察在前，定走法在后。","label":"","guards":[]}],"metadata":{"scene":["沙盘推演处——一方木盘上覆着黄泥与青苔，用木条搭出山脊，用蓝布条表示河流，几面小旗插在渡口。油灯在旁，人影投在墙上忽大忽小。窗外是黔北的夜，山风带着湿冷。"],"historyAnchor":["一九三五年一至三月，红军在赤水河两岸数度往返机动，摆脱围追堵截。（档案）"],"characterState":["何文清楚\"这是一场比谁脑子快的仗\"，但他只让本组看眼前这一小段——多了会乱。"],"npc":["何文、解说旁白"],"trigger":["玩家进入第 04 章，赤水沙盘载入时。"],"preconditions":["沙盘上区分\"已核实地标\"与\"虚构行动点\"（视觉标注）。"],"subtext":["他怕你把\"游戏里的点\"当成了\"当年真走过的地方\"，那样的复盘就全错了。"],"cues":["玩家点沙盘时，小旗会晃；标了字的老地名用木牌立着，虚构点用草绳圈出——一眼可辨真假。"],"outcomeNotes":["结果变体：无论岗位均进入沙盘推演；不出现改写真实渡河路线的分支。"],"memory":["写入 chapter04_started = true。"],"voice":["情绪＝沉着、机敏（alert）。何文：稳中带快；旁白：平。"]}},{"id":"04-02","nodeId":4,"part":2,"title":"山路观察点获取消息","sourceParagraph":633,"opening":[{"speaker":"联络员","npcId":"liaison_1","text":"站在这儿，东面一段尽收眼底，再远就叫山梁挡死。你要打听什么，我先讲清能望见多少。","label":"联络员","guards":[]}],"responses":[{"speaker":"联络员","npcId":"liaison_1","text":"再跑一趟？成。只是来回的工夫搭进去，别的事全得排队。","label":"再探一遍，稳妥为上","guards":[],"intent":"other"},{"speaker":"联络员","npcId":"liaison_1","text":"不核就动？随你。这条消息是新是旧，后果自己扛。","label":"军情紧急，不等了，动！","guards":[],"intent":"other"},{"speaker":"联络员","npcId":"liaison_1","text":"我敢作保的，只有这两只眼睛方才望见的。","label":"站这儿能望见多远？","guards":["quantity"],"intent":"status"},{"speaker":"联络员","npcId":"liaison_1","text":"这条消息不入你的耳？那另派人去看，我让位。","label":"你这消息我信不过","guards":[],"intent":"disagree"},{"speaker":"联络员","npcId":"liaison_1","text":"明天的事，谁也吹不了牛。方才望见的，我倒记得分毫不差。","label":"接下来敌我形势会怎样？","guards":[],"intent":"history"}],"roles":{},"outcomes":[],"fallback":[{"speaker":"联络员","npcId":"liaison_1","text":"望见的说一宗是一宗，没望见的，我不编。","label":"","guards":[]}],"closing":[{"speaker":"联络员","npcId":"liaison_1","text":"去或不去，等你一个字。","label":"","guards":[]}],"metadata":{"scene":["山腰一处突出岩台，灌木掩着。天刚亮，山坳里一片薄雾。从这里能望见东面一条浅滩，渡口的船影隐约；再往西，山挡住了。"],"historyAnchor":["山地行动中，观察点视野受地形限制，情报的完整性与时效都受约束。（军事常识，档案框架）"],"characterState":["联络员跑了一夜山路，鞋上全是泥；他宁可多说一句\"我没看见\"，也不肯让队里赌。"],"npc":["联络员（虚构）"],"trigger":["玩家派遣观察、或亲自登观察点时。"],"preconditions":["观察点视野有限；消息有时效。"],"subtext":["他把\"能看多少\"先交底，是不想让你把半个消息当成全貌。","信息呈现（可核验线索＋观察局限＋时效）：","可核验：「东面渡口的船，今早还系在岸边——我亲眼见的。」","局限：「西面山那边我看不到，得绕过去才行。」","时效：「我隔了半晌回来，消息这会儿还作不作数，不好说。」"],"cues":["每次\"跑到观察点看\"都要花掉沙盘上的时间点；雾散雾起会改变能见度——让\"信息不足\"变得可感。"],"outcomeNotes":["结果变体：","核验：耗时，得较可靠信息。","直接行动：快，但承担信息不足的后果（后续反馈具体）。"],"memory":["写入 intel_ch04 = {内容, 时效}。"],"voice":["情绪＝警惕（watchful）。联络员：气声、短句，喘未平。"]}},{"id":"04-03","nodeId":4,"part":3,"title":"拼接行动顺序","sourceParagraph":662,"opening":[{"speaker":"王贵","npcId":"wang_gui","text":"侦察、联络、休整、机动，四张牌在你手里。出牌的先后不一样，走出来的就是两条道。","label":"王贵","guards":[]}],"responses":[{"speaker":"王贵","npcId":"wang_gui","text":"先探路再动身，稳是稳，半天的工夫就撂在山头上了。","label":"先派人侦察","guards":[],"intent":"other"},{"speaker":"后勤协作员","npcId":"logistics_1","text":"睡足了再赶路，脚上有劲。可追兵的脚底板，不认你这个理。","label":"先让队伍歇足","guards":[],"intent":"other"},{"speaker":"王贵","npcId":"wang_gui","text":"先把各队的线接通，散了也能收拢。代价是慢。","label":"先把联络接通","guards":[],"intent":"other"},{"speaker":"后勤协作员","npcId":"logistics_1","text":"抢时间没错。摸黑乱闯，前头是沟是坎，两眼一抹黑。","label":"先抢时间机动","guards":[],"intent":"other"},{"speaker":"后勤协作员","npcId":"logistics_1","text":"粮袋瘪着，人手缺着，一样一样都有数，容不得虚账。","label":"现在的粮和人撑几步？","guards":[],"intent":"status"},{"speaker":"王贵","npcId":"wang_gui","text":"嫌这顺序不妥？重新摆一摆，摆出个说法来。","label":"这个顺序我不认","guards":[],"intent":"disagree"}],"roles":{},"outcomes":[],"fallback":[{"speaker":"王贵","npcId":"wang_gui","text":"先探还是先走，先后一换，天壤之别。","label":"","guards":[]}],"closing":[{"speaker":"王贵","npcId":"wang_gui","text":"牌出定了，照这个打。","label":"","guards":[]}],"metadata":{"scene":["沙盘旁，四块木牌分别写着\"侦察\"\"休整\"\"联络\"\"机动\"，等在盘边。你可以把它们依次摆进行动轨道。木牌手感沉，边角磨得发亮。"],"historyAnchor":["机动转战中，侦察、休整、联络、机动的先后次序直接影响队伍的安全与速度。（军事常识，档案框架）"],"characterState":["王贵凭经验，主张\"先看后走\"；后勤协作员凭体力账，主张\"先歇再走\"——两人都从自己的痛处出发。"],"npc":["王贵、后勤协作员"],"trigger":["玩家在行动面板上排列\"侦察、休整、联络、机动\"模块顺序时。"],"preconditions":["四个模块可换序；同一模块换顺序必须产生不同反馈。"],"subtext":["王贵吃过\"瞎走\"的亏，后勤协作员见过\"累垮\"的人——他们争的不是对错，是各自的伤疤。"],"cues":["每次摆牌，沙盘上会实时生成一条行军轨迹，并在可能出现问题的节点标出小旗（走散、断粮、遇阻）。"],"outcomeNotes":["结果变体（换序必不同）：","「侦察→联络→机动→休整」：路清楚，但队伍疲惫。","「休整→侦察→机动→联络」：体力好，但联络滞后。","「机动→侦察→休整→联络」：快但不稳，易走散。","不得出现两套不同顺序返回同一句评价。"],"memory":["写入 order_ch04 = 顺序。"],"voice":["情绪＝斟酌（deliberate）。王贵：慢、顿；后勤协作员：快、脆。"]}},{"id":"04-04","nodeId":4,"part":4,"title":"河谷渡运点调度","sourceParagraph":690,"opening":[{"speaker":"船工","npcId":"boatman_1","text":"河汊里拢共拢这几条船，一趟能驮几多，问我不如问水。排队也好、分拨也好，你定个章程。","label":"船工","guards":["quantity"]}],"responses":[{"speaker":"船工","npcId":"boatman_1","text":"要抢时辰？那就人先行、粮压后。翻船了，莫怪我没打招唿。","label":"全渡！一趟一趟连着来","guards":[],"intent":"other"},{"speaker":"船工","npcId":"boatman_1","text":"等探明了再动，成。可滩口不是歇脚的地界，天亮前必须离水。","label":"先探清水路再动","guards":["conditional"],"intent":"other"},{"speaker":"船工","npcId":"boatman_1","text":"分两拨走，稳当是稳当，来回多跑几趟，人力熬不熬得住，先掂掂。","label":"分两拨，前后脚过","guards":["quantity"],"intent":"other"},{"speaker":"船工","npcId":"boatman_1","text":"水性、船况、风头，三样凑齐才晓得一船装几人。浪头一掀脸，先把数减半。","label":"这渡口一回能过多少人？","guards":["quantity"],"intent":"status"},{"speaker":"船工","npcId":"boatman_1","text":"嫌我磨蹭？那你另寻旁的渡口。这条河的脾气，我比你熟。","label":"你这也太慢了！","guards":[],"intent":"disagree"},{"speaker":"船工","npcId":"boatman_1","text":"别在我跟前摆那些没影的渡河旧事，我只认得眼下的船、眼前的水。","label":"当年某次渡河就是这样过的","guards":["quantity"],"intent":"other"}],"roles":{},"outcomes":[],"fallback":[{"speaker":"船工","npcId":"boatman_1","text":"船有定数，水无常形，装多装少自己掂掂。","label":"","guards":["quantity"]}],"closing":[{"speaker":"船工","npcId":"boatman_1","text":"主意拿定，我就招呼伙计撑篙。","label":"","guards":[]}],"metadata":{"scene":["赤水河边一处滩头。四五条木船泊在浅水里，船身旧，篙子立在船头。岸边堆着等待过河的人和物资，草鞋踩得滩上泥泞。河对岸是陡坡，树影里看不清有没有人。"],"historyAnchor":["赤水河沿线的渡口是机动转战的关键节点，渡运能力受船数、水情与船工人数制约。（档案框架）"],"characterState":["船工是本地人，识水、惜船；他知道哪条线有暗涡，也怕队伍催得急出岔子。"],"npc":["渡口协作员／船工（虚构，当地）"],"trigger":["抵达河谷渡运点，安排渡运时。"],"preconditions":["本地渡运能力有限（船数、载荷、人手以本局数据为准），存在排队与隐蔽需求。"],"subtext":["他不是不帮忙，是不想你把他这条河当\"想怎么走就怎么走\"。"],"cues":["渡运时，船身随水流侧倾；满载时船帮几乎贴水面，玩家的每次调度都对应一条船的往返剪影。"],"outcomeNotes":["结果变体（三种分别回应，不泛称真实渡河全貌）：","急进：快，但疲劳与风险上升。","等待核验：稳，但时间成本高。","分批：均衡，但轮次多、耗人力。"],"memory":["写入 crossing_ch04 = 调度方式。"],"voice":["情绪＝焦急中带耐性（hurried-patient）。船工：方言味、慢条斯理，尾音沉。"]}},{"id":"04-05","nodeId":4,"part":5,"title":"多轮行动、对手适应","sourceParagraph":717,"opening":[{"speaker":"联络员","npcId":"liaison_1","text":"东岸你露了两回脸，那头像是把人往那边挪了。","label":"联络员","guards":[]}],"responses":[{"speaker":"联络员","npcId":"liaison_1","text":"改走西岸？西岸我没踩过点，得先遣人探。","label":"换条道走西面","guards":[],"intent":"plan"},{"speaker":"联络员","npcId":"liaison_1","text":"我晓得的：他们比你上一回多渡了一趟河。","label":"对岸这会儿什么动向？","guards":[],"intent":"status"},{"speaker":"联络员","npcId":"liaison_1","text":"你断定他们没设防？那就照你的意思办，捅了篓子再说。","label":"他未必真有防备，照原计划","guards":[],"intent":"disagree"},{"speaker":"联络员","npcId":"liaison_1","text":"对手下一步的棋，我猜不来。我不是神仙。","label":"他们下一步会怎么动？","guards":[],"intent":"history"}],"roles":{},"outcomes":[],"fallback":[{"speaker":"联络员","npcId":"liaison_1","text":"你在那头露过相，人家八成有了动作。","label":"","guards":[]}],"closing":[{"speaker":"联络员","npcId":"liaison_1","text":"下一趟走哪条线，你指。","label":"","guards":[]}],"metadata":{"scene":["沙盘上，几轮行动过后，代表\"敌方\"的黑色小旗悄悄挪了位置。油灯将尽，灯花一跳。联络员从外头进来，带进一身寒气。"],"historyAnchor":["机动战的核心是\"敌人适应你的动作、你也适应敌人的动作\"，双方都在猜测中调整。（军事常识，档案框架）"],"characterState":["联络员只报告\"看到了什么\"，不敢替敌人\"想什么\"；他知道，猜敌人心思最容易出错。"],"npc":["联络员、敌方传令兵（可选登场，虚构）"],"trigger":["玩家在沙盘完成若干轮行动后。"],"preconditions":["反馈只依据玩家已实际暴露的行为；对手\"记忆\"仅属游戏机制。"],"subtext":["他说的是\"像是\"，不是\"一定\"——留了余地，也留了命。"],"boundary":["","敌方传令兵不必每章登场；登场时不是全知 AI，不称掌握真实敌军心理。","\"对手适应\"仅表现为游戏机制对玩家选择的回应，不得包装成\"还原了真实敌军决策\"。"],"cues":["黑旗自适应移动要\"有依据\"——必须对应玩家上一轮实际走的方向，而非随机漂移。"],"outcomeNotes":["结果变体：","换向规避：避开已暴露方向，但新方向情报空白。","固守：路径熟，但面对对手已做出的调整。"],"memory":["写入 exposure_ch04 = [已暴露方向]。"],"voice":["情绪＝紧绷（tense）。联络员：低、快；敌方传令兵：含糊、慌张、话不成句。"]}},{"id":"04-06","nodeId":4,"part":6,"title":"接应与四渡史实对照","sourceParagraph":745,"opening":[{"speaker":"何文","npcId":"he_wen","text":"把你这一路的走法，从头到尾捋一遍。","label":"何文","guards":[]},{"speaker":"旁白","npcId":"narrator","text":"四渡的来龙去脉，档案里分得清清楚楚，此处不再赘述。","label":"旁白","guards":[]}],"responses":[],"roles":{},"outcomes":[],"fallback":[{"speaker":"何文","npcId":"he_wen","text":"自己那段路捋顺了，就够了。","label":"","guards":[]}],"closing":[{"speaker":"何文","npcId":"he_wen","text":"收拢人手，往江边靠。","label":"","guards":[]}],"metadata":{"scene":["天亮，队伍在北岸一处村口收拢。屋顶冒着炊烟，有人在井边洗脸。何文蹲在门槛上，用树枝在地上把玩家这一路的动法从头划了一遍。"],"historyAnchor":["四渡赤水的史实进程与意义由档案分段说明。（档案）"],"characterState":["何文复盘时只谈\"我们这一组\"，不碰\"全军得失\"——这是分寸，也是自知。"],"npc":["何文、解说旁白"],"trigger":["本章收束，接应完成、进入复盘时。"],"preconditions":["回顾玩家行动链与代价；四次渡河的史实材料分段调用。"],"subtext":["他要你看清\"每一步都是有代价的\"，而不是只看结果漂不漂亮。","回应与呈现：","行动链回顾：何文据实串起玩家的观察、顺序、调度、应变，指出代价（耗粮、疲劳、延误）。","史实分段调用：旁白分段说明四渡赤水的史实，不把四轮虚构任务等同四次真实渡河。","玩家询问历史：旁白据档案叙述；不与角色当时认知混淆。","玩家关心／安慰：何文：「这一段，人是累了，好歹都过来了。」","玩家异议：何文：「你觉得哪一步不该那么走，说出来，记到复盘里。」"],"cues":["每复盘一个节点，地上的划痕就添一笔，最后连成一条曲折的线。"],"boundary":["","本组虚构任务：行动链与代价。","历史线（旁白）：四渡赤水史实（分段、有来源）。"],"outcomeNotes":["结果变体：只复盘本组协作，不评价真实战役得失。"],"memory":["写入 marchLog += ch04。"],"voice":["情绪＝沉稳、回望（reflective）。何文：慢、平；旁白：分段、清楚。"]}},{"id":"05-01","nodeId":5,"part":1,"title":"抵达渡运环境","sourceParagraph":776,"opening":[{"speaker":"旁白","npcId":"narrator","text":"金沙江到了。皎平渡一带江面收窄，水头贴着礁石打转。","label":"旁白","guards":[]},{"speaker":"船工","npcId":"boatman_1","text":"这段江面底下净是暗漩，能下篙的地方拢共两处。船不比桥——坐几个、走哪条水线，全依我的。","label":"船工","guards":[]}],"responses":[{"speaker":"船工","npcId":"boatman_1","text":"船拢在滩下，人聚在坡上，浪头一起，一趟能过的数就往下落。先摸清吃水，再谈装人。","label":"这段江水有多凶？","guards":[],"intent":"status"},{"speaker":"船工","npcId":"boatman_1","text":"你打算怎么个渡法？先人后货，还是先货后人，排个次序出来。","label":"我的渡江方案，你听听","guards":[],"intent":"plan"},{"speaker":"船工","npcId":"boatman_1","text":"头回见这条江的，十个里九个腿肚子转筋。莫慌，耳朵听口令就行。","label":"头回见这么急的江，腿软","guards":[],"intent":"fear"},{"speaker":"船工","npcId":"boatman_1","text":"想走那条水线？底下卧着暗流，篙下去都探不到底。换一条，或者讲个我信服的理由。","label":"你那套规矩太死，我要改","guards":[],"intent":"disagree"},{"speaker":"船工","npcId":"boatman_1","text":"认清楚咯——脚底下是木船，不是铁索。索桥上那套把戏，搁到水上是要死人的。","label":"说起泸定桥铁索怎么过","guards":[],"intent":"other"}],"roles":{},"outcomes":[],"fallback":[{"speaker":"船工","npcId":"boatman_1","text":"船不是桥，装多少、行哪条线，得一笔一笔算。","label":"","guards":[]}],"closing":[{"speaker":"船工","npcId":"boatman_1","text":"先清船数，再核人头。","label":"","guards":[]}],"metadata":{"scene":["金沙江皎平渡渡口。两岸是陡峭的赭红色山壁，江面宽，水流急，激浪拍在礁石上，声如闷雷。岸边泊着几条窄木船，篙子斜插在水里。江风把砂砾吹得打旋，说话得对着耳朵喊。"],"historyAnchor":["一九三五年五月，红军抵金沙江畔，在皎平渡等地以有限船只连续渡运。（档案）"],"characterState":["船工在此撑了半辈子船，认得这里的每一道暗流；他不怕水，怕的是\"不识水的人催他开船\"。"],"npc":["旁白、船工"],"trigger":["玩家抵达金沙江渡口时。"],"preconditions":["江面开阔、水流急；现场条件有限（船、篙、绳、人力以本局为准）。"],"subtext":["他把\"得听我的\"先撂出来，是因为他知道，江上不听船工的，是要出人命的。"],"cues":["风浪音效始终在底噪里；玩家靠近岸边时，浪花会打湿画面下缘。"],"outcomeNotes":["结果变体：无论岗位均进入渡运准备；拒绝照搬攀索桥段。"],"memory":["写入 chapter05_started = true。"],"voice":["情绪＝谨慎、厚重（grave）。船工：大嗓、压过水声，尾音沉；旁白：庄重。"]}},{"id":"05-02","nodeId":5,"part":2,"title":"核对船只和运力","sourceParagraph":800,"opening":[{"speaker":"后勤协作员","npcId":"logistics_1","text":"船几条、一趟装几人、对岸还压着多少人几袋粮——一样一样，先给我个准数。","label":"后勤协作员","guards":["quantity"]}],"responses":[{"speaker":"船工","npcId":"boatman_1","text":"船拢在滩下，几条就是几条，每条的肚量摆在那儿，浪大还得往下压。账就这么些，编不出花来。","label":"船和运力，到底什么底数？","guards":["quantity"],"intent":"status"},{"speaker":"后勤协作员","npcId":"logistics_1","text":"先运粮再渡人，成。人这一头就得往后压，队伍要等。你排序，我记账。","label":"我提个分批的章程","guards":[],"intent":"plan"},{"speaker":"船工","npcId":"boatman_1","text":"每船再加几个？吃水一过线，一个浪头就把船扣了。这个险，换谁来说我都不冒。","label":"每船多塞几个，快些","guards":["quantity"],"intent":"disagree"},{"speaker":"船工","npcId":"boatman_1","text":"先前队伍拢共征了多少条船，我上哪儿晓得去。我眼里只有眼下这几条。","label":"当年一共征了多少条船？","guards":["quantity"],"intent":"history"},{"speaker":"后勤协作员","npcId":"logistics_1","text":"你打问的是哪一桩？船、人、粮，指一样。","label":"（问得没头没脑）","guards":[],"intent":"unclear"}],"roles":{},"outcomes":[],"fallback":[{"speaker":"后勤协作员","npcId":"logistics_1","text":"一切从实数起头：船、人、粮。","label":"","guards":[]}],"closing":[{"speaker":"后勤协作员","npcId":"logistics_1","text":"数都落本子了，接着排次序。","label":"","guards":[]}],"metadata":{"scene":["滩头一块大青石，成了临时\"账台\"。后勤协作员蹲在石上，用炭条记数；船工站在旁边，一条条报船的情况——哪条漏水、哪条篙短。水声在耳边不停。"],"historyAnchor":["渡运的载荷与人手，取决于实际的船只数量与船工数量，须以实况为准，不任意编造统计。（档案框架）"],"characterState":["后勤协作员心里只认\"实数\"；他最怕的是有人拍脑袋多报一条船，结果翻在江心。"],"npc":["船工、后勤协作员"],"trigger":["玩家清点船只、核算载荷时。"],"preconditions":["船数、载荷、待运任务以本局实际数据为准，不得任意编造史实统计。"],"subtext":["他宁可得罪人，也不愿把\"想当然的数\"写进账——账错了，是要拿命去填的。"],"cues":["炭条写下的数字会随玩家调整实时变化；一旦填入\"假数\"，船工立刻摇头并抹掉。"],"outcomeNotes":["结果变体：","清点准确：后续调度有据可依。","清点含糊：后续易出现超载或空跑（具体反馈）。","所有数字必须与游戏内实际库存、待运队列一致，不得凭空增减。"],"memory":["写入 capacity_ch05 = {船数, 载荷}。"],"voice":["情绪＝认真（matter-of-fact）。后勤协作员：快、干脆；船工：慢、稳，尾音重。"]}},{"id":"05-03","nodeId":5,"part":3,"title":"拖拽编排渡运顺序","sourceParagraph":826,"opening":[{"speaker":"卫生员","npcId":"medic_1","text":"船次你来排。排的时候记着一条：伤号经不起江风干等。","label":"卫生员","guards":[]}],"responses":[{"speaker":"卫生员","npcId":"medic_1","text":"先送伤号，合情理。能拄棍走动的轻伤员挪后一班船，省下的舱位装粮。","label":"先送伤员过江","guards":["quantity"],"intent":"other"},{"speaker":"后勤协作员","npcId":"logistics_1","text":"先保粮，成。躺着的伤号押后班次，得留人陪着——江风冷。","label":"粮食要紧，粮船先行","guards":[],"intent":"other"},{"speaker":"卫生员","npcId":"medic_1","text":"人摞着粮装，船帮都快贴到水面了。分开装——哪条命也不是拿来赌的。","label":"人粮同船，一趟装完","guards":[],"intent":"other"},{"speaker":"后勤协作员","npcId":"logistics_1","text":"论重量分三拨，趟数多、人熬人；论人头分两拨，快是快，轻伤号得挤一挤。两条道，你选。","label":"我按重量排了三批","guards":["quantity"],"intent":"plan"},{"speaker":"卫生员","npcId":"medic_1","text":"先送伤号有哪里不妥，讲给我听。讲得在理，我就依你。","label":"伤员排前头，我不服","guards":[],"intent":"disagree"}],"roles":{},"outcomes":[],"fallback":[{"speaker":"卫生员","npcId":"medic_1","text":"人粮混装要出事，一船装一样。","label":"","guards":[]}],"closing":[{"speaker":"后勤协作员","npcId":"logistics_1","text":"序次定了，去知会船家。","label":"","guards":[]}],"metadata":{"scene":["滩上砂石被踩得平实，三块小木牌代表\"人\"\"伤员\"\"物资\"，等着玩家把它们排进船的往返轮次。江风不小，木牌要用手按着。"],"historyAnchor":["渡运中，人员、伤员、物资的先后与搭配，直接决定是否超载、是否久等。（档案框架）"],"characterState":["卫生员最惦记担架上的伤员，但她懂\"能挪的得让能撑的\"；后勤协作员算的是船次与人手。"],"npc":["卫生员、后勤协作员"],"trigger":["玩家拖拽人员、伤员、物资到渡运轮次时。"],"preconditions":["存在伤员需优先、物资有重量、船有载荷上限。"],"subtext":["她知道伤员优先是对的，但也怕因这一个\"优先\"让另一船人空等——她要你把账算给她听。"],"cues":["超载时，木船吃水线明显下沉、船工立刻喊停；久等时，等候的人会搓手、跺脚——冷意可见。"],"outcomeNotes":["结果变体：","合理编组：超载提示消失，等待时间可控。","不当搭配：明确提示\"为什么超载／为什么久等\"，不泛泛而谈。"],"memory":["写入 loading_ch05 = 编组方式。"],"voice":["情绪＝细致、关切（attentive）。卫生员：轻、稳；后勤协作员：快、实。"]}},{"id":"05-04","nodeId":5,"part":4,"title":"输入自由渡运方案","sourceParagraph":851,"opening":[{"speaker":"何文","npcId":"he_wen","text":"方案讲一遍。船工坐在旁边——水上半分讨不来巧，他有话要挑。","label":"何文","guards":[]}],"responses":[{"speaker":"船工","npcId":"boatman_1","text":"连轴转、往返不停？篙要换手，人要灌水，船板也要歇——你当它是块铁？","label":"我的渡运方案","guards":[],"intent":"plan"},{"speaker":"何文","npcId":"he_wen","text":"摊开来就这些：人一拨，船一列。你的算计，从这堆家底上起头。","label":"现有人手船只几何？","guards":[],"intent":"status"},{"speaker":"何文","npcId":"he_wen","text":"有不妥，动手改。改完，把因此多赔进去的工夫和人，一并报出来。","label":"这方案要改，我说说哪里","guards":[],"intent":"disagree"},{"speaker":"船工","npcId":"boatman_1","text":"你讲的那个物件，这地界找不出第二件。手头只有船、篙、缆绳，摆布吧。","label":"弄几台机器绞船过江","guards":[],"intent":"plan"}],"roles":{},"outcomes":[{"speaker":"何文","npcId":"he_wen","text":"分批、往返、接应、轮换，四样都在。这方案，立得住。","label":"四项齐备","guards":[]},{"speaker":"船工","npcId":"boatman_1","text":"一宿不合眼，第二趟准坏在水中央。","label":"缺轮换","guards":[]},{"speaker":"何文","npcId":"he_wen","text":"对岸没人接？船一靠，滩上就成一锅粥。","label":"缺接应","guards":["conditional"]}],"fallback":[{"speaker":"何文","npcId":"he_wen","text":"分批、往返、接应、轮换——少一环，这盘棋就不活。","label":"","guards":[]}],"closing":[{"speaker":"何文","npcId":"he_wen","text":"照你的改法动。","label":"","guards":[]}],"metadata":{"scene":["渡口上游一处稍微避风的岩凹里，何文和船工对着一块木炭画的简图商量。图上画着几条船行线，箭头标着往返。"],"historyAnchor":["连续渡运需考虑分批、往返、接应与船手轮换，方能持续。（档案框架）"],"characterState":["何文担心\"累垮船工\"；船工担心\"图快出事\"——两人一同给你把关。"],"npc":["何文、船工"],"trigger":["玩家提交一份自由填写的渡运方案后。"],"preconditions":["方案需覆盖分批、往返、接应、疲劳安排。"],"subtext":["两个人一个懂\"组织\"、一个懂\"江\"，他们合起来，才是你这套方案能不能落地的答案。"],"cues":["方案里的每条船行线都会在简图上被\"走\"一遍——往返太密，图上箭头会挤成一团，直观提示\"人撑不住\"。"],"outcomeNotes":["结果变体（禁止一律\"可以，继续前进\"）："],"memory":["写入 crossing_plan_ch05 = 要点。"],"voice":["情绪＝冷静（steady）。何文：稳、慢；船工：实、糙。"]}},{"id":"05-05","nodeId":5,"part":5,"title":"夜间联络与操作受阻","sourceParagraph":877,"opening":[{"speaker":"陈小满","npcId":"chen_xiaoman","text":"对岸的火光亮一半灭一半。是催我们过，还是叫我们候着？我瞧不准。","label":"陈小满","guards":[]}],"responses":[{"speaker":"陈小满","npcId":"chen_xiaoman","text":"叫我摸黑先泅过去探？行是行——黑咕隆咚的，好歹给我拴根绳啊。","label":"我泅过去探灯号","guards":[],"intent":"plan"},{"speaker":"陈小满","npcId":"chen_xiaoman","text":"手指头冻成胡萝卜了。你给我哈两口热气，我还能再撑一程。","label":"手冻坏了吧？我给你暖暖","guards":[],"intent":"comfort"},{"speaker":"船工","npcId":"boatman_1","text":"夜风一起，浪头认不得人。硬闯不是本事，多等半个时辰不亏什么。","label":"灯号不明，硬闯怕出事","guards":[],"intent":"fear"},{"speaker":"陈小满","npcId":"chen_xiaoman","text":"你讲信号没花、是我眼花？那你自个儿来认。认对了，我服气。","label":"信号没错，是你看岔了","guards":[],"intent":"disagree"},{"speaker":"船工","npcId":"boatman_1","text":"对岸黑黢黢的没个回音。让船靠一靠，也让弟兄们的手腕歇一歇。","label":"对岸现在什么动静？","guards":[],"intent":"status"}],"roles":{},"outcomes":[],"fallback":[{"speaker":"陈小满","npcId":"chen_xiaoman","text":"火光不明，灯号不真，再候一候。","label":"","guards":[]}],"closing":[{"speaker":"陈小满","npcId":"chen_xiaoman","text":"认准了，是叫咱们走。下水！","label":"","guards":[]}],"metadata":{"scene":["夜里的渡口。风更冷，江面只剩一条灰白的线。对岸本该亮起的灯号，只零星星闪了两下又灭。陈小满裹着薄毯蹲在石头上，手冻得发僵，呵气成霜。"],"historyAnchor":["夜间渡运中，信号传递易受能见度、风浪与疲劳影响。（档案框架）"],"characterState":["陈小满怕黑水，更怕自己\"看错了信号\"耽误队伍；他反复揉眼，就是想确认自己没看岔。"],"npc":["陈小满、船工"],"trigger":["夜间渡运中，出现信号误解、等待或疲劳时。"],"preconditions":["受阻原因为信号／疲劳／等待，不必然升级为战斗。"],"subtext":["他宁可承认\"我看不准\"，也不敢瞎报一个\"能走\"——上次在湘江，他就吃过\"想当然\"的亏。"],"cues":["夜色中画面亮度压低，仅靠灯号与水面微光；玩家\"摸黑探路\"时，镜头随脚步轻微晃动——只体现协作与风险，不触发战斗。"],"outcomeNotes":["结果变体（不每次变枪战）：","信号澄清：继续渡运。","等待：耗时，队伍休息恢复。","疲劳累积：需轮换，否则出错概率上升——仅体现协作效率，不触发战斗。"],"memory":["写入 night_delay_ch05 = 原因。"],"voice":["情绪＝疲惫、低声（weary-hushed）。陈小满：气声、鼻音重；船工：压嗓、短。"]}},{"id":"05-06","nodeId":5,"part":6,"title":"渡运完成与回望","sourceParagraph":903,"opening":[{"speaker":"船工","npcId":"boatman_1","text":"一船一船都送过去了。你们这支队伍上下船有章法，少见。","label":"船工","guards":["conditional"]}],"responses":[],"roles":{},"outcomes":[],"fallback":[{"speaker":"船工","npcId":"boatman_1","text":"江这边没落下一个人，一篙一篙，都是数过的。","label":"","guards":["conditional"]}],"closing":[{"speaker":"旁白","npcId":"narrator","text":"北岸的路在山腰上绕。再往北，等着他们的是大渡河。","label":"","guards":[]}],"metadata":{"scene":["晨光里，最后一批人踏上北岸。滩上留下一串湿脚印，一直延伸向岸边的石阶。船工坐在船头歇息，篙子横在膝上，望着江面出神。北岸的路，通向更北的群山。"],"historyAnchor":["巧渡金沙江的史实与意义由档案说明，本组只复盘组织与协作。（档案）"],"characterState":["船工把船篙收了，心里松快；他没夸自己，只说\"江这头没落下人\"——这是他最在意的一句。"],"npc":["船工、旁白"],"trigger":["本章收束，渡运完成时。"],"preconditions":["剩余任务、资源以实际为准。"],"subtext":["他夸的是\"有条理\"，不是\"勇猛\"——在江上撑船的人，最敬重的是\"不乱\"。","回应与呈现：","感谢协作：船工或玩家致意可写；船工不冒用真实人物身份。","核对剩余任务：后勤据实报还剩什么人、多少粮、下一步。","询问现状：船工：「船我收篙了，江这头没落下人。」","问历史／未来：旁白：「此后的路，档案有载。」（不预知）","关心／安慰：陈小满：（长出一口气）「总算过来了。这辈子不想再坐这船。」"],"cues":["镜头从江面缓缓抬向北岸山路，晨雾散开——把\"巧渡\"的紧张收进一句平静里。"],"boundary":["","本组虚构任务：渡运组织完成度（据实）。","历史线（旁白）：巧渡金沙江的史实与组织能力（档案），不改写真实渡江结局。"],"outcomeNotes":["结果变体：只评价组织与协作，不称\"创造了渡江奇迹\"之类超出史实的表述。"],"memory":["写入 marchLog += ch05。"],"voice":["情绪＝松一口气（relieved）。船工：舒缓、低沉；旁白：平。"]}},{"id":"06-01","nodeId":6,"part":1,"title":"安顺场环境与任务","sourceParagraph":933,"opening":[{"speaker":"旁白","npcId":"narrator","text":"安顺场。渡口只寻得几只小船，江流却比来路更凶。","label":"旁白","guards":[]},{"speaker":"何文","npcId":"he_wen","text":"立个规矩：这一关，是安顺场抢渡。铁索桥在下一程，两桩事不许搅在一起。","label":"何文","guards":[]}],"responses":[{"speaker":"何文","npcId":"he_wen","text":"咱们的差事：配合渡河、滩头接应、保小船来回跑。","label":"安顺场这仗怎么个打法？","guards":[],"intent":"status"},{"speaker":"何文","npcId":"he_wen","text":"怎么个配合法？先讲，我对着这片江岸琢磨合不合适。","label":"我这样配合渡河","guards":[],"intent":"plan"},{"speaker":"何文","npcId":"he_wen","text":"铁索桥是下一场的事。眼下只有船——把船这一头的心思用足。","label":"张口就讲泸定桥铁索","guards":[],"intent":"other"},{"speaker":"何文","npcId":"he_wen","text":"水凶船小，腿软不冤。一应听船工的——他的篙，比咱们的话管用。","label":"这江这船，看着就悬","guards":[],"intent":"fear"},{"speaker":"何文","npcId":"he_wen","text":"哪一节没吃透？","label":"有话没说清","guards":[],"intent":"unclear"}],"roles":{},"outcomes":[],"fallback":[{"speaker":"何文","npcId":"he_wen","text":"这里是抢渡。铁索桥，是另一回的事。","label":"","guards":[]}],"closing":[{"speaker":"何文","npcId":"he_wen","text":"先去滩头看看船。","label":"","guards":[]}],"metadata":{"scene":["安顺场渡口，大渡河咆哮着向东。河面比金沙江更凶，浪头翻卷。岸边是碎石滩，几间破败的民房。天阴着，云压得低。一条小船被几个人扶着，在浪边摇晃。"],"historyAnchor":["一九三五年五月，红军在安顺场强渡大渡河。（档案）"],"characterState":["何文知道这水\"吃人\"，也知道\"越是这样的地方越不能乱\"；他先给本组划线：这关是渡船，不是过桥。"],"npc":["旁白、何文"],"trigger":["玩家进入第 06 章，抵达安顺场时。"],"preconditions":["本关定位为安顺场渡口；泸定桥为后续独立关卡。"],"subtext":["他怕你把两场最险的仗记混——记混了，复盘、纪念都会失真。"],"cues":["河水的轰鸣贯穿全场景；玩家站近浪线时，画面会被飞沫打湿。"],"outcomeNotes":["结果变体：无论岗位均进入渡河准备；硬性禁止与泸定桥合并。"],"memory":["写入 chapter06_started = true；scene_is_anshunchang = true。"],"voice":["情绪＝凝重（grave）。何文：稳、压嗓；旁白：庄重。"]}},{"id":"06-02","nodeId":6,"part":2,"title":"岸边准备","sourceParagraph":957,"opening":[{"speaker":"船工","npcId":"boatman_1","text":"拢共就这么一条小船，压上七八个就到头了。先派定谁走谁留，再挪步。","label":"船工","guards":["quantity"]}],"responses":[{"speaker":"船工","npcId":"boatman_1","text":"船帮是新补的桐油灰，撑得住几趟，我不敢说大话。走一趟看一趟。","label":"船况到底撑得住几趟？","guards":[],"intent":"status"},{"speaker":"后勤协作员","npcId":"logistics_1","text":"谁先下滩、谁留在坡上接应，名单开出来。","label":"谁先上谁后上，我来派","guards":[],"intent":"plan"},{"speaker":"船工","npcId":"boatman_1","text":"再塞两个也压不翻？水头这么急，命只有一条，我不赌。","label":"多上两个压不翻！","guards":[],"intent":"disagree"},{"speaker":"何文","npcId":"he_wen","text":"当年几条船、多少人，我说不出准数——得翻档案才敢落笔。咱们先把手头的活干扎实。","label":"当年渡河到底几条船几人？","guards":["quantity"],"intent":"other"},{"speaker":"后勤协作员","npcId":"logistics_1","text":"你问的是船的事，还是人的事？","label":"（问得不在点子上）","guards":[],"intent":"unclear"}],"roles":{},"outcomes":[],"fallback":[{"speaker":"船工","npcId":"boatman_1","text":"船一只，水一江，派好了人再动身。","label":"","guards":[]}],"closing":[{"speaker":"船工","npcId":"boatman_1","text":"人派定了，我给你们配桨。","label":"","guards":[]}],"metadata":{"scene":["岸边一处背风的岩石后，船工带着两个人给小船补漏——用麻丝塞缝，用桐油抹边。船帮上还留着旧补丁。后勤协作员在旁清点涉水用的绳、竹竿。风把油布吹得啪啪响。"],"historyAnchor":["安顺场强渡依赖有限的船只与船工，船况与渡河人数须以核实资料为准。（档案框架）"],"characterState":["船工信\"手摸过的船\"，不信\"嘴上说的船\"；他反复检查船帮，是怕渡到江心才漏。"],"npc":["船工、后勤协作员"],"trigger":["玩家在岸边准备船只、携行与人员分工时。"],"preconditions":["船况、携行、人员分工明确；参与者人数等史实信息只能用已核实资料。"],"subtext":["他知道一条船渡不了多少人，可他更知道，硬塞只会让大家都回不来。"],"cues":["补漏时桐油的气味、麻丝的手感，可在画面与文字上给到；检查合格前船身会显示\"未就绪\"标识。"],"outcomeNotes":["结果变体：","分工清晰：上船与接应节奏顺畅。","未分工：拥挤、等待（具体反馈）。"],"memory":["写入 boat_team_ch06 = 分工。"],"voice":["情绪＝干练（brisk）。船工：短、实；后勤协作员：快。"]}},{"id":"06-03","nodeId":6,"part":3,"title":"选择本组配合方式","sourceParagraph":982,"opening":[{"speaker":"何文","npcId":"he_wen","text":"各归各位，按岗位上。谁守哪一摊，别串。","label":"何文","guards":[]}],"responses":[{"speaker":"何文","npcId":"he_wen","text":"职权圈里的事，你拍了就算数。探出圈外半步，先回头问我一声。","label":"我这组的配合法子","guards":[],"intent":"plan"},{"speaker":"何文","npcId":"he_wen","text":"这么分派不当？理由讲出来，咱们再调。","label":"这么分工不合适","guards":[],"intent":"disagree"},{"speaker":"何文","npcId":"he_wen","text":"冲锋带队，不是你这个岗位的事。把自己那一摊磨亮，就是头功。","label":"我一个卫生员，也想带队冲锋","guards":[],"intent":"boundary"},{"speaker":"何文","npcId":"he_wen","text":"你问的是自己的差事，还是旁人的？","label":"自己该干什么，没想好","guards":[],"intent":"unclear"}],"roles":{},"outcomes":[],"fallback":[{"speaker":"何文","npcId":"he_wen","text":"各管一段，不越位。","label":"","guards":[]}],"closing":[{"speaker":"何文","npcId":"he_wen","text":"就照这一份干。","label":"","guards":["quantity"]}],"metadata":{"scene":["河滩一棵老树下，何文把本组的人和物归了归。树下摆着绳、板、担架；河水在几步外轰响。岗位搭档站在玩家一侧，等着领具体的事。"],"historyAnchor":["强渡中的基层分工，按职务各司其责，不越权、不空谈。（档案框架）"],"characterState":["何文最看重\"各守其位\"——他最怕战士想指挥、医护想冲锋，好心办了坏事。"],"npc":["何文、岗位搭档"],"trigger":["玩家选择本组在渡河中的配合方式时。"],"preconditions":["四种岗位权限各异，不得越位。"],"subtext":["他不是压制谁，是想让每个人都在\"能救命\"的位置上，而不是在\"想立功\"的位置上。","岗位版本（必须区分权限）：","连长：何文：「你把基层分组、叫口令、出了问题往上报。别一个人冲在前头。」","战士：何文：「你执行已经受领的任务，先把自己的位置站好。」","后勤：何文：「你保障船上的东西，把补给接上岸。」","医护：何文：「你在岸上备好包扎，来一个接一个。」"],"cues":["确定分工后，本组各人回到各自位置，画面从\"散\"变\"序\"——一眼看出队伍立住了。"],"outcomeNotes":["结果变体：岗位配合方式影响后续协作反馈，不改变渡河史实。"],"memory":["写入 role_in_crossing_ch06 = 配合方式。"],"voice":["情绪＝明确、有序（clear）。何文：稳、清，关键词略重。"]}},{"id":"06-04","nodeId":6,"part":4,"title":"自由协同计划","sourceParagraph":1009,"opening":[{"speaker":"联络员","npcId":"liaison_1","text":"你这盘计划里，几时发信号、几时候着、哪个接应——一条一条报清楚。","label":"联络员","guards":[]}],"responses":[{"speaker":"联络员","npcId":"liaison_1","text":"信号一响就开渡？对岸还没预备停当，人过去也是干杵着。","label":"协同计划我拟好了","guards":[],"intent":"plan"},{"speaker":"何文","npcId":"he_wen","text":"能用的家底摆着：信号、人、船。三样，再多没有了。","label":"信号、人、船，家底亮一亮","guards":[],"intent":"status"},{"speaker":"联络员","npcId":"liaison_1","text":"信号是多余的？那对岸凭什么晓得我们到了水边？","label":"信号是多余的一环","guards":["conditional"],"intent":"disagree"},{"speaker":"何文","npcId":"he_wen","text":"这一仗史书上写得明白。眼下，先看你的信号亮不亮。","label":"这一仗，史书怎么说？","guards":[],"intent":"history"}],"roles":{},"outcomes":[],"fallback":[{"speaker":"联络员","npcId":"liaison_1","text":"信号、时辰、接应，三笔账都写进计划。","label":"","guards":[]}],"closing":[{"speaker":"联络员","npcId":"liaison_1","text":"就依你的章程传令。","label":"","guards":[]}],"metadata":{"scene":["河滩上游一处石坎后，联络员摊开一张湿了边的纸，上面记着信号与时辰。何文蹲在一旁，用石子压住纸角。风大，纸哗哗响。"],"historyAnchor":["强渡需事先约定联络信号、出发时机与岸上接应条件。（档案框架）"],"characterState":["联络员最怕\"信号发了没人接、接了没人动\"；他一遍遍问，是想把每一步都咬合上。"],"npc":["联络员、何文"],"trigger":["玩家提交一份自由填写的协同计划后。"],"preconditions":["计划需回应联络信号、等待时机、接应条件。"],"subtext":["他知道，岸上慢一拍、船上快一拍，差的可能就是一条船、几条命。"],"cues":["纸上三条线——\"信号\"\"等待\"\"接应\"——被逐一点亮或留暗，缺口一目了然。"],"outcomeNotes":["结果变体：","条件齐备：联络、时机、接应三环相扣。","缺时机：过早或过慢，触发等待或空跑（具体反馈）。"],"memory":["写入 synergy_plan_ch06 = 要点；plan_gaps_ch06 = [缺口]。"],"voice":["情绪＝缜密（precise）。联络员：中速、清楚；何文：稳。"]}},{"id":"06-05","nodeId":6,"part":5,"title":"渡河执行与状态反馈","sourceParagraph":1034,"opening":[{"speaker":"船工","npcId":"boatman_1","text":"浪头拍上船帮了！篙掌稳，后头坐住的把船舷抓牢！","label":"船工","guards":[]}],"responses":[{"speaker":"船工","npcId":"boatman_1","text":"要调船向？成，我这边压篙，你那侧的把身子压低，别乱动。","label":"调一下船头，避开浪头","guards":[],"intent":"plan"},{"speaker":"陈小满","npcId":"chen_xiaoman","text":"绳子我攥死了！你嘱咐他蹲低些——船帮太高！","label":"我把绳子攥紧了","guards":[],"intent":"support"},{"speaker":"陈小满","npcId":"chen_xiaoman","text":"这江水打转转……我不吭声，就是手不松。","label":"这浪头，怕人","guards":[],"intent":"fear"},{"speaker":"船工","npcId":"boatman_1","text":"心提到嗓子眼了？眼睛盯篙，别盯水——水越看越慌。","label":"别慌，看我的","guards":[],"intent":"comfort"},{"speaker":"船工","npcId":"boatman_1","text":"换航线？来不及了，咬住这条水道。","label":"这条水道不行，换！","guards":[],"intent":"disagree"}],"roles":{},"outcomes":[],"fallback":[{"speaker":"船工","npcId":"boatman_1","text":"盯住篙头，稳住腰杆！","label":"","guards":[]}],"closing":[{"speaker":"船工","npcId":"boatman_1","text":"船底擦到滩了，跳下去，往高处走！","label":"","guards":[]}],"metadata":{"scene":["小船离岸，立刻被急流托起又拉低。船工在船尾压篙，船头的人握紧船帮。浪花不断拍上船舷，水灌进舱里，有人用帽子往外舀。对岸的滩头，越来越近。"],"historyAnchor":["安顺场强渡中，小船在急流中往返，动作与水流、船况紧密相关。（档案）"],"characterState":["陈小满在船上，脸发白，却一声不吭地舀水；他知道自己一喊，别人就更慌。"],"npc":["船工、陈小满"],"trigger":["渡河执行中，出现水流变化或操作反馈时。"],"preconditions":["水流、船体动作与本组实际状态匹配。"],"subtext":["他吼的是口令，稳住的是人心——江上最怕的不是浪，是乱。"],"cues":["本关为节奏／配合玩法——玩家配合船工的号子点击或按键；配合到位则船身渐稳，失误则船体一晃、水声骤大，调整后可继续。"],"outcomeNotes":["结果变体（失误后调整，不随机牺牲真实人物）：","配合到位：船平稳靠岸。","操作失误：船身一荡，调整配合后可继续；不得随机宣告真实人物牺牲。"],"boundary":["不随机宣告真实人物牺牲；本组失误只影响本局任务。"],"memory":["写入 crossing_exec_ch06 = 结果。"],"voice":["情绪＝紧张（intense）。船工：吼、短促；陈小满：气声、颤。"]}},{"id":"06-06","nodeId":6,"part":6,"title":"岸上接应与下一步","sourceParagraph":1060,"opening":[{"speaker":"卫生员","npcId":"medic_1","text":"滩头搭了铺，上来一个，我看一个。","label":"卫生员","guards":["state"]}],"responses":[{"speaker":"卫生员","npcId":"medic_1","text":"破了皮的马上包，呛了水的先换干衣。躺着的这会儿别折腾他。","label":"伤员都安置好了吗？","guards":["state"],"intent":"comfort"},{"speaker":"后勤协作员","npcId":"logistics_1","text":"抬人的活你搭把手，货物点验归我。","label":"抬人的活算我一个","guards":[],"intent":"support"},{"speaker":"何文","npcId":"he_wen","text":"是先歇脚，还是先接下一船？这个次序，你来定。","label":"先歇脚，还是接下一船？","guards":["quantity"],"intent":"plan"},{"speaker":"旁白","npcId":"narrator","text":"强渡安顺场只是这一程的一个节点；再往后的事，档案另有一页。","label":"再往后，队伍往哪去？","guards":[],"intent":"history"},{"speaker":"卫生员","npcId":"medic_1","text":"你说的是哪一个？往这边带。","label":"（指的是哪个人，没说明白）","guards":[],"intent":"unclear"}],"roles":{},"outcomes":[],"fallback":[{"speaker":"卫生员","npcId":"medic_1","text":"岸边这批看完之前，不谈下一班船。","label":"","guards":["quantity"]}],"closing":[{"speaker":"旁白","npcId":"narrator","text":"队伍沿大渡河南岸溯流而上。二百四十里外，横着十三根铁索。","label":"","guards":[]}],"metadata":{"scene":["对岸滩头，先上的人回身拉船、接下船的人。有人跪在滩上大口喘气，有人仰面躺下。卫生员提着药箱快步过来，蹲下就翻看伤处。河水依旧在身后轰响。"],"historyAnchor":["安顺场强渡成功后，红军得以继续北上，其史实进程由档案说明。（档案）"],"characterState":["卫生员一到就开始干活，不问\"痛不痛\"，先看\"伤在哪\"——她懂，这时候安慰是奢侈品。"],"npc":["卫生员、旁白"],"trigger":["渡河完成、进入岸上接应与清点时。"],"preconditions":["以本组实际状态清点与照料。"],"subtext":["她心里有本账：谁先下船、谁伤得重，她比谁都清楚——所以她不慌。"],"cues":["接应时，镜头可给一个\"递手\"的特写——一只湿冷的、划破的手握住另一只手。"],"boundary":["","本组虚构任务：清点、照料、接应完成度。","历史线（旁白）：安顺场强渡的史实与历史进程（档案）。","不把安顺场强渡与飞夺泸定桥合成一次战斗。"],"outcomeNotes":["结果变体：只评价本组接应，不评价真实战果。"],"memory":["写入 marchLog += ch06。"],"voice":["情绪＝收束、关切（settling）。卫生员：稳、利落；旁白：平。"]}},{"id":"07-01","nodeId":7,"part":1,"title":"抵达桥头、观察铁索","sourceParagraph":1091,"opening":[{"speaker":"旁白","npcId":"narrator","text":"泸定桥头。十三根铁索凌空悬着，桥板大半被拆走，底下是打着旋的红褐色的水。","label":"旁白","guards":["quantity"]},{"speaker":"王贵","npcId":"wang_gui","text":"瞅见没有？桥板抽得一块不剩，空悬十三根铁索。这叫过索，不叫摆渡。","label":"王贵","guards":[]}],"responses":[{"speaker":"王贵","npcId":"wang_gui","text":"索子十三根：底下两根踩脚，中间两根扶手。手上抓牢上头的，脚底下扣死下头的。","label":"这十三根铁索，怎么个过法？","guards":["quantity"],"intent":"status"},{"speaker":"王贵","npcId":"wang_gui","text":"想先候风口过了再动？对，先瞧这索子晃到什么份上。","label":"先看风，再上","guards":[],"intent":"plan"},{"speaker":"王贵","npcId":"wang_gui","text":"咱这一仗是夺桥。摆渡是金沙江的旧账，别把两码事搅一块。","label":"这不就是渡船换了个地方","guards":[],"intent":"other"},{"speaker":"王贵","npcId":"wang_gui","text":"底下离水好几丈，腿软不丢人。手先挂上索，再挪脚。","label":"往下一望，腿肚子转筋","guards":["quantity"],"intent":"fear"},{"speaker":"王贵","npcId":"wang_gui","text":"你讲的是哪一根？手往那边点点。","label":"（指的是哪根索，说不清）","guards":[],"intent":"unclear"}],"roles":{},"outcomes":[],"fallback":[{"speaker":"王贵","npcId":"wang_gui","text":"索是空的，人是实的。过索，不叫摆渡。","label":"","guards":[]}],"closing":[{"speaker":"王贵","npcId":"wang_gui","text":"看真了，再上索。","label":"","guards":[]}],"metadata":{"scene":["泸定桥西桥头。十三根粗铁索横跨大渡河，桥面的木板大都被撤走，只在两端残留几块。铁索被风吹得轻晃，发出低沉的金属嗡鸣。桥下湍流撞着礁石，白浪翻涌，水声压过一切。东桥头隐约有火光。"],"historyAnchor":["一九三五年五月二十九日，红军奔袭泸定桥；夺桥时桥面木板多已撤除，突击队攀铁索前进。（档案）"],"characterState":["王贵站在桥头，先看的是铁索的松紧和风向——他知道，过索靠的不是胆子，是\"算\"。"],"npc":["王贵、旁白"],"trigger":["玩家进入第 07 章，抵达桥头观察时。"],"preconditions":["3D 画面为裸露铁索；桥下水流湍急。"],"subtext":["他先看、后说，是在给你留\"看清再动\"的时间——桥上慌一秒，就没命了。"],"cues":["镜头从桥下仰拍铁索与急流，再摇到东桥头的火光；风声与水声始终在底噪中。"],"outcomeNotes":["结果变体：无论岗位均进入桥头准备；硬性禁止称为渡船任务。"],"memory":["写入 chapter07_started = true；scene_is_luding_bridge = true。"],"voice":["情绪＝肃杀、紧绷（severe）。王贵：沙、沉，尾音压；旁白：庄重、克制。"]}},{"id":"07-02","nodeId":7,"part":2,"title":"分工与行动前交流","sourceParagraph":1115,"opening":[{"speaker":"何文","npcId":"he_wen","text":"摆正位置：咱们是配合的协作组，跟人家真正的突击队不是一回事。干好自己这一段。","label":"何文","guards":[]}],"responses":[{"speaker":"何文","npcId":"he_wen","text":"分段的路数可以。只是两段之间谁递给谁、怎么递，要说死。","label":"分段的打法，我说说","guards":[],"intent":"plan"},{"speaker":"何文","npcId":"he_wen","text":"不兴分组？那你拿个更稳的章程出来。","label":"不兴分组，一起上更利索","guards":[],"intent":"disagree"},{"speaker":"何文","npcId":"he_wen","text":"档案里那些名字，一个都不许往自己身上安。咱们是虚构的协作小组，各归各。","label":"我们就是教科书里那支突击队","guards":[],"intent":"other"},{"speaker":"何文","npcId":"he_wen","text":"全局的事，不到你我这一级。看好自己脚底下那一截。","label":"全局的仗，我来指挥","guards":[],"intent":"boundary"}],"roles":{},"outcomes":[],"fallback":[{"speaker":"何文","npcId":"he_wen","text":"协作小组，只做自己那一段。","label":"","guards":[]}],"closing":[{"speaker":"何文","npcId":"he_wen","text":"分段定了，各上各位。","label":"","guards":[]}],"metadata":{"scene":["西桥头一处石墙后，本组的人挤在一小片背风处。有人把麻绳缠在腰上，有人往鞋底绑布条防滑。桥那边，火光忽明忽暗，映在每个人脸上。"],"historyAnchor":["夺桥以突击队攀索突击、后续部队跟进与火力掩护协同完成；本组为虚构协作小组。（档案框架）"],"characterState":["何文把\"我们不是突击队\"这句话说在前头，是要你有荣誉感，又不起虚妄的念头。"],"npc":["何文、岗位搭档"],"trigger":["夺桥前，玩家与本组确定分工时。"],"preconditions":["普通战士与虚构协作小组的职责区分明确；不冒充真实突击队队员。"],"subtext":["他不许你冒名，是因为他知道，那些真正攀索的人，名字都在档案里——不能让虚构占了真实的位置。","岗位版本：","连长：何文：「你组织本组分批上索、盯联络，情况往上报。」","战士：何文：「你受领哪一段，就走哪一段，互相照应。」","后勤：何文：「你在桥头保障，把要用的垫脚料、绳递上去。」","医护：何文：「你在桥头待命，下来一个接一个。」"],"cues":["绑布条、缠麻绳的动作要实拍感——这些\"手上的准备\"是勇气的外化。"],"outcomeNotes":["结果变体：分工方式影响后续攀索反馈，不改史实。"],"memory":["写入 role_on_bridge_ch07 = 分工。"],"voice":["情绪＝严肃、克制（stern）。何文：低、稳，关键句顿。"]}},{"id":"07-03","nodeId":7,"part":3,"title":"玩家输入行动方案","sourceParagraph":1142,"opening":[{"speaker":"王贵","npcId":"wang_gui","text":"要怎么过，慢慢讲，我得听出个节奏来。","label":"王贵","guards":[]}],"responses":[{"speaker":"王贵","npcId":"wang_gui","text":"一股气冲到对岸？索子荡着，人又不是铁打的，半道就得脱力。","label":"我的过桥方案","guards":[],"intent":"plan"},{"speaker":"何文","npcId":"he_wen","text":"家当清点过了：索、绳、垫料、人。一样是一样。","label":"索、绳、垫料，家底有哪几样？","guards":[],"intent":"status"},{"speaker":"王贵","npcId":"wang_gui","text":"不妥当在哪儿，讲出来，另拟一稿。","label":"这打法要改，我说说","guards":[],"intent":"disagree"},{"speaker":"何文","npcId":"he_wen","text":"这件家什没有，那套打法也不是这个年头的。就着眼现有的，重新拿方案。","label":"要有冲锋舟和迫击炮掩护就好了","guards":[],"intent":"anachronism"}],"roles":{},"outcomes":[{"speaker":"王贵","npcId":"wang_gui","text":"对岸接应的缺口谁填？没人接，爬到一半就吊在索上，进退两难。","label":"缺支援","guards":[]}],"fallback":[{"speaker":"王贵","npcId":"wang_gui","text":"掩护、节奏、联络、接应——缺一环，这桥就过不去。","label":"","guards":[]}],"closing":[{"speaker":"王贵","npcId":"wang_gui","text":"章法定了，上索！","label":"","guards":[]}],"metadata":{"scene":["背风的石墙根下，王贵蹲着，用半截炭在石板上画桥——十三根竖线当铁索，横画几笔当缺口。何文在旁看着，风把炭灰吹散。"],"historyAnchor":["攀索夺桥需考虑配合、节奏、联络与支援，需依当时条件而非现代装备。（档案框架）"],"characterState":["王贵只信\"稳扎稳打\"；何文看的是\"退路与接应\"——两人一稳一全，替你把风险管理住。"],"npc":["王贵、何文"],"trigger":["玩家提交一份自由填写的夺桥行动方案后。"],"preconditions":["按配合、节奏、联络、支援四要素评估；不以现代装备或未经核实战法替代历史环境。"],"subtext":["他听过太多\"一鼓作气\"的漂亮话，最后都变成了\"回不来\"——所以他要听节奏，不要听口号。"],"cues":["石板上画出的\"动法\"会随选择改变——连贯的箭头＝稳进，堆叠的箭头＝强冲，直观呈现节奏差异。"],"outcomeNotes":["结果变体（相异方案，相异评价）：","快冲：省时，但体力与稳定风险高。","分段稳进：耗时，但可控、易接应。"],"memory":["写入 plan_ch07 = 要点。"],"voice":["情绪＝沉着（composed）。王贵：慢、顿；何文：稳。"]}},{"id":"07-04","nodeId":7,"part":4,"title":"攀索／桥头配合反馈","sourceParagraph":1168,"opening":[{"speaker":"陈小满","npcId":"chen_xiaoman","text":"攥死！索子荡起来了——别、别跟着我的节奏乱！","label":"陈小满","guards":[]}],"responses":[{"speaker":"陈小满","npcId":"chen_xiaoman","text":"对喽！就这个劲儿，一口气别泄！","label":"（踩准了他的节奏）","guards":[],"intent":"other"},{"speaker":"陈小满","npcId":"chen_xiaoman","text":"稳住稳住，脚掌横过来卡住索，急不得！","label":"（脚下踏空了半拍）","guards":[],"intent":"other"},{"speaker":"陈小满","npcId":"chen_xiaoman","text":"我腿肚子也在抖！可这手死也不能松——一松，就什么都没了。","label":"我也怕，可不能露怯","guards":[],"intent":"fear"},{"speaker":"陈小满","npcId":"chen_xiaoman","text":"都什么时候了还惦记我？管好你自个儿那颗扑通扑通的心！","label":"小满，自个儿抓牢！","guards":[],"intent":"comfort"},{"speaker":"陈小满","npcId":"chen_xiaoman","text":"先迈哪只脚，我自己数着拍子呢！别催！","label":"别催！我的拍子自己数","guards":[],"intent":"disagree"}],"roles":{},"outcomes":[{"speaker":"陈小满","npcId":"chen_xiaoman","text":"呼……气都倒不上来……可我这只手，还挂在索上呢！","label":"低体力·成功","guards":[]}],"fallback":[{"speaker":"陈小满","npcId":"chen_xiaoman","text":"攥死、踩实、跟拍子，一条都不能丢！","label":"","guards":[]}],"closing":[{"speaker":"陈小满","npcId":"chen_xiaoman","text":"桥那头了！手先莫松，等脚跟落定！","label":"","guards":["conditional"]}],"metadata":{"scene":["铁索上。手抓上链、脚踩下链，身下是翻卷的白浪，风把衣服吹得紧贴身体。铁索随动作一晃一晃，发出\"嗡——嗡——\"的颤音。对岸火光越来越近。"],"historyAnchor":["夺桥时突击队员徒手攀铁索前进，体力与配合是成败关键。（档案）"],"characterState":["陈小满的手心很快磨破，他咬着牙不吭声——不是不怕，是怕\"说出来就更怕\"。"],"npc":["陈小满"],"trigger":["玩家在攀索（QTE 连击）过程中的实时反馈。"],"preconditions":["把体力分档——高体力与低体力，成功与失误，反馈不同。"],"subtext":["他紧张到结巴，却仍在提醒你——他把自己活成了别人的扶手。"],"cues":["本关为 QTE 连击玩法——命中时铁索轻震、前景水花飞溅；失误时画面轻微摇晃、铁索\"嗡\"声放大。连击越高，攀进越快。"],"outcomeNotes":["结果变体（分档反馈）：","高体力·成功：动作连贯，攀进顺利。","高体力·失误：一滑，需重抓；提醒后调整。","低体力·失误：手部疲劳明显，需同伴提醒与短歇。"],"boundary":["害怕、手部疲劳、互相提醒必须写出；不循环受伤。"],"memory":["写入 climb_result_ch07 = 结果；relationship_chen = ±。"],"voice":["情绪＝急促（urgent）。陈小满：气声、喘、句短，紧张时结巴。"]}},{"id":"07-05","nodeId":7,"part":5,"title":"后续跟进与照料","sourceParagraph":1196,"opening":[{"speaker":"后勤协作员","npcId":"logistics_1","text":"前头递上来的先扶稳，铺桥板的事一件一件往前传，后头的道才好续。","label":"后勤协作员","guards":[]}],"responses":[{"speaker":"后勤协作员","npcId":"logistics_1","text":"搭手递板子？跟在我侧后方，手递手，别探身。","label":"铺板子的活，算我一个","guards":[],"intent":"support"},{"speaker":"卫生员","npcId":"medic_1","text":"手掌磨出血了？先裹上。这几日缰绳、背包带，都换只手拿。","label":"手都磨破了吧，歇口气","guards":[],"intent":"comfort"},{"speaker":"何文","npcId":"he_wen","text":"先接人，还是先续板？两桩事排个先后。","label":"先接人，还是先续板？","guards":[],"intent":"plan"},{"speaker":"后勤协作员","npcId":"logistics_1","text":"不铺板，让人从铁索上怎么过？你把你的道理再讲一遍。","label":"桥面够宽了，不用再铺","guards":[],"intent":"disagree"},{"speaker":"后勤协作员","npcId":"logistics_1","text":"桥板远远没铺齐。落到索上的就那几块，一块是一块，别把没做的当成做完的。","label":"桥早全铺好了，冲就是","guards":[],"intent":"other"}],"roles":{},"outcomes":[],"fallback":[{"speaker":"后勤协作员","npcId":"logistics_1","text":"先站稳人，再续板子。","label":"","guards":[]}],"closing":[{"speaker":"后勤协作员","npcId":"logistics_1","text":"这一段吃住了，记上一笔。","label":"","guards":[]}],"metadata":{"scene":["东桥头一侧的坡地上，先到的人回身接应，把垫脚料、绳、木板往桥头递。卫生员蹲在地上，用牙咬开绷带卷，替人缠手。桥还在，火光还在。"],"historyAnchor":["夺桥后续阶段有铺设桥板、巩固阵地等进程，具体须对应经核实的战斗阶段。（档案框架）"],"characterState":["后勤协作员嘴上催得急，手脚却一直没停；他知道\"跟进慢一拍，前面就白拼\"。"],"npc":["后勤协作员、卫生员"],"trigger":["夺桥后进入跟进保障与照料时。"],"preconditions":["跟进、接应、伤员照料；若写铺板，须对应经核实的战斗阶段。"],"subtext":["他喊的是\"好走些\"，心里想的是\"别让后面的人再摔\"。"],"boundary":["不把当前裸索画面说成\"已经全铺好\"；铺板须对应史实战斗阶段。"],"cues":["铺设桥板的进度以\"块\"为单位可见地增加，但明显未完成——画面本身就在纠正\"全铺好了\"的错觉。"],"outcomeNotes":["结果变体：","接应到位：后续人员通过更顺。","照料不足：伤员积压，提示需增加人手。"],"memory":["写入 followup_ch07 = 结果。"],"voice":["情绪＝忙碌、关切（busy-solicitous）。后勤协作员：急、糙；卫生员：短、实。"]}},{"id":"07-06","nodeId":7,"part":6,"title":"夺桥史实与个人行记","sourceParagraph":1222,"opening":[{"speaker":"旁白","npcId":"narrator","text":"飞夺泸定桥的前后经过，档案记得详细；你们亲历的，只是其中一段。","label":"旁白","guards":[]},{"speaker":"王贵","npcId":"wang_gui","text":"咱们这一组，力气使尽了，问心无愧。那些留下名姓的真勇士，档案里有他们一笔。","label":"王贵","guards":[]}],"responses":[],"roles":{},"outcomes":[],"fallback":[{"speaker":"王贵","npcId":"wang_gui","text":"咱们这段记下了。真勇士的名字，交给档案。","label":"","guards":[]}],"closing":[{"speaker":"旁白","npcId":"narrator","text":"天边泛白，队伍调头向南。夹金山，就在前头。","label":"","guards":[]}],"metadata":{"scene":["战斗间隙。桥头坡地上，人靠着石头歇息。有人把磨破的手摊开晾着，有人望着桥对岸出神。风小了，水声依旧。晨光一点点爬上山头。"],"historyAnchor":["飞夺泸定桥的史实与意义由档案说明；本组只回顾虚构小组行动。（档案）"],"characterState":["王贵抽着旱烟，望着铁索出神——他在想那些真实攀索的人，也在想自己这一组的年轻人。"],"npc":["旁白、王贵"],"trigger":["本章收束，进入史实说明与个人行记时。"],"preconditions":["历史结果固定；本局只回顾虚构小组行动。"],"subtext":["他把\"我们\"和\"他们\"分得很清——那是一种近乎虔诚的敬意。","回应与呈现：","个人行记：王贵据实复活玩家的分段、节奏、互助、照料行为。","玩家询问历史：旁白按档案叙述夺桥史实；不与角色当时认知混淆。","关心／安慰：王贵：「下来了就好。手还抖吧？缓一缓。」","要求给突击队排名或评分：王贵：（摆手）「谁第一谁第二，那不是你我说的。真勇士的事，不排名。」"],"cues":["镜头最后停在桥上的十三根铁索上，晨光沿索面反出一道细亮——静，胜过千言。"],"boundary":["","本组虚构任务：行动链与互助。","历史线（旁白）：飞夺泸定桥史实（档案）。","不以 AI 推演给真实勇士排名。"],"outcomeNotes":["结果变体：只记本组经历，不给真实战役打分。"],"memory":["写入 marchLog += ch07；promise（若在本章许下）。"],"voice":["情绪＝肃然、释然（solemn-relieved）。王贵：低、慢；旁白：庄重、有据。"]}},{"id":"08-01","nodeId":8,"part":1,"title":"山脚准备","sourceParagraph":1253,"opening":[{"speaker":"旁白","npcId":"narrator","text":"夹金山，当地人叫它神山。上行不到半程，风就换了性子，雪粒子打在脸上生疼。","label":"旁白","guards":[]},{"speaker":"王贵","npcId":"wang_gui","text":"抬眼就是雪线。这儿没有船桨，没有铁索，家什只有两条腿。","label":"王贵","guards":[]}],"responses":[{"speaker":"王贵","npcId":"wang_gui","text":"几时动身、走阳坡还是阴坡，一步差错，就是冻掉手指头的事。","label":"雪山有什么讲究，讲讲","guards":[],"intent":"status"},{"speaker":"王贵","npcId":"wang_gui","text":"先勒紧绑腿、灌口热的再爬？对。空着肚子上山，走不到半坡。","label":"我的登山安排","guards":[],"intent":"plan"},{"speaker":"王贵","npcId":"wang_gui","text":"船啊索啊，都翻篇了。这一程，比的是腿和这口气。","label":"又说起渡船和铁索的事","guards":[],"intent":"other"},{"speaker":"王贵","npcId":"wang_gui","text":"怕冷？人人都怕。可站住不动，冷得更狠——走起来才生热。","label":"这风雪，看得人心里发毛","guards":[],"intent":"fear"},{"speaker":"王贵","npcId":"wang_gui","text":"你问的是行装，还是道路？","label":"（问的是行装还是道路，没说清）","guards":[],"intent":"unclear"}],"roles":{},"outcomes":[],"fallback":[{"speaker":"王贵","npcId":"wang_gui","text":"雪山上没旁的巧，凭的就是两条腿。","label":"","guards":[]}],"closing":[{"speaker":"王贵","npcId":"wang_gui","text":"绑腿扎紧，动身。","label":"","guards":[]}],"metadata":{"scene":["夹金山脚下。抬头望去，山顶隐在云雾里，雪线以上一片惨白。山脚下的溪水结着薄冰，风从谷口灌进来，刮得人脸生疼。有人往鞋里塞辣椒叶，有人把薄毯裹在肩上。"],"historyAnchor":["一九三五年六月，红军翻越夹金山等大雪山，山高寒、空气稀薄。（档案）"],"characterState":["王贵在山脚下抬头看了很久——他上过山，知道山不认人，只认准备。"],"npc":["王贵、旁白"],"trigger":["玩家进入第 08 章，抵达雪山脚下时。"],"preconditions":["高寒环境；物资以现有为准。"],"subtext":["他特意说\"没有船、没有桥\"，是提醒你——别拿前几关的法子走这山。"],"cues":["呼出的白气、冻红的手、踩碎的薄冰——用最日常的三个细节立住\"冷\"。"],"outcomeNotes":["结果变体：无论岗位均进入山脚准备；禁止沿用渡运词、火力词。"],"memory":["写入 chapter08_started = true。"],"voice":["情绪＝严寒、凝重（frigid）。王贵：沙、慢，气声；旁白：冷、平。"]}},{"id":"08-02","nodeId":8,"part":2,"title":"被服和负重分担","sourceParagraph":1277,"opening":[{"speaker":"后勤协作员","npcId":"logistics_1","text":"棉衣拢共这些件，辣椒水小半罐。谁多穿一件，准有人少穿一件，这个谱你得拿。","label":"后勤协作员","guards":[]}],"responses":[{"speaker":"后勤协作员","npcId":"logistics_1","text":"棉衣缺着七八件，辣椒水只够先驱一回寒，家底薄得很。","label":"棉衣还缺几件？","guards":[],"intent":"status"},{"speaker":"后勤协作员","npcId":"logistics_1","text":"体弱的先添衣，那膀大腰圆的就得单衣顶风。担子压你肩上，接不接？","label":"体弱的先穿，我来排","guards":[],"intent":"plan"},{"speaker":"后勤协作员","npcId":"logistics_1","text":"把你那件脱给我？山上零下的风，你拿什么顶？想周全了再脱。","label":"我这件让给他","guards":[],"intent":"support"},{"speaker":"后勤协作员","npcId":"logistics_1","text":"新棉衣、热汤饭——梦里什么都有。睁眼还是这一堆，分吧。","label":"要是有热饭新棉衣就好了","guards":[],"intent":"other"},{"speaker":"后勤协作员","npcId":"logistics_1","text":"嫌分得不公道，重新来过。总账不动，翻来覆去还是这些件。","label":"这么分不公道，重分","guards":[],"intent":"disagree"}],"roles":{},"outcomes":[],"fallback":[{"speaker":"后勤协作员","npcId":"logistics_1","text":"衣裳有数，人心要平。","label":"","guards":[]}],"closing":[{"speaker":"后勤协作员","npcId":"logistics_1","text":"分定就动身，风不等人。","label":"","guards":[]}],"metadata":{"scene":["山脚一处避风的岩下，后勤协作员把过冬的家当摊开：几件旧棉衣、两条薄毯、一小瓶辣椒水、几根裹脚布。数量少得可怜，风一吹，布料边角乱翻。"],"historyAnchor":["翻越雪山时，御寒物资普遍紧缺，主要靠现有装备与相互分担。（档案，通识）"],"characterState":["后勤协作员手上有本\"冷暖账\"——他知道谁扛得住、谁扛不住，却也知道，无论怎么分都有人要挨冻。"],"npc":["后勤协作员"],"trigger":["玩家在山脚协商被服与负重分配时。"],"preconditions":["物资以现有实存为准；缺物资时不凭空变出棉衣和热食。"],"subtext":["他其实已经算出一套\"最小挨冻\"的方案，但他要你先说——因为挨冻的人，得由所有人都服气的人来定。"],"cues":["分配界面里，棉衣从一个\"格子\"挪到另一个\"格子\"，总数始终不变——用操作本身证明\"变不出物资\"。"],"outcomeNotes":["结果变体（禁止凭空生成物资）：","合理分担：体弱者少受冻，壮者承压。","分配失衡：出现受冻风险（具体反馈）。","所有增减必须与实际库存一致；不得凭空变出棉衣、热食。"],"memory":["写入 gear_split_ch08 = 分配。"],"voice":["情绪＝务实、清冷（practical-cold）。后勤协作员：快、实，尾音压。"]}},{"id":"08-03","nodeId":8,"part":3,"title":"战友体力下降","sourceParagraph":1303,"opening":[{"speaker":"陈小满","npcId":"chen_xiaoman","text":"不行了……指尖冻得不像自己的了。你先走两步，等等我。","label":"陈小满","guards":[]}],"responses":[{"speaker":"陈小满","npcId":"chen_xiaoman","text":"听你这么讲，胸口暖了半截。可这腿，还是灌了铅似的。","label":"撑住，我在这","guards":[],"intent":"comfort"},{"speaker":"陈小满","npcId":"chen_xiaoman","text":"你要替我背？那你自己那卷呢……那，成，我匀口气再爬。","label":"你的背包，我替你背","guards":[],"intent":"support"},{"speaker":"卫生员","npcId":"medic_1","text":"你反映得及时。我这就交代他挂到后队，一步不离人。","label":"得赶紧报告队长","guards":[],"intent":"other"},{"speaker":"陈小满","npcId":"chen_xiaoman","text":"……嗯，你们先走。我歇一歇就赶上。","label":"（顾不上他，自己赶路）","guards":[],"intent":"other"},{"speaker":"陈小满","npcId":"chen_xiaoman","text":"天旋地转，气不够喘，十个脚趾头一个都不听招呼。","label":"你到底什么感觉，说仔细点","guards":[],"intent":"status"}],"roles":{},"outcomes":[],"fallback":[{"speaker":"陈小满","npcId":"chen_xiaoman","text":"拉我一把，就一把……我还能挪。","label":"","guards":[]}],"closing":[{"speaker":"陈小满","npcId":"chen_xiaoman","text":"缓过这口了。走，我跟着。","label":"","guards":[]}],"metadata":{"scene":["半山腰，风更硬了，雪粒打在脸上像针扎。队伍走得很慢，脚印很快被雪盖住。陈小满落在后头几步，脸冻得发青，手插在袖筒里，脚步越来越沉。"],"historyAnchor":["高海拔行军中，体力下降、缺氧与严寒相互叠加，掉队风险极高。（档案，通识）"],"characterState":["陈小满最怕的不是冷，是\"拖累别人\"——所以他宁可硬撑，也不先开口。"],"npc":["陈小满、卫生员"],"trigger":["行军中陈小满出现体力下降时。"],"preconditions":["通过观察和询问表现疲惫；四种玩家反应分别反馈。"],"subtext":["他说\"跟不上了\"，其实还想说的是\"别丢下我\"——但他不敢说全。"],"cues":["陈小满的呼吸会随海拔变化加重、动作变慢；报告后他会被人扶到后队，独自前行则逐渐落后出画面。"],"outcomeNotes":["结果变体：","照料到位：陈小满缓过来，继续同行。","忽略：触发掉队，衔接 08-05。"],"boundary":["不循环受伤、不喊口号；成长依赖经历。"],"memory":["写入 care_chen_ch08 = 反应；relationship_chen = ±。"],"voice":["情绪＝关切（concerned）。陈小满：气声、虚弱、句短。"]}},{"id":"08-04","nodeId":8,"part":4,"title":"自由行军与互助计划","sourceParagraph":1329,"opening":[{"speaker":"王贵","npcId":"wang_gui","text":"队伍怎么列、强的怎么顾弱的，一样一样讲明白。","label":"王贵","guards":[]}],"responses":[{"speaker":"王贵","npcId":"wang_gui","text":"壮实的押后队，防的是掉队。只是后队走得最磨，得挑个耐得住性子的。","label":"行军队形我排好了","guards":[],"intent":"plan"},{"speaker":"王贵","npcId":"wang_gui","text":"脚力好的拢共那几个，按人头派，不能寅吃卯粮。","label":"能顶事的人手有哪几个？","guards":[],"intent":"status"},{"speaker":"王贵","npcId":"wang_gui","text":"要换列法，把道理摆到桌面上。","label":"这列法要换，我说说","guards":[],"intent":"disagree"},{"speaker":"王贵","npcId":"wang_gui","text":"全军怎么走，轮不着咱这组插手。把你这一段管好，比什么都强。","label":"全军都该照我的章程走","guards":[],"intent":"other"}],"roles":{},"outcomes":[],"fallback":[{"speaker":"王贵","npcId":"wang_gui","text":"列队、歇脚、传信、负重，四桩事排齐。","label":"","guards":[]}],"closing":[{"speaker":"王贵","npcId":"wang_gui","text":"就这么走，队形莫乱。","label":"","guards":[]}],"metadata":{"scene":["山腰一处背风的巨石后，队伍短暂歇脚。石头上铺着雪，人们挤在一小片无风处。王贵蹲在雪地上，用树枝画出一条\"队形线\"，标出前后照应。"],"historyAnchor":["雪上行军讲究队形照应、适时休整与负重合理分配，防止掉队与冻伤。（档案框架）"],"characterState":["王贵主张\"强壮的压队尾\"，理由是\"掉队的多是落在后头的\"；他自己就是压队尾的人。"],"npc":["王贵、岗位搭档"],"trigger":["玩家提交一份自由填写的行军互助计划后。"],"preconditions":["讨论队形照应、休整、联络、负重；需明确不同安排的取舍。"],"subtext":["他画这条线的时候，心里想的是湘江之后那些再没跟上来的人——这一次，不能再落下一个。"],"cues":["雪地上画出的队形线，会随方案实时改写；\"前后照应\"到位时，线条均匀，反之会出现孤零零的一个点。"],"outcomeNotes":["结果变体（不同安排不同取舍）：","前强后弱：防掉队，但队尾压力大。","强弱交错：互助方便，但队形拉长。","集中休整：恢复好，但耗时间、受冻更久。"],"memory":["写入 march_plan_ch08 = 要点。"],"voice":["情绪＝沉稳（steady）。王贵：慢、顿，压嗓。"]}},{"id":"08-05","nodeId":8,"part":5,"title":"风雪中失去照应","sourceParagraph":1355,"opening":[{"speaker":"联络员","npcId":"liaison_1","text":"雪幕合拢了，前后都望不见人影。点名，短了一个。","label":"联络员","guards":[]}],"responses":[{"speaker":"联络员","npcId":"liaison_1","text":"折回去寻？绳拴腰上再动身，谁也不许单溜。","label":"我回去把他找回来","guards":[],"intent":"plan"},{"speaker":"陈小满","npcId":"chen_xiaoman","text":"算我一个！雪窝子里两个人搭伙，总比一个人强。","label":"一起去，两人搭伙","guards":[],"intent":"support"},{"speaker":"联络员","npcId":"liaison_1","text":"都稳住，先把散掉的人往一处拢。","label":"都别慌，先拢人","guards":[],"intent":"comfort"},{"speaker":"陈小满","npcId":"chen_xiaoman","text":"只是这风雪天折回去……万一连我们也叫雪盖住了呢？","label":"风雪这么大……真要回头？","guards":[],"intent":"fear"},{"speaker":"联络员","npcId":"liaison_1","text":"不寻了？那这个决断，得由你签字画押。","label":"不能为他一个人停队伍","guards":[],"intent":"disagree"}],"roles":{},"outcomes":[],"fallback":[{"speaker":"联络员","npcId":"liaison_1","text":"白茫茫望不见人，先拢人再赶路。","label":"","guards":[]}],"closing":[{"speaker":"联络员","npcId":"liaison_1","text":"人齐了，开拔。","label":"","guards":[]}],"metadata":{"scene":["山脊上，风雪骤紧，天地一片浑白，三五步外就看不见人。队伍被迫停下点名——声音喊出去，很快被风吞掉。有人发现少了一个。"],"historyAnchor":["雪山大风会造成能见度骤降、队伍失散，是行军中极危险的情况。（档案，通识）"],"characterState":["联络员心里发紧——他认得路，却认不出风雪里的脚印；他知道，回头找，自己也可能出事。"],"npc":["联络员、陈小满"],"trigger":["风雪中队伍失散或有人掉队时。"],"preconditions":["行动失败可请求协助或重新组织。"],"subtext":["他想立刻回头，但风太大，他得先\"有个妥当的法子\"才敢动——冲动回头的，都容易被留下。"],"cues":["风雪中画面几乎全白，脚步声与喘息声被风放大；回去找人时，镜头随绳索一点点没入白雾。"],"outcomeNotes":["结果变体（不把狂点等同意志）：","重新组织：收拢队伍，找回掉队者。","继续前行：触发具体后果（掉队者落后，需后续应对）。","硬性提示：不把\"继续疯狂点击\"等同于\"意志坚定\"；本关对连续无意义点击不作为\"坚毅\"评价，只如实反馈状态。"],"memory":["写入 lost_contact_ch08 = 处理。"],"voice":["情绪＝焦急、风雪感（frantic-whiteout）。联络员：吼、短；陈小满：颤、气。"]}},{"id":"08-06","nodeId":8,"part":6,"title":"下山清点与关系回声","sourceParagraph":1381,"opening":[{"speaker":"陈小满","npcId":"chen_xiaoman","text":"下山了！上头那一场，要不是你……（视玩家当日选择而定）","label":"陈小满","guards":[]}],"responses":[],"roles":{},"outcomes":[],"fallback":[{"speaker":"陈小满","npcId":"chen_xiaoman","text":"脚后跟冻裂了口子。走得慢，你耐着性子等我一等。","label":"","guards":[]}],"closing":[{"speaker":"旁白","npcId":"narrator","text":"山那头望下去，是一片望不到边的灰绿色。都说，草地比雪山更不留情面。","label":"","guards":[]}],"metadata":{"scene":["山那一边，海拔渐低，风雪停了。脚下是碎石坡，远处能看见绿色的林线。人们松了绑腿，瘫坐在石头上，靴子里的雪化成水。陈小满把冻僵的手凑到嘴边呵气。"],"historyAnchor":["翻越雪山后，队伍继续北上；其史实背景由档案说明。（档案）"],"characterState":["陈小满缓过来后，第一件事是找玩家——他记得谁在山上扶过他。"],"npc":["陈小满、旁白"],"trigger":["翻越完成、山下清点时。"],"preconditions":["回忆玩家此前是否帮忙、是否兑现承诺；不把所有人状态重置为完好。"],"subtext":["他把\"多亏\"只说半句——剩下的，他要看你到底做没做。","回应与呈现：","关系回声：若玩家本章或前章确实帮过陈小满（helped_ally_ch01、care_chen_ch08 等），他据实致谢；没有记录则不提，可改为沉默或自顾。","承诺兑现核查：若玩家曾许下 promise_01 类承诺，此处核查是否兑现：兑现则有释然，未兑现则有疑问或遗憾，不无限拔高。","询问现状：陈小满：「脚上冻裂了，走慢点没事。」","关心／安慰：陈小满：（笑笑）「你顾好自己就行，我扛得住。」","问历史／未来：旁白：「往后的路，档案有载。」（不预知）"],"cues":["冻裂的脚、结霜的眉毛、化雪的靴子——恢复不是\"满血\"，是\"带着伤往下走\"。"],"boundary":["","本组虚构任务：翻越互助记录与资源消耗。","历史线（旁白）：翻越雪山的史实背景（档案）。","不把所有人状态重置成完好无损；伤病、疲惫延续到后续章节。"],"outcomeNotes":["结果变体：状态延续，不\"整队无损\"。"],"memory":["写入 marchLog += ch08；relationship_chen 更新；state_persist = {伤病, 疲劳}。"],"voice":["情绪＝疲惫、低回（weary-muted）。陈小满：沙、慢、鼻音；旁白：平。"]}},{"id":"09-01","nodeId":9,"part":1,"title":"进入草地","sourceParagraph":1412,"opening":[{"speaker":"旁白","npcId":"narrator","text":"草地行到深处，天和地成了一样的颜色。草面子底下藏着水，一脚深一脚浅，全凭试探。","label":"旁白","guards":[]},{"speaker":"向导","npcId":"guide_1","text":"草面子底下全是水，眼见的道未必是真道。跟紧我踩出来的脚印，一步都别抢。","label":"向导","guards":[]},{"speaker":"向导","npcId":"guide_1","text":"翻雪山那阵你说过，先把自己这组的脚力稳住，才轮得到帮旁人。这话搁草地里更顶用——这儿比雪山还耗人。","label":"回响·雪山脚力","guards":[],"echo":"8-keep"},{"speaker":"向导","npcId":"guide_1","text":"听你们队里讲，过山那回是搀着走过来的。草地照这个走法：绳拴腰上，一个牵一个，单飞的最容易没。","label":"回响·雪山结伴","guards":[],"echo":"8-share"}],"responses":[{"speaker":"向导","npcId":"guide_1","text":"哪片是干草甸、哪片是泥潭，面上瞧不出高低。我拿竹竿头前探，探一段走一段，急不得。","label":"这草地到底怎么个走法？","guards":[],"intent":"status"},{"speaker":"向导","npcId":"guide_1","text":"想凭罗盘走直线？这雾一起，十步开外就转了向。得盯着草墩子和远山的棱线，一段一段校着走。","label":"我画了条行进线","guards":[],"intent":"plan"},{"speaker":"向导","npcId":"guide_1","text":"图上那几个点，是给你们引路的记号，跟当年队伍实打实踩出来的道是两码事，莫要混为一谈。","label":"照地图上的点走就行","guards":[],"intent":"history"},{"speaker":"向导","npcId":"guide_1","text":"白天草地上还能瞧见人影，天一擦黑，连东西南北都没了。赶路要趁晌午前。","label":"一眼望不到头，心里发瘆","guards":[],"intent":"fear"},{"speaker":"向导","npcId":"guide_1","text":"你指的是哪一块？往那边比划比划。","label":"（指的是哪片草地，没说清）","guards":[],"intent":"unclear"}],"roles":{},"outcomes":[],"fallback":[{"speaker":"向导","npcId":"guide_1","text":"草底下是水窝子，拿不准就停下。","label":"","guards":[]}],"closing":[{"speaker":"向导","npcId":"guide_1","text":"绳子系好，一个挨一个。","label":"","guards":[]}],"metadata":{"scene":["草地边缘。天色灰蒙蒙，看不到地平线。脚下是草墩与黑水交错，踩下去\"咕叽\"一声，草墩没入水中。远处有几株孤树，更远处是一层层翻涌的云。空气里有腐草的腥气。"],"historyAnchor":["一九三五年八月，红军穿越松潘草地，地形为水草沼泽，辨认道路极难。（档案）"],"characterState":["向导是本地人，识路但也忌惮这片草地——他说\"我也不敢打包票\"，是真话，不是推脱。"],"npc":["旁白、向导／联络员"],"trigger":["玩家进入第 09 章，踏入草地时。"],"preconditions":["地形开阔、水草覆盖暗沼；认路困难。"],"subtext":["他先戳草墩再说话——用动作告诉你，\"我说的每一句，都是踩出来的\"。"],"cues":["脚下每次落点，草墩都会下沉再弹起；用长棍探路时，棍尖触到的\"底\"深浅不一——危险可感。"],"outcomeNotes":["结果变体：无论岗位均进入草地行军；不宣称游戏坐标即史实路线。"],"memory":["写入 chapter09_started = true。"],"voice":["情绪＝茫远、警惕（vast-wary）。向导：方言、低，尾音沉；旁白：空旷。"]}},{"id":"09-02","nodeId":9,"part":2,"title":"盘点口粮和饮水","sourceParagraph":1436,"opening":[{"speaker":"后勤协作员","npcId":"logistics_1","text":"炒面还剩多少、水囊几个空的，摊开看。分法你来提。","label":"后勤协作员","guards":[]}],"responses":[{"speaker":"后勤协作员","npcId":"logistics_1","text":"炒面撑两顿整，盐巴罐底都刮光了，饮水必须烧沸再进嘴。","label":"粮和水还剩多少？","guards":["quantity"],"intent":"status"},{"speaker":"王贵","npcId":"wang_gui","text":"省着嚼？道理不错。可草甸子上消耗大，饿着肚子走不出十里。","label":"我打算省着分","guards":[],"intent":"plan"},{"speaker":"后勤协作员","npcId":"logistics_1","text":"把自己那份也让出去？后头没粮的日子，你拿什么填？","label":"我这份匀给你","guards":[],"intent":"support"},{"speaker":"王贵","npcId":"wang_gui","text":"草皮底下的吃食，认不真的千万别往嘴里送。中一回毒，比饿三天还难救。","label":"草地里野菜随便采着吃","guards":[],"intent":"other"},{"speaker":"后勤协作员","npcId":"logistics_1","text":"说不公道就重分。米缸见底，怎么翻都是这个数。","label":"分得不公，重分","guards":[],"intent":"disagree"}],"roles":{},"outcomes":[],"fallback":[{"speaker":"王贵","npcId":"wang_gui","text":"野菜入口前先过三道眼，认不准就饿着。","label":"","guards":[]}],"closing":[{"speaker":"后勤协作员","npcId":"logistics_1","text":"口粮照此分摊，水一律烧透再喝。","label":"","guards":[]}],"metadata":{"scene":["一处稍干的草坡上，队伍歇脚。后勤协作员把干粮袋翻过来抖了抖，倒出一小撮炒面，又抖了抖，没了。有人蹲在草墩上看那黑水——水要沉淀、要烧开才敢喝。"],"historyAnchor":["草地行军补给极端困难，粮食与饮水需精打细算，野外食物不可随意取食。（档案，通识）"],"characterState":["后勤协作员掂着那点炒面，脸上没表情，指节却发白——他清楚这点东西撑不到头。"],"npc":["后勤协作员、王贵"],"trigger":["玩家清点口粮与饮水时。"],"preconditions":["只谈实际剩余量、分配与补给不确定性。"],"subtext":["他把袋子倒给你看，不是哭穷，是让你自己看清\"就这么多\"。"],"cues":["分配时，干粮袋里的炒面以肉眼可见的速度变少；试图\"变出\"食物会失败并提示\"草地不产粮\"。"],"outcomeNotes":["结果变体（禁止凭空生成）：","合理分配：够撑到预定补给点。","分配失衡：出现饿、渴风险（具体反馈）。","硬性提示：不把野外食物都写成可安全食用。"],"memory":["写入 rations_ch09 = 分配。"],"voice":["情绪＝精打细算（frugal）。后勤协作员：平、实；王贵：沙、稳。"]}},{"id":"09-03","nodeId":9,"part":3,"title":"陷入泥泞与援助","sourceParagraph":1462,"opening":[{"speaker":"陈小满","npcId":"chen_xiaoman","text":"脚底下空了——！快，捞我一把！","label":"陈小满","guards":[]}],"responses":[{"speaker":"王贵","npcId":"wang_gui","text":"趴下去，把棍子横着递。站着拽是害他——两个人一起陷。","label":"趴下！把棍子递过去","guards":[],"intent":"support"},{"speaker":"陈小满","npcId":"chen_xiaoman","text":"别、别都围过来！我自己扒着草根能上去……（越挣越深）","label":"我自己能上来","guards":[],"intent":"other"},{"speaker":"王贵","npcId":"wang_gui","text":"你俩头前拉，我后头垫草垫。各管一摊，同时动。","label":"你俩拉，我垫草","guards":[],"intent":"other"},{"speaker":"陈小满","npcId":"chen_xiaoman","text":"娘诶……魂都吓掉了半条。多谢，多谢你。","label":"吓着了吧？没事了","guards":[],"intent":"comfort"},{"speaker":"王贵","npcId":"wang_gui","text":"不服这个法子？那你趴下来做个样子。","label":"你那法子不成","guards":[],"intent":"disagree"}],"roles":{},"outcomes":[],"fallback":[{"speaker":"王贵","npcId":"wang_gui","text":"人趴平，棍横递。","label":"","guards":[]}],"closing":[{"speaker":"王贵","npcId":"wang_gui","text":"出泥坑了。鞋呢？鞋捞上来没有？","label":"","guards":[]}],"metadata":{"scene":["一片不起眼的绿草下是软底，前头一个人刚踩上去，身体就往下陷——先是脚踝，再是膝盖。他抓住身边的草，草也跟着沉。周围的人立刻散开，不敢再近。"],"historyAnchor":["草地沼泽暗藏，踩空下陷是常见危险，救援须低姿、借杆、受力分散。（档案，通识）"],"characterState":["陈小满头一个冲过去，被王贵一把拽住——他急着救人，王贵急着不让他也陷进去。"],"npc":["陈小满、王贵"],"trigger":["有人陷入泥沼、需要协助时。"],"preconditions":["具体求助、协作与反馈；接受帮助／独自逞强／重新分工结果不同。"],"subtext":["他喊的是\"拉我\"，其实是\"别让我一个人在这儿\"——陷在泥里的人最怕的不是深，是没人敢靠近。"],"cues":["下陷者身体缓慢下沉、泥面翻泡；施救时\"低姿＋借杆＋后人垫草\"三招缺一，效果明显不同。"],"outcomeNotes":["结果变体（三种结果不同）：","接受帮助：快速脱险，关系升温。","独自逞强：耗时、耗力，可能轻伤。","重新分工：更稳，但更慢。"],"memory":["写入 mud_rescue_ch09 = 结果；relationship_chen = ±。"],"voice":["情绪＝惊险（perilous）。陈小满：尖叫后转气声、颤；王贵：急而不乱、短促。"]}},{"id":"09-04","nodeId":9,"part":4,"title":"自定义寻路与行军方案","sourceParagraph":1488,"opening":[{"speaker":"向导","npcId":"guide_1","text":"你把想走的道讲一遍，我来对这片草地的底。","label":"向导","guards":[]}],"responses":[{"speaker":"向导","npcId":"guide_1","text":"直奔西边？那一半我只摸到半程，再往里是深是浅没人晓得。要去，就得拿人去赌。","label":"我的行军路线","guards":[],"intent":"plan"},{"speaker":"何文","npcId":"he_wen","text":"干粮撑两日，人越走越沉。排日程，就照这两条算。","label":"干粮撑几天，心里有个数","guards":["quantity"],"intent":"status"},{"speaker":"向导","npcId":"guide_1","text":"改方向，成。先把改的道理讲给我听，讲得通我就带你走。","label":"直插西边最近","guards":[],"intent":"disagree"},{"speaker":"向导","npcId":"guide_1","text":"荒滩野岭，方圆几十里没有人烟。粮食不会从天上掉下来，省着肚子想正事。","label":"要是有补给站接应就好了","guards":[],"intent":"other"}],"roles":{},"outcomes":[],"fallback":[{"speaker":"向导","npcId":"guide_1","text":"这片洼地存不住粮，指望不上外头接济。","label":"","guards":[]}],"closing":[{"speaker":"向导","npcId":"guide_1","text":"按定好的道走，散不得。","label":"","guards":[]}],"metadata":{"scene":["草坡高处，向导用长棍在湿泥上画出几条可能的路：一条绕远、一条直插、一条半绕半插。泥上的线很快被渗水吃掉，只剩浅浅的痕。"],"historyAnchor":["草地无既定道路，行军多靠向导经验、地形判断与反复试探。（档案）"],"characterState":["向导画的两条\"近路\"，都被他自己标了问号——他画的不是答案，是\"赌哪一条\"。"],"npc":["向导、何文"],"trigger":["玩家提交一份自由填写的寻路与行军方案后。"],"preconditions":["须回应信息不足、队伍照应、物资代价。"],"subtext":["他见识过\"嘴上说得通、脚下走不通\"，所以他只信\"能不能落到地上\"。"],"cues":["泥上的路线会随玩家选择被\"走\"一遍——直插的线走到中途会断（被沼泽截断），绕远的线则细而长。"],"outcomeNotes":["结果变体（硬性）：","稳妥绕行：慢，但全员跟上。","冒险直插：快，但可能折返或失散。","禁止：玩家输入一句话即\"发现捷径和补给站\"。"],"memory":["写入 route_plan_ch09 = 要点。"],"voice":["情绪＝审慎（prudent）。向导：低、慢；何文：稳。"]}},{"id":"09-05","nodeId":9,"part":5,"title":"宿营与分享","sourceParagraph":1514,"opening":[{"speaker":"陈小满","npcId":"chen_xiaoman","text":"挤到火堆边来，这儿才有点人气。锅里就剩这一口了，你先来一勺？","label":"陈小满","guards":[]}],"responses":[{"speaker":"卫生员","npcId":"medic_1","text":"把压箱底那一口也散出去？散完明天你拿什么撑？想好了，再来找我。","label":"我这份口粮，你多吃点","guards":[],"intent":"support"},{"speaker":"陈小满","npcId":"chen_xiaoman","text":"想家了？我娘擀的那碗汤面，撒一把葱花……我梦见过三回了。","label":"想家了吧？说说","guards":[],"intent":"comfort"},{"speaker":"陈小满","npcId":"chen_xiaoman","text":"你说你不恋家？骗鬼咧。出门在外，谁不恋。","label":"不想！行军还顾得上想家","guards":[],"intent":"disagree"},{"speaker":"陈小满","npcId":"chen_xiaoman","text":"这几夜我总听见草地里有人叫名字。兴许是风……兴许不是。","label":"夜里……我好像听见有人喊","guards":[],"intent":"fear"},{"speaker":"陈小满","npcId":"chen_xiaoman","text":"啊？你讲啥？火一烤，脑子发木。","label":"（火边恍惚，没接上话）","guards":[],"intent":"unclear"}],"roles":{},"outcomes":[],"fallback":[{"speaker":"陈小满","npcId":"chen_xiaoman","text":"锅底就这些了，你先舀。","label":"","guards":[]}],"closing":[{"speaker":"陈小满","npcId":"chen_xiaoman","text":"睡吧睡吧，天亮还要赶路。","label":"","guards":[]}],"metadata":{"scene":["夜里的草地，一堆半湿的牛粪火勉强燃着，冒着呛人的烟。人们围成一圈，有水汽从衣服上腾起。远处草丛里，不知名的虫子在叫。星子很亮，冷得刺人。"],"historyAnchor":["草地宿营条件极差，燃料、食物、御寒均短缺，队伍靠相互照应支撑。（档案，通识）"],"characterState":["陈小满守着火堆，宁可自己少烤一会，也要把好的位置让给别人——这是他一路学着做的事。"],"npc":["陈小满、卫生员"],"trigger":["草地宿营、分食时。"],"preconditions":["真实资源决定是否能分享；可谈牵挂与恐惧。"],"subtext":["他嘴上说\"谁多吃点\"，眼睛却瞟着别人——他其实是在等人先动。"],"cues":["火堆的光在每个人脸上跳；分享时，食物真的从一人手里递到另一人手里——资源不足时，界面会诚实地说\"这顿给不了\"。"],"outcomeNotes":["结果变体：","有粮可分享：温暖，关系升温。","资源不足无法分享：如实说明\"这顿给不了\"，不硬拗成全队充足。"],"boundary":["不灌输现代网络口号；牵挂、恐惧以人物本真口吻表达。"],"memory":["写入 share_camp_ch09 = 结果；relationship_chen = ±。"],"voice":["情绪＝温暖而苍凉（warm-desolate）。陈小满：低、缓，带鼻音；卫生员：轻、稳。"]}},{"id":"09-06","nodeId":9,"part":6,"title":"走出草地后的行记","sourceParagraph":1540,"opening":[{"speaker":"王贵","npcId":"wang_gui","text":"草甸子甩在身后了。回头望望，还认得出哪一道是咱们踩出来的辙？","label":"王贵","guards":[]}],"responses":[],"roles":{},"outcomes":[],"fallback":[{"speaker":"王贵","npcId":"wang_gui","text":"人出来了，人都活着，就是全脱了形。","label":"","guards":[]}],"closing":[{"speaker":"旁白","npcId":"narrator","text":"出了草地，队伍一路向北。川甘交界处，一道隘口扼住了去路。","label":"","guards":[]}],"metadata":{"scene":["草地尽头，地势渐渐升高，脚下终于有了硬地。回头望去，那片水草荒原灰蒙蒙地铺在身后，像一片沉默的海。有人坐在石头上系鞋带，鞋帮早已开裂。"],"historyAnchor":["一九三五年八月，红军走出松潘草地，继续北上；其史实背景由档案说明。（档案）"],"characterState":["王贵回头看了很久那片草地——他数过进去多少人，也数过出来多少人，但他不说数字，只说\"人都在\"。"],"npc":["王贵、旁白"],"trigger":["走出草地、本章收束时。"],"preconditions":["把互助记录、资源消耗与历史背景相连。"],"subtext":["他问的是草地的路，其实在说：这一段，走出去的人，心里都得留个记。","回应与呈现：","行记回顾：王贵据实复活玩家的辨路、分配、施救、分享行为，并与实际资源消耗关联。","询问现状：王贵：「人都在，就是瘦了一圈，鞋也豁了口。」","关心／安慰：王贵：「这段熬过来了，往后就好走些。」","问历史／未来：旁白：「前方的腊子口，是另一道坎。」（档案，不预知细节）"],"cues":["镜头从队伍的脚印平移向身后无边草地，再切回前方渐高的山影——不用一句台词，就把\"穿越\"写出来。"],"boundary":["","本组虚构任务：互助与消耗。","历史线（旁白）：穿越草地的史实背景（档案）。","不捏造统一适用于所有部队的细节；只记本组所历。"],"outcomeNotes":["结果变体：只回顾本组，不放大为\"全军的必然\"。"],"memory":["写入 marchLog += ch09。"],"voice":["情绪＝疲惫、回望（haggard-reflective）。王贵：沙、慢；旁白：平、远。"]}},{"id":"10-01","nodeId":10,"part":1,"title":"抵近峡口","sourceParagraph":1570,"opening":[{"speaker":"旁白","npcId":"narrator","text":"腊子口。两壁如刀劈斧削，抬头只见一线天；口子里那条独路，绕是绕不开的。","label":"旁白","guards":[]},{"speaker":"联络员","npcId":"liaison_1","text":"这地方就是一线石缝。钻过去，天就宽了。","label":"联络员","guards":[]}],"responses":[{"speaker":"联络员","npcId":"liaison_1","text":"隘口、木桥、碉堡、绝壁，全挤在前头那一小把地方。","label":"这道隘口，什么情形？","guards":[],"intent":"status"},{"speaker":"联络员","npcId":"liaison_1","text":"先侦察还是先扑？这道石缝，容不得半点莽撞。","label":"我的进攻协同","guards":[],"intent":"plan"},{"speaker":"联络员","npcId":"liaison_1","text":"这里没江没船，只有崖和缝。前头渡江那套，一字都用不上。","label":"又拿渡江那套来套","guards":[],"intent":"other"},{"speaker":"联络员","npcId":"liaison_1","text":"崖是陡。可除此之外，上天无路。","label":"两壁夹一缝，瘆人","guards":[],"intent":"fear"},{"speaker":"联络员","npcId":"liaison_1","text":"你讲的是哪一侧的崖？","label":"（指的是哪面崖，没讲明）","guards":[],"intent":"unclear"}],"roles":{},"outcomes":[],"fallback":[{"speaker":"联络员","npcId":"liaison_1","text":"眼前是崖和缝，没江也没船。","label":"","guards":[]}],"closing":[{"speaker":"联络员","npcId":"liaison_1","text":"先趴下，把口子看仔细。","label":"","guards":[]}],"metadata":{"scene":["腊子口外。两侧是刀劈般的峭壁，谷底一条急流，水声在峡谷里被放大成轰鸣。窄口处有一座木桥，桥头立着碉堡的影子。天光只能从顶上一条缝里漏下来。风穿谷而过，呜呜作响。"],"historyAnchor":["一九三五年九月十七日，红军在腊子口突破天险，打开北上通道。（档案）"],"characterState":["联络员趴在一块岩石后观察了很久，才回头报告——他知道，这道口子\"看着窄，其实更凶\"。"],"npc":["旁白、联络员"],"trigger":["玩家进入第 10 章，抵近腊子口时。"],"preconditions":["峡谷、绝壁、狭道；本组受领具体配合任务。"],"subtext":["他说\"就是活路\"，是怕的另一种说法——过不去，就是绝路。"],"cues":["峡谷光影窄而冷，回声让低声也显得响；玩家抬头看崖时，画面会有轻微的眩晕感（危险提示）。"],"outcomeNotes":["结果变体：无论岗位均进入观察；禁止继续生成渡江背景。"],"memory":["写入 chapter10_started = true。"],"voice":["情绪＝险峻（rugged）。联络员：低、急；旁白：沉。"]}},{"id":"10-02","nodeId":10,"part":2,"title":"观察通道与报告","sourceParagraph":1594,"opening":[{"speaker":"侦察联络员","npcId":"liaison_1","text":"我在西崖根底下猫了大半晌，一样一样报给你。","label":"侦察联络员","guards":[]}],"responses":[{"speaker":"侦察联络员","npcId":"liaison_1","text":"要我再探一回？行，只是这面坡，白日里没法攀。","label":"再探一遍崖下","guards":[],"intent":"other"},{"speaker":"侦察联络员","npcId":"liaison_1","text":"我眼皮底下的就这一段。别处的，没看见。","label":"崖底看仔细了吗？","guards":[],"intent":"status"},{"speaker":"侦察联络员","npcId":"liaison_1","text":"一座山你要望穿？办不到，我又不是千里眼。","label":"整座山的布防都报给我","guards":[],"intent":"other"},{"speaker":"侦察联络员","npcId":"liaison_1","text":"不信我的眼，换个人去看。","label":"你这报告我信不过","guards":[],"intent":"disagree"},{"speaker":"侦察联络员","npcId":"liaison_1","text":"后头这一仗怎么打，我不敢妄断。眼下这道口子的情形，方才都报过了。","label":"后面这仗怎么打？","guards":[],"intent":"history"}],"roles":{},"outcomes":[],"fallback":[{"speaker":"侦察联络员","npcId":"liaison_1","text":"窄口看清了。崖顶上雾大，望不真。","label":"","guards":[]}],"closing":[{"speaker":"侦察联络员","npcId":"liaison_1","text":"报毕。怎么定，是你的事。","label":"","guards":[]}],"metadata":{"scene":["西崖下一块凹处，侦察联络员猫着腰，手指在地上比划窄口的方位。他脸上有道新划的口子，是攀岩时蹭的。谷底的水声不断，说话要凑到近前。"],"historyAnchor":["腊子口正面有桥头碉堡扼守，两侧为陡崖，观察条件受限，情报难以完整。（档案框架）"],"characterState":["这名侦察员只认\"我亲眼见的\"；他不肯把\"猜的\"说成\"看的\"，哪怕那样听着更漂亮。"],"npc":["侦察联络员"],"trigger":["玩家派观察、或亲自侦察时。"],"preconditions":["必须讲清信息来自何处、观察到什么、尚不清楚什么。"],"subtext":["他摆石子是有意的——\"哪块石子代表哪处\"，摆错了、要说错，一眼就能看出来。","信息呈现：","来源：「靠近看的，不是隔老远猜的。」","所见：「窄口那头有桥，桥头有人守着，数目我看不真切。」","不清楚：「崖顶有没有人，我上不去，不知道。」"],"cues":["石子摆出的\"沙盘\"会随报告逐处补全，但崖顶那块石子始终空缺——直观展示\"未知\"。"],"outcomeNotes":["结果变体（不能始终提供完美全景情报）：","局部清晰：窄口情况较明，崖顶仍不明。","信息缺口：需在后续行动中承受未知。"],"memory":["写入 intel_ch10 = {来源, 所见, 未知}。"],"voice":["情绪＝机警（shrewd）。侦察联络员：低、快，字字清楚。"]}},{"id":"10-03","nodeId":10,"part":3,"title":"岗位分工","sourceParagraph":1623,"opening":[{"speaker":"何文","npcId":"he_wen","text":"老规矩，按岗位分。哪一段谁管，讲清。","label":"何文","guards":[]}],"responses":[{"speaker":"何文","npcId":"he_wen","text":"你这一段可以这样切。切完，得留一拨接应的。","label":"我的分段法子","guards":[],"intent":"plan"},{"speaker":"何文","npcId":"he_wen","text":"不合适？不合适在哪，讲出来。","label":"这么分不当","guards":[],"intent":"disagree"},{"speaker":"何文","npcId":"he_wen","text":"独闯、带突击，都不归你的岗位。守牢自己的位置。","label":"我一个人摸上去探","guards":[],"intent":"boundary"},{"speaker":"何文","npcId":"he_wen","text":"问的是自己的差事，还是旁人的？","label":"自己该守哪段，没想好","guards":[],"intent":"unclear"}],"roles":{},"outcomes":[],"fallback":[{"speaker":"何文","npcId":"he_wen","text":"按岗位切，留足接应。","label":"","guards":[]}],"closing":[{"speaker":"何文","npcId":"he_wen","text":"分定，各上各段。","label":"","guards":[]}],"metadata":{"scene":["峡口外一处岩缝避风处，本组的人挤在一起。岩壁渗水，地上湿冷。何文用脚尖划出一小块平地，把要办的事一件件摆开。头顶偶尔有碎石滚落，众人立刻贴壁。"],"historyAnchor":["攻坚配合按职务分工，各司其职，协同完成。（档案框架）"],"characterState":["何文反复强调\"你不是突击的\"，是让每个人把命放在该放的位置上。"],"npc":["何文、岗位搭档"],"trigger":["攻坚前，玩家与本组确定分工时。"],"preconditions":["四种岗位权限各异。"],"subtext":["他知道有人盼着\"冲上去立功\"，但真正的勇敢，是在自己的位置上不出错。","岗位版本：","连长：何文：「你安排基层配合、盯着联络，别自己先爬。」","战士：何文：「你完成受领的动作，跟紧前面的。」","后勤：何文：「你把绳、料送上去，保障到位。」","医护：何文：「你在下头备好接应，下来的先管。」"],"cues":["碎石滚落时众人本能贴壁，这个动作反复出现——危险不需要说，只需要\"发生\"。"],"outcomeNotes":["结果变体：分工影响后续攀爬与传令反馈。"],"memory":["写入 role_ch10 = 分工。"],"voice":["情绪＝严整（disciplined）。何文：低、清，关键词重。"]}},{"id":"10-04","nodeId":10,"part":4,"title":"玩家提交协同方案","sourceParagraph":1650,"opening":[{"speaker":"王贵","npcId":"wang_gui","text":"攀崖、传令、接应，三节棍。一节一节接给我听。","label":"王贵","guards":[]}],"responses":[{"speaker":"王贵","npcId":"wang_gui","text":"一队攻正面、一队走侧后？走侧后那一拨，谁肚子里装着那张地图？","label":"三段协同方案","guards":[],"intent":"plan"},{"speaker":"何文","npcId":"he_wen","text":"手头四样：绳、垫料、爆破的家伙、几个人。翻来覆去就这些。","label":"绳、料、爆破家伙什有哪几样？","guards":[],"intent":"status"},{"speaker":"王贵","npcId":"wang_gui","text":"要动棋子，先把理由落明白。","label":"这个协同要改","guards":[],"intent":"disagree"},{"speaker":"何文","npcId":"he_wen","text":"你要的那些，这里变不出。现有的人和家伙什，仗怎么打，你重新说。","label":"弄几门重炮轰开隘口","guards":[],"intent":"anachronism"}],"roles":{},"outcomes":[],"fallback":[{"speaker":"王贵","npcId":"wang_gui","text":"三节咬住，缺一节就断。","label":"","guards":[]}],"closing":[{"speaker":"王贵","npcId":"wang_gui","text":"照此办理。","label":"","guards":[]}],"metadata":{"scene":["岩缝里，王贵蹲着，用一块碎瓦在岩壁上划出\"正面—崖顶—接应\"三点。何文在旁边补充\"联络\"这一环。水珠顺着岩壁往下淌，把划痕冲淡。"],"historyAnchor":["腊子口攻坚采正面强攻与攀崖迂回相结合的方式，须依当时条件而无现代装备。（档案框架）"],"characterState":["王贵信\"绕后\"的机会，也信\"绕后最险\"；他不夸这法子，只说\"谁认得路\"。"],"npc":["王贵、何文"],"trigger":["玩家提交一份自由填写的协同方案后。"],"preconditions":["按联络、准备、行动衔接分析；不凭空获得重武器或现代侦察设备。"],"subtext":["他知道\"接不上\"比\"打不下\"更要命——三段接不上，前头的人就白爬了。"],"cues":["岩壁上的三点被水冲淡，玩家需不断\"重划\"——暗示计划要经得起反复推敲。"],"outcomeNotes":["结果变体：","衔接顺畅：动作连贯。","缺联络：攀爬队与接应脱节（具体反馈）。"],"memory":["写入 synergy_plan_ch10 = 要点。"],"voice":["情绪＝沉着（composed）。王贵：慢、顿；何文：稳。"]}},{"id":"10-05","nodeId":10,"part":5,"title":"攀爬／传令受阻","sourceParagraph":1675,"opening":[{"speaker":"陈小满","npcId":"chen_xiaoman","text":"崖皮太滑！我扒不住，脚底下直出溜！","label":"陈小满","guards":[]}],"responses":[{"speaker":"陈小满","npcId":"chen_xiaoman","text":"从左首绕？那边更陡，可也算条道——我试试！","label":"换左首绕上去","guards":[],"intent":"plan"},{"speaker":"联络员","npcId":"liaison_1","text":"脚底下托我一把，我上去好甩绳子。","label":"脚下给我垫把劲","guards":[],"intent":"support"},{"speaker":"陈小满","npcId":"chen_xiaoman","text":"喘匀了……成，我再扑一回。","label":"缓口气再扑一回","guards":[],"intent":"comfort"},{"speaker":"联络员","npcId":"liaison_1","text":"传令兵还没转来，上头的将令你压根没接着——先沉住气，别自作主张。","label":"传令兵没回来，等等再说","guards":[],"intent":"other"},{"speaker":"陈小满","npcId":"chen_xiaoman","text":"说我上不去？那你先爬个样子给我瞧瞧！","label":"说我不行？你来！","guards":[],"intent":"disagree"},{"speaker":"联络员","npcId":"liaison_1","text":"谁当年真爬过这道崖、崖上讲过什么话，我没凭没据，不晓得。没核实的话，不能当准话使。","label":"（要求按亲历者口述给史实台词）","guards":[],"intent":"other"}],"roles":{},"outcomes":[],"fallback":[{"speaker":"陈小满","npcId":"chen_xiaoman","text":"崖皮滑，指头抠不住。缓过这口气，再扑一回。","label":"","guards":[]}],"closing":[{"speaker":"陈小满","npcId":"chen_xiaoman","text":"上来了！绳子给你甩下去！","label":"","guards":[]}],"metadata":{"scene":["崖壁上，手脚并用，指节抠进石缝，鞋子蹬着凸起的岩棱。碎石簌簌往下掉，砸在谷底的水里。下方传来一声口令，被水声扯碎，听不真切。"],"historyAnchor":["攀崖与传令在峡谷环境中极易受阻，握力、节奏、消息传递均受影响。（档案框架）"],"characterState":["陈小满手劲不够，抓一次滑一次，却一次次再抓——他不肯成为\"被留下的人\"。"],"npc":["陈小满、联络员"],"trigger":["攀爬或传令过程中受挫时。"],"preconditions":["握力、节奏、消息迟到与实际操作一致。"],"subtext":["他说的是\"石头滑\"，其实怕的是\"我拖了后腿\"——所以宁可从别的路再试。"],"cues":["攀爬为节奏／时机玩法——抓握时机对，省力；错，滑退半步。传令未达时，屏幕上方\"命令\"栏保持空白，不允许玩家\"自己下命令\"。"],"outcomeNotes":["结果变体：","配合到位：攀爬成功、传令接上。","受阻：需重新组织或等待，不随机宣告真实人物牺牲。"],"memory":["写入 climb_result_ch10 = 结果。"],"voice":["情绪＝艰险（arduous）。陈小满：喘、颤、短；联络员：低、快。"]}},{"id":"10-06","nodeId":10,"part":6,"title":"通道打开后的整理","sourceParagraph":1701,"opening":[{"speaker":"卫生员","npcId":"medic_1","text":"出口这边我守着，出来一个，验一个。","label":"卫生员","guards":[]}],"responses":[],"roles":{},"outcomes":[],"fallback":[{"speaker":"卫生员","npcId":"medic_1","text":"打隘口撤下来的，挨个过目，伤重的就地安置。","label":"","guards":[]}],"closing":[{"speaker":"旁白","npcId":"narrator","text":"天险既破，前路豁然开阔。翻过岷山，队伍离陕北越来越近。","label":"","guards":[]}],"metadata":{"scene":["窄口过去，谷内豁然开朗一些。晨雾未散，远处的山影层层叠叠。有人靠着岩壁坐下，手还在抖。卫生员蹲着替人缠手、敷伤。地上散着绳头和碎石。"],"historyAnchor":["腊子口突破后，红军随即北上；其史实进程由档案说明。（档案）"],"characterState":["卫生员不问\"怎么打的\"，只问\"伤在哪\"——她把惊心动魄关在门外，专心做眼前的事。"],"npc":["卫生员、旁白"],"trigger":["通道打开、本章收束时。"],"preconditions":["本组任务清点与战役史实分开。"],"subtext":["她知道，这时候最该做的是\"让每个下来的人都被看见\"，而不是先庆功。","回应与呈现：","清点照料：卫生员据实处理本组人员状况。","询问现状：卫生员：「擦破的多，重的先躺。」","关心／安慰：何文：「这道口过了，后面开阔些。」","问历史／未来：旁白：「腊子口突破，是这一段的关键一步。」（档案）","异议：何文：「你觉得哪一步不妥，记到复盘。」"],"cues":["晨雾中的峡口渐渐明亮，队伍默默收拾绳料——收尾的安静与攻坚的喧嚣形成对照。"],"boundary":["","本组虚构任务：清点与整理。","历史线（旁白）：腊子口战役史实（档案）。","不把本关所有可选分支都写成同一个\"大捷\"；据实反馈可选分支。"],"outcomeNotes":["结果变体：只评价本组任务，不评价真实战果。"],"memory":["写入 marchLog += ch10。"],"voice":["情绪＝紧绷后松弛（taut-then-slack）。卫生员：稳、实；旁白：平。"]}},{"id":"11-01","nodeId":11,"part":1,"title":"抵达陕北背景","sourceParagraph":1732,"opening":[{"speaker":"旁白","npcId":"narrator","text":"一九三五年十月，中央红军到达陕北吴起镇。一支走了整整一年的队伍，终于落脚。","label":"旁白","guards":[]},{"speaker":"何文","npcId":"he_wen","text":"到了，是落脚，不是团圆。各路的人马，还在路上走着。","label":"何文","guards":["conditional"]}],"responses":[{"speaker":"何文","npcId":"he_wen","text":"头一桩，找地方安顿、休整，把这一程的尾收利索。","label":"到这儿之后，头一件做什么？","guards":[],"intent":"status"},{"speaker":"何文","npcId":"he_wen","text":"先安顿人，还是先接通地方上的联络？两桩都得办，讲个先后。","label":"先安顿还是先联络，我排了","guards":[],"intent":"plan"},{"speaker":"何文","npcId":"he_wen","text":"大会师在明年，急不出个早字来。眼下的正事，是把手头安顿妥帖。","label":"这就算三大主力会师了吧？","guards":[],"intent":"other"},{"speaker":"何文","npcId":"he_wen","text":"初到生地方，心里空落落的，不碍。住下几天就实了。","label":"到了新地界，心里空落落的","guards":["conditional"],"intent":"fear"},{"speaker":"何文","npcId":"he_wen","text":"你想问的是安顿，还是队伍？","label":"（想问的没问明白）","guards":[],"intent":"unclear"}],"roles":{},"outcomes":[],"fallback":[{"speaker":"何文","npcId":"he_wen","text":"落脚是真的。齐到一起，还早。","label":"","guards":[]}],"closing":[{"speaker":"何文","npcId":"he_wen","text":"先寻个歇脚的地界。","label":"","guards":[]}],"metadata":{"scene":["吴起镇外的黄土坡。沟壑纵横，山是黄褐色的，天却很高很蓝。坡上散着几孔窑洞，炊烟直上。路边的酸枣树挂着红果，风是干的，吹得人脸上发紧。队伍沿着坡道慢慢下来。"],"historyAnchor":["一九三五年十月，中央红军到达陕北吴起镇，长征结束；次年十月三大主力才先后会师。（档案）"],"characterState":["何文到了这里，肩膀才真正松下来一点；但他仍强调\"这是落脚，不是全到齐了\"，因为后头的队伍还在路上。"],"npc":["旁白、何文"],"trigger":["玩家进入第 11 章，抵达吴起镇一带时。"],"preconditions":["本关为中央红军到达陕北；会师为后续章节（次年）。"],"subtext":["他怕有人此刻就以为\"大功告成\"——真正的会合，还要再等一年。"],"cues":["镜头从黄土沟壑摇到窑洞门前的红辣椒串；干风、蓝空、黄坡——三个色块立住\"陕北\"。"],"outcomeNotes":["结果变体：进入安置流程；禁止提前宣布三大主力会师。"],"memory":["写入 chapter11_started = true；not_yet_all_joined = true。"],"voice":["情绪＝疲惫后落定（weary-settling）。何文：舒缓、尾音松；旁白：平、远。"]}},{"id":"11-02","nodeId":11,"part":2,"title":"与当地接洽","sourceParagraph":1756,"opening":[{"speaker":"联络员","npcId":"liaison_1","text":"远道来的同志，先拣要紧的讲——来了多少人？要几孔窑？","label":"当地联络员","guards":[]}],"responses":[{"speaker":"联络员","npcId":"liaison_1","text":"咱这搭儿粮食也紧巴，能匀的有限，你给个数。","label":"村里还能匀出多少粮？","guards":[],"intent":"status"},{"speaker":"联络员","npcId":"liaison_1","text":"先安置老弱？成，我领你去看几孔空窑。","label":"安置的法子我拟了","guards":[],"intent":"plan"},{"speaker":"联络员","npcId":"liaison_1","text":"你们受的苦，村里都知道。可咱这搭儿，也得量力而行。","label":"一路辛苦乡亲们了","guards":[],"intent":"comfort"},{"speaker":"联络员","npcId":"liaison_1","text":"嫌不够？咱也就这一锅饭，大伙挤一挤。","label":"这点粮食可不够","guards":[],"intent":"disagree"},{"speaker":"联络员","npcId":"liaison_1","text":"家家锅里都照得见人影，几十石粮是真拿不出。得商量着办。","label":"让全村都把粮交出来","guards":[],"intent":"other"}],"roles":{},"outcomes":[],"fallback":[{"speaker":"联络员","npcId":"liaison_1","text":"粮食紧巴。人多少？要几孔窑？","label":"","guards":[]}],"closing":[{"speaker":"联络员","npcId":"liaison_1","text":"跟我走，先相一相那几孔空窑。","label":"","guards":[]}],"metadata":{"scene":["一孔窑洞前的小院。院里有石碾、水缸、几串苞谷。当地一位中年汉子迎出来，手里还攥着半把没打完的豆荚。他身后，一个娃娃扒着门框偷看。"],"historyAnchor":["中央红军到达陕北后，与当地群众、地方组织接洽安置事宜。（档案框架）"],"characterState":["当地联络员是实在人，家里也不宽裕；他愿帮，但也要你把\"要多少\"说清楚。"],"npc":["群众／当地联络员（虚构）"],"trigger":["玩家与当地人接洽安置时。"],"preconditions":["需询问安置条件、表达来意、尊重群众；不把群众写成无限粮仓。"],"subtext":["他先问\"人多少、地多大\"，不是推脱，是怕答应了却办不到——他对红军是真心，也要量力。"],"cues":["说到\"空窑\"时，镜头扫过几孔塌了半边的旧窑；说到\"粮不宽裕\"时，可给一眼院角的粮囤——空了大半。"],"outcomeNotes":["结果变体：","尊重协商：安置顺利，关系融洽。","强索物资：触发当地为难，关系受损（具体反馈）。"],"boundary":["不冒用真实人物身份；不把群众写成无条件无限物资的工具人。"],"memory":["写入 local_rel_ch11 = 关系值。"],"voice":["情绪＝朴实、客气（homely-deferential）。当地联络员：陕北口音、慢、实在。"]}},{"id":"11-03","nodeId":11,"part":3,"title":"分配住宿和现有物资","sourceParagraph":1782,"opening":[{"speaker":"后勤协作员","npcId":"logistics_1","text":"窑洞拢共这几孔，铺草、口粮、伤员的药垫，全得排个次序出来。","label":"后勤协作员","guards":[]}],"responses":[{"speaker":"后勤协作员","npcId":"logistics_1","text":"伤员挪暖窑，这个安排在理。那剩下的人就得肩挨肩挤一挤。","label":"住处物资我排了单子","guards":[],"intent":"plan"},{"speaker":"卫生员","npcId":"medic_1","text":"挑一孔干燥背风的窑洞给伤员，换药、烧水都便利。","label":"伤病员安置好了吗？","guards":[],"intent":"comfort"},{"speaker":"后勤协作员","npcId":"logistics_1","text":"不挤？几孔窑装几十号人，你给我变出窟窿来？","label":"这么分住不妥","guards":[],"intent":"disagree"},{"speaker":"后勤协作员","npcId":"logistics_1","text":"铺草几捆、口粮几袋、柴火几垛，全在单子上，以实数为准。","label":"窑洞、铺草还有多少？","guards":[],"intent":"status"},{"speaker":"后勤协作员","npcId":"logistics_1","text":"你要先把谁安置下去？","label":"（先安置谁，没说清）","guards":[],"intent":"unclear"}],"roles":{},"outcomes":[],"fallback":[{"speaker":"后勤协作员","npcId":"logistics_1","text":"窑洞有数，伤员第一。","label":"","guards":[]}],"closing":[{"speaker":"后勤协作员","npcId":"logistics_1","text":"就这么排，我去抱铺草。","label":"","guards":[]}],"metadata":{"scene":["几孔窑洞前，后勤协作员把要送进去的东西排开：铺草、几口粮、一点柴火、伤员要用的布条。窑洞里黑，洞口透进来的光把地面照出一条亮的通道。"],"historyAnchor":["到达陕北后队伍安置困难，住宿与物资需按人数、体力与库存统筹。（档案框架）"],"characterState":["后勤协作员这回难得地\"松\"了一点——终于有个能遮风的地方，他把伤员往最暖的窑洞里排。"],"npc":["后勤协作员、卫生员"],"trigger":["玩家拖拽人员、物资到安置方案时。"],"preconditions":["根据人数、体力与库存处理取舍；拖拽操作影响具体反馈。"],"subtext":["他嘴上还是\"都得排\"，动作却是先把最暖的窑留给伤员——心比嘴软。"],"cues":["拖拽时，窑洞的\"床位\"逐格填满；伤员优先则暖窑先满，物资分散则各窑渐满——两种结果在画面上清晰不同。"],"outcomeNotes":["结果变体（拖拽影响反馈）：","伤员优先：照料到位，体壮者挤些。","物资分散：无短板，但都不宽裕。","不同拖拽组合给出不同的具体反馈。"],"memory":["写入 billet_plan_ch11 = 方案。"],"voice":["情绪＝操持（busy-managing）。后勤协作员：快、实；卫生员：轻、稳。"]}},{"id":"11-04","nodeId":11,"part":4,"title":"自由整顿方案","sourceParagraph":1808,"opening":[{"speaker":"何文","npcId":"he_wen","text":"整顿的次序，你来排。哪件头前走，哪件压后头。","label":"何文","guards":[]}],"responses":[{"speaker":"王贵","npcId":"wang_gui","text":"先歇整后联络？行。只是信送晚了，外头什么风声都摸不着。","label":"整顿的先后我排好了","guards":[],"intent":"plan"},{"speaker":"何文","npcId":"he_wen","text":"人手、物件，摊开就眼前这些。照这个排。","label":"人手物件现有什么底？","guards":[],"intent":"status"},{"speaker":"何文","npcId":"he_wen","text":"顺序要换？理由讲出来。","label":"顺序要换，我说说","guards":[],"intent":"disagree"},{"speaker":"何文","npcId":"he_wen","text":"根据地怎么经营，自有定盘星。咱们管的，是本组这摊整顿。","label":"根据地怎么经营，我提个纲领","guards":[],"intent":"other"}],"roles":{},"outcomes":[],"fallback":[{"speaker":"何文","npcId":"he_wen","text":"休整、联络、照料、整理——先后你排。","label":"","guards":[]}],"closing":[{"speaker":"何文","npcId":"he_wen","text":"就依你定的办。","label":"","guards":[]}],"metadata":{"scene":["窑洞外的小院，日头偏西。何文和王贵蹲在碾盘边，何文在地上列\"整顿\"的条目：休整、联络、照料、物资整理。院里的娃娃远远看着，不敢过来。"],"historyAnchor":["落脚后需统筹休整、联络、照料与物资整理的次序。（档案框架）"],"characterState":["何文难得话多，一项一项说；王贵只偶尔插一句\"人得先歇过来\"——两人各有侧重。"],"npc":["何文、王贵"],"trigger":["玩家提交一份自由填写的整顿方案后。"],"preconditions":["讨论休整、联络、照料、物资整理的优先顺序。"],"subtext":["这是他最愿意听你说的一件事——因为这里，终于可以\"慢慢来\"了。"],"cues":["地上的条目会随排序重排位置；\"休整\"排前时，画面里的人陆续坐下——让\"优先\"看得见。"],"outcomeNotes":["结果变体：","先休整：人恢复快，但外联滞后。","先联络：信息灵，但人乏。","先整理物资：底数清，但人还累着。"],"memory":["写入 rectify_plan_ch11 = 顺序。"],"voice":["情绪＝沉稳（sedate）。何文：稳、缓；王贵：沙、慢。"]}},{"id":"11-05","nodeId":11,"part":5,"title":"回应一路承诺","sourceParagraph":1834,"opening":[{"speaker":"陈小满","npcId":"chen_xiaoman","text":"打于都那晚起，一步一步挪到这儿……你记不记得，出发头天你应过我什么？","label":"陈小满","guards":[]}],"responses":[],"roles":{},"outcomes":[],"fallback":[{"speaker":"陈小满","npcId":"chen_xiaoman","text":"能走到这儿，谁不是咬着牙过来的。","label":"","guards":[]}],"closing":[{"speaker":"陈小满","npcId":"chen_xiaoman","text":"歇着吧，明日还有明日的事。","label":"","guards":[]}],"metadata":{"scene":["窑洞前的坡地，天边烧着晚霞，把黄土坡染成暖红色。陈小满坐在一截矮墙上，把磨破的草鞋脱下来翻看。风不大，能听见院里水缸边的说话声。"],"historyAnchor":["中央红军到达陕北后，队伍休整、整理；其意义由档案说明。（档案）"],"characterState":["陈小满一路走到这里，长高了些，也沉稳了些；但他心里那个\"于都的承诺\"，一直没放下。"],"npc":["陈小满"],"trigger":["安置闲暇，与陈小满回顾一路时。"],"preconditions":["调用第一章及中途记录；可有感激、疑问或遗憾，不能无论经历如何都热情赞扬。"],"subtext":["他故意不抬头，是怕你看他眼睛——这话在他心里放了一路，说出来需要勇气。","回应（依记录分支）：","若有 `helped_ally_ch01`／`care_chen_ch08` 等帮助记录：陈小满：（抬头）「那几回你搭把手，我记着。到了这儿，我得跟你说声谢。」","若有 `promise_01` 且已兑现：陈小满：「你答应的，你真做了。这话我信你。」","若有 `promise_01` 未兑现：陈小满：（把草鞋翻来覆去）「你那天说过的……后来没提。我不怪你，可心里搁着。」","若无相关记录：陈小满：「走到这儿，各自都不容易。」（不编造共同经历）","关心／安慰：陈小满：「你想家不？我有点想。」","问历史／未来：旁白：「后事另有档案。」（不预知）"],"cues":["晚霞的光从坡顶一点点收下去；说到\"没提\"时，陈小满会把草鞋放回膝上，动作慢下来。"],"outcomeNotes":["结果变体：据实分支，禁止一律热情赞扬。"],"memory":["读 promise_01、helped_ally_ch01、care_chen_ch08；写 relationship_chen = 终值。"],"voice":["情绪＝温情中带克制（tender-restrained）。陈小满：低、慢，尾音稳；不哭腔，但要有\"憋着\"的感觉。"]}},{"id":"11-06","nodeId":11,"part":6,"title":"阶段回顾与后续时间转场","sourceParagraph":1858,"opening":[{"speaker":"旁白","npcId":"narrator","text":"纵横十一省，行程二万五千里——到这一刻，中央红军的长征暂告一段落。","label":"旁白","guards":[]},{"speaker":"何文","npcId":"he_wen","text":"这一程，算是有个交代了。","label":"何文","guards":[]}],"responses":[],"roles":{},"outcomes":[],"fallback":[{"speaker":"旁白","npcId":"narrator","text":"这一程到这里走完了。三大主力的会面，还要再等一年。","label":"","guards":[]}],"closing":[{"speaker":"旁白","npcId":"narrator","text":"队伍在陕北扎下根来。日历，一页页翻向一九三六年。","label":"","guards":[]}],"metadata":{"scene":["夜色里的吴起镇，窑洞亮起一盏盏油灯，像黄土坡上散落的星。远处传来山歌的调子，断断续续。风很轻。这是长征路上少有的安宁之夜。"],"historyAnchor":["一九三五年十月，中央红军到达陕北，长征告一段落；三大主力会师在次年十月。（档案）"],"characterState":["何文站在窑洞口，望着这片灯火——他一路上第一次露出\"能睡个整觉\"的神情。"],"npc":["旁白、何文"],"trigger":["本章收束，转入后续时间点前。"],"preconditions":["说明这一阶段的意义；后续不同日期事件单独标注。"],"subtext":["他说的\"交代\"，是给那些没走到这里的人的交代——这一句，要留白。","回应与呈现：","阶段意义：旁白据档案说明中央红军到达陕北的历史意义。","时间转场提示：明确后续章节（会师）发生在次年，不在抵达当晚一并发生。","询问现状：何文：「今晚就是休整，别的明天再说。」","关心／安慰：何文：（伸了个懒腰）「歇下来，才觉得浑身散架。」","异议：何文：「你觉得该早些联络别的队伍？我记下，明天办。」"],"cues":["镜头缓缓拉远，窑洞灯火渐成星点，黑场，再浮现\"一九三六年十月\"——用画面完成时间转场，杜绝\"当天会师\"的错觉。"],"boundary":["","本组虚构任务：整顿完成度。","历史线（旁白）：中央红军到达陕北的意义（档案）。","不在抵达当晚一并发生次年事件。"],"outcomeNotes":["结果变体：明确\"是夜\"与\"次年\"的时间分层。"],"memory":["写入 marchLog += ch11；timeline_next = 1936-10 会师。"],"voice":["情绪＝告一段落（chapter-closing）。何文：舒缓、长出一口气；旁白：沉稳、有历史的厚度。"]}},{"id":"12-01","nodeId":12,"part":1,"title":"时间转场","sourceParagraph":1890,"opening":[{"speaker":"旁白","npcId":"narrator","text":"自吴起镇落脚算起，将近一年过去。一九三六年秋，各路红军先后向会宁一带集结。","label":"旁白","guards":[]},{"speaker":"旁白","npcId":"narrator","text":"过草地时省下的那口口粮，你说过要留给更需要的同志。如今三军齐聚，这笔约定，是时候当面清了。","label":"回响·草地预留","guards":[],"echo":"9-reserve","echoHint":"（行记里记着这一笔）"},{"speaker":"旁白","npcId":"narrator","text":"草地里约下的那个联络信号，此刻正派上用场——各路队伍能在这片黄土坡上彼此相认，靠的就是一个一个约好的记号。","label":"回响·草地信号","guards":[],"echo":"9-signal","echoHint":"（行记里记着这一笔）"}],"responses":[],"roles":{},"outcomes":[],"fallback":[{"speaker":"旁白","npcId":"narrator","text":"一九三六年十月，会宁。三支主力先后进城，汇成一股。","label":"","guards":[]}],"closing":[{"speaker":"旁白","npcId":"narrator","text":"接应的人先到，会师的队伍后至。城门内外，挤满了彼此打量的人。","label":"","guards":[]}],"metadata":{"scene":["画面从上一章的窑洞灯火黑场，缓缓浮现出一九三六年十月的黄土坡。秋高气爽，天蓝得发亮。路边的白杨叶子黄了，风一吹，哗哗作响。远处大路上，隐约有队伍行进扬起的尘土。"],"historyAnchor":["一九三六年十月，红军三大主力先后在会宁、将台堡等地会师。（档案）"],"characterState":["旁白把时间交底，角色们回到当下——没有人\"记得\"这一年具体发生了什么，他们只是刚走到这里。"],"npc":["旁白"],"trigger":["玩家进入第 12 章开头。"],"preconditions":["明确1936 年 10 月背景。"],"subtext":["（旁白无潜台词，语气要求：平实、有分量，不煽情。）","回应与呈现：","明确转场：不能让玩家从吴起镇直接无说明地跳成\"同一天会师\"。","玩家询问历史：旁白据档案说明会师的时间与地点分布。","玩家询问现状：旁白：「此刻，各路队伍正陆续向会师地点汇合。」","简短输入／问号：旁白：「你是想问时间，还是想问地点？」"],"cues":["用画面完成时间跳跃：窑洞灯火 → 黑场 → 秋日白杨与远处队伍扬尘。严禁直接切到\"会师现场\"而不说明时间。"],"outcomeNotes":["结果变体：转场无失败态；硬性禁止压缩时间造成\"当天会师\"的错觉。"],"memory":["写入 chapter12_started = true；timeline = 1936-10。"],"voice":["情绪＝庄重、期待（solemn-anticipant）。旁白：沉稳、清楚。"]}},{"id":"12-02","nodeId":12,"part":2,"title":"接应来人和核对信息","sourceParagraph":1912,"opening":[{"speaker":"联络员甲","npcId":"role_partner","text":"我们是另一路开过来的，跟你们不同队。先把番号对上。","label":"联络员甲","guards":[]}],"responses":[{"speaker":"联络员甲","npcId":"role_partner","text":"我们到的是那一头，你们在的这一头，连日子都对着不一样。","label":"你们那边，日子对得上吗？","guards":[],"intent":"status"},{"speaker":"联络员乙","npcId":"role_partner","text":"两处的消息并成一处？成。可千万别并成同一天的事。","label":"两处的消息合起来对一对","guards":["quantity"],"intent":"plan"},{"speaker":"联络员甲","npcId":"role_partner","text":"我讲的跟你听的对不上？那就一样一样核，急不得。","label":"你说的跟我们对不上","guards":[],"intent":"disagree"},{"speaker":"联络员甲","npcId":"role_partner","text":"一路两年，你没全赶上。没见着的事，不能说成亲眼见的。","label":"这一路的事我都亲历了","guards":["conditional"],"intent":"other"},{"speaker":"联络员乙","npcId":"role_partner","text":"你问的是哪一路？","label":"（问的是哪一路，没说清）","guards":[],"intent":"unclear"}],"roles":{},"outcomes":[],"fallback":[{"speaker":"联络员甲","npcId":"role_partner","text":"另一路来的，先对番号。","label":"","guards":[]}],"closing":[{"speaker":"联络员甲","npcId":"role_partner","text":"号对上了，再谈安置不迟。","label":"","guards":[]}],"metadata":{"scene":["一条黄土大路边，几支队伍从不同方向汇聚。彼此军装的颜色深浅不一，草鞋样式也不同。有人相互打量，有人交换着打听消息。路边的水桶边围着一圈人，轮流喝水。"],"historyAnchor":["会师涉及不同方面军与不同地点，队伍此前未必相识，信息需核对。（档案框架）"],"characterState":["联络员甲来自另一路，他不认得眼前这些人，也不装认得；他先把\"番号\"对上，再说别的。"],"npc":["不同队伍的虚构联络员、岗位搭档"],"trigger":["玩家接应几路来人、核对信息时。"],"preconditions":["信息涉及不同队伍和会师地点；不暗示主角一路跟随所有方面军亲历全部事件。"],"subtext":["他先划清\"不是一支\"，不是生分，是怕把不同队伍的功劳记混了。"],"cues":["不同队伍的\"辨识物\"（绑腿颜色、斗笠样式、草鞋编法）可作视觉符号，帮助区分\"不是一支\"。"],"outcomeNotes":["结果变体：核对结果分\"对得上／待核／有出入\"，据实反馈。"],"boundary":["不暗示主角一路跟随所有方面军亲历全部事件。"],"memory":["写入 info_check_ch12 = 结果。"],"voice":["情绪＝务实、郑重（pragmatic-solemn）。联络员甲：中速、清楚；乙：略急、直。"]}},{"id":"12-03","nodeId":12,"part":3,"title":"会宁与将台堡资料整理","sourceParagraph":1936,"opening":[{"speaker":"何文","npcId":"he_wen","text":"左手这摞是会宁的，右手那摞是将台堡的。两摞，不许掺。","label":"何文","guards":[]}],"responses":[],"roles":{},"outcomes":[],"fallback":[{"speaker":"何文","npcId":"he_wen","text":"会宁一摞、将台堡一摞，掺了就乱。","label":"","guards":[]}],"closing":[{"speaker":"何文","npcId":"he_wen","text":"分明白了，我呈上去。","label":"","guards":[]}],"metadata":{"scene":["一处临时指挥所，桌上摆着两摞材料，分别用麻绳捆着，纸角写着不同的地名。窗外是秋日的黄土坡。何文把两摞往里推了推，用镇纸压住。"],"historyAnchor":["会宁会师与将台堡会师是两地、若不同日的史实，材料须分别整理。（档案）"],"characterState":["何文最忌\"图省事把两处合一\"，他反复提醒\"分开摆\"，是对史实的敬畏。"],"npc":["何文、旁白"],"trigger":["玩家整理两处会师相关材料时。"],"preconditions":["两处会师材料分别展示。"],"subtext":["他知道\"混\"了会怎样——历史一旦被摊成\"一天一场\"，就失真了。","回应与呈现：","分别整理：两个地点、不同日期的材料分开归整。","询问现状：何文：「两处的时辰、地点不一样，你分开记。」","玩家试图合并：何文：「合成一次？不合史实。分开摆。」","问历史：旁白据档案分别说明会宁、将台堡会师。","简短输入／问号：何文：「你问哪一处？」"],"cues":["两摞材料始终分置桌面两侧，不出现\"合并成一摞\"的操作可能——用交互本身守住史实。"],"outcomeNotes":["结果变体：材料归整正确／混放，据实反馈。"],"boundary":["不合并为同一日、同一地点的一次场面。"],"memory":["写入 archive_ch12 = {会宁, 将台堡}。"],"voice":["情绪＝郑重（dignified）。何文：稳、清，强调\"分开\"二字。"]}},{"id":"12-04","nodeId":12,"part":4,"title":"玩家安排接应与保障","sourceParagraph":1960,"opening":[{"speaker":"后勤协作员","npcId":"logistics_1","text":"会师在即，来的人马不少。粮秣、住处、伤号安置，三大摊，你统筹。","label":"后勤协作员","guards":[]}],"responses":[{"speaker":"后勤协作员","npcId":"logistics_1","text":"远道而来的先安顿，对，他们脚底板熬得最狠。","label":"接应保障的章程","guards":[],"intent":"plan"},{"speaker":"卫生员","npcId":"medic_1","text":"一路转战过来的伤号只会多不会少，铺草和盐水得提前备足。","label":"伤号安置想周全了吗？","guards":[],"intent":"comfort"},{"speaker":"后勤协作员","npcId":"logistics_1","text":"不先顾远道的？把你的道理摆出来听听。","label":"这样安排欠妥","guards":[],"intent":"disagree"},{"speaker":"后勤协作员","npcId":"logistics_1","text":"存粮几担、空窑几孔、能出力的人几个，账面上都是现成的。","label":"来的人马粮草够不够？","guards":[],"intent":"status"},{"speaker":"何文","npcId":"he_wen","text":"会师是写定了的大事，轮不到改。你安排的，是咱们这一组怎么把它伺候好——别把主次弄颠倒。","label":"会师的事，我想改一改安排","guards":[],"intent":"other"}],"roles":{},"outcomes":[],"fallback":[{"speaker":"后勤协作员","npcId":"logistics_1","text":"粮、窑、伤号，三条线你先排。","label":"","guards":[]}],"closing":[{"speaker":"后勤协作员","npcId":"logistics_1","text":"方案准了，我去张罗草料。","label":"","guards":[]}],"metadata":{"scene":["会师地点附近的村口，几间土房、一口水井、一片打谷场。远道而来的队伍陆陆续续进村，尘土扬起又落下。后勤协作员在水井边张罗，卫生员在土房里铺开铺位。"],"historyAnchor":["会师时需安排物资、安置、联络与任务交接等保障工作。（档案框架）"],"characterState":["后勤协作员这回终于能\"放开手\"一点——但他仍记着\"粮是按实有算的\"，不敢松口。"],"npc":["后勤协作员、卫生员"],"trigger":["玩家提交一份自由填写的接应与保障方案后。"],"preconditions":["涉及物资、安置、联络、任务交接；不改变真实会师事实。"],"subtext":["他嘴上问\"你安排\"，其实心里高兴——这一年，队伍终于壮大了。"],"cues":["进村的队伍一批批增加，水井边的人越聚越多；安置是否到位，会直接反映在\"还有没有人站着没安排\"上。"],"outcomeNotes":["结果变体：方案影响本组服务水平，不改变真实会师事实。"],"memory":["写入 support_plan_ch12 = 要点。"],"voice":["情绪＝热切、有序（fervent-orderly）。后勤协作员：快、亮；卫生员：稳。"]}},{"id":"12-05","nodeId":12,"part":5,"title":"战友重逢／彼此介绍","sourceParagraph":1983,"opening":[{"speaker":"陈小满","npcId":"chen_xiaoman","text":"这位同志，好生面熟……咱们是不是在哪条河、哪座山碰过面？","label":"陈小满","guards":[]}],"responses":[],"roles":{},"outcomes":[],"fallback":[{"speaker":"王贵","npcId":"wang_gui","text":"乱世里能再碰头，就是天大的缘分。坐下，慢慢叙。","label":"","guards":[]}],"closing":[{"speaker":"陈小满","npcId":"chen_xiaoman","text":"来来来，挨着坐。这一路没说尽的话，今夜慢慢摆。","label":"","guards":[]}],"metadata":{"scene":["打谷场上，各路人马混在一处歇脚。有人蹲在地上抽烟，有人互相递水。突然，有人在一堆生脸里认出一张熟脸，愣了一下，试探着喊了个名字。"],"historyAnchor":["会师时不同队伍此前未必相识，重逢与否取决于是否真有共同经历。（档案框架）"],"characterState":["陈小满既盼着\"见到熟人\"，又怕认错人；他站在原地，先在记忆里翻找。"],"npc":["王贵、陈小满、新队伍虚构战友"],"trigger":["各路来人相见时。"],"preconditions":["仅有经历记录支持时才写\"重逢\"；此前未见者应为相识。"],"subtext":["他半是期待、半是不确定——这是他这一路第一次主动\"找熟人\"。","回应（严格依记录）：","若有同队经历记录（如陈小满与某位一路同行）：写重逢，据实回顾共同经历。","若无记录（新队伍来人）：写相识——新战友自我介绍，不自动认识每个人。","玩家询问现状：新战友：「我们那一路跟你们不是一道，头回见。」","关心／安慰：王贵：「见着了就是缘分，坐下说。」","异议：陈小满：「你说你认得他？我怎么没印象。」","问历史／未来：旁白：「后事另有档案。」（不预知）"],"cues":["重逢与相识要用不同镜头语言区分：重逢是快步上前、紧紧握手；相识是抱拳、自我介绍、略带拘谨。"],"outcomeNotes":["结果变体：重逢（有据）／相识（无据）两条路必须区分。"],"boundary":["不自动认识每个人。"],"memory":["读相关经历记录；写 relationships_final = {...}。"],"voice":["情绪＝温热、感慨（warm-moved）。陈小满：从试探到惊喜／或略失望；王贵：低沉带笑。"]}},{"id":"12-06","nodeId":12,"part":6,"title":"终章行记与历史回望","sourceParagraph":2008,"opening":[{"speaker":"旁白","npcId":"narrator","text":"红一、二、四方面军会聚会宁。长征，至此胜利结束。","label":"旁白","guards":[]},{"speaker":"何文","npcId":"he_wen","text":"打于都那晚到今天，你每一步怎么迈的，行记上都摊着。","label":"何文","guards":[]}],"responses":[],"roles":{},"outcomes":[],"fallback":[{"speaker":"何文","npcId":"he_wen","text":"这一路的脚印，行记都替你收着。","label":"","guards":[]}],"closing":[{"speaker":"旁白","npcId":"narrator","text":"火种还在，路还长。往后的故事，自有后来人接着写。","label":"","guards":[]}],"metadata":{"scene":["傍晚的打谷场，炊烟升起。各路人马围着几堆火坐成一圈，火光把一张张年轻的脸照亮。远处，夕阳沉进黄土沟壑。有人轻声唱起了歌，调子很慢。"],"historyAnchor":["一九三六年十月，三大主力会师，长征胜利结束。（档案）"],"characterState":["何文站在人群外，看着这一圈火与一屋人——他想起于都河边那个傍晚，那时也是这样的暮色，只是少了太多人。"],"npc":["旁白、何文"],"trigger":["全章收束，终章行记时。"],"preconditions":["回顾玩家跨章选择、兑现承诺和协作；历史结局固定。"],"subtext":["他心里那句没说的，是\"能走到这儿的人，都该被记住\"。","回应与呈现：","跨章回顾：旁白／何文据实串起玩家的整条行动链与关系变化。","承诺核查汇总：列出玩家实际兑现与未兑现的承诺，据实呈现。","玩家询问历史：旁白据档案说明会师意义。","关心／安慰：何文：「这段路，走到头了。」","要求\"超越真实长征\"的评价：旁白：「你这一局损耗低，是你把事安排得好；这不等于超越了真实长征。当年的人，是在真实的枪炮和饥寒里走过来的。」"],"cues":["镜头从火圈缓缓拉高、拉远，越过黄土沟壑，落在一片星空上——把\"个人的长征\"交还给\"历史的长征\"。"],"boundary":["","本组虚构任务：跨章行记（据实）。","历史线（旁白）：三大主力会师与长征胜利的史实（档案）。","不将模拟较低损耗包装成\"超越真实长征\"；历史结局固定。"],"outcomeNotes":["结果变体：终章无评分，只有据实的行记与史实并置。"],"memory":["写入 marchLog += ch12；game_complete = true。"],"voice":["情绪＝庄重、悠远（solemn-resonant）。何文：低、慢，收在留白里；旁白：沉稳、有分量，末句\"星火不熄\"不加颤音。"]}}],"echoes":{"version":1,"note":"回响行（echo 字段）均为虚构创作对白：按玩家在先前站点的结构化选择（npc_dialogue_v1 分支与 storyPreparations 决策行）条件插入；无记录自然降级，不改变真实历史进程。","groups":[{"id":"xiangjiang-zunyi","from":2,"to":3,"keys":["2-share","2-reserve"]},{"id":"snowmount-grassland","from":8,"to":9,"keys":["8-share","8-keep"]},{"id":"grassland-huining","from":9,"to":12,"keys":["9-signal","9-reserve"]}]}};
